window.__BOOK__={"meta": {"title_fr": "Le Petit Prince", "title_zh": "小王子", "author_fr": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "fr-FR-DeniseNeural (edge-tts)", "ipa_note": "音标为宽式音位转写（法语近似发音，不标重音、不处理联诵），仅供参考。", "n_chapters": 28, "n_paras": 783, "n_sents": 1653, "audio_paras": 783}, "chapters": [{"id": "ch00", "title_fr": "À Léon Werth", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"fr": "À Léon Werth.", "zh": "请孩子们原谅我把这本书献给一位大人。", "t": [100, 1962]}, {"fr": "Je demande aux enfants de m'excuser de dédier ce livre à une grande personne.", "zh": "请孩子们原谅我把这本书献给一位大人。", "t": [1962, 6538]}, {"fr": "J'ai une excuse sérieuse : cette grande personne est le meilleur ami que j'ai au monde.", "zh": "我有这样做的充分理由：这位大人是我最要好的朋友。", "t": [6538, 11725]}, {"fr": "J'ai une autre excuse : cette grande personne peut tout comprendre, même les livres pour enfants.", "zh": "我还有另一个理由：这位大人什么都懂，他完全能理解写给孩子们阅读的书籍。", "t": [11725, 17450]}, {"fr": "J'ai une troisième excuse : cette grande personne habite la France où elle a faim et froid.", "zh": "我还有第三个理由：这位大人住在法国，正在忍饥挨饿，他需要别人的安慰。", "t": [17450, 22900]}, {"fr": "Elle a besoin d'être consolée.", "zh": "我还有第三个理由：这位大人住在法国，正在忍饥挨饿，他需要别人的安慰。", "t": [22900, 25388]}, {"fr": "Si toutes ces raisons ne suffisent pas, je veux dédier ce livre à l'enfant qu'a été autrefois cette grande personne.", "zh": "要是你们认为这些理由还不充分，那我就把这本书献给小时候的他吧——所有的大人都经历过童年。", "t": [25388, 31550]}, {"fr": "Toutes les grandes personnes ont d'abord été des enfants.", "zh": "（但很少有大人记得自己曾是孩子。", "t": [31550, 34662]}, {"fr": "(Mais peu d'entre elles s'en souviennent.) Je corrige donc ma dédicace : À LEON WERTH, QUAND IL ÉTAIT PETIT GARÇON.", "zh": "）因此，我把我的献辞改为： 献给从前那个小男孩列翁·维尔特。", "t": [34662, 41287]}]}]}, {"id": "ch01", "title_fr": "Chapitre I", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"fr": "Lorsque j’avais six ans j’ai vu, une fois, une magnifique image, dans un livre sur la Forêt Vierge qui s’appelait \"Histoires Vécues\".", "zh": "六岁那一年，我在一本描写原始森林的书里看见一幅扣人心弦的图画。", "t": [100, 7875]}, {"fr": "Ça représentait un serpent boa qui avalait un fauve.", "zh": "那本书的书名叫做“丛林奇遇记”。", "t": [7875, 11488]}, {"fr": "Voilà la copie du dessin.", "zh": "图中画的是正在吞吃野兽的蟒蛇。", "t": [11488, 12938]}]}, {"id": "ch01p01", "audio": true, "sents": [{"fr": "On disait dans le livre : \"Les serpents boas avalent leur proie tout entière, sans la mâcher.", "zh": "下面是这幅画的复印件。", "t": [100, 6088]}, {"fr": "Ensuite ils ne peuvent plus bouger et ils dorment pendant les six mois de leur digestion\".", "zh": "书中说：“蟒蛇囫囵吞下猎物，肚子撑得它不能动弹，要躺六个月才能把猎物消化掉。", "t": [6088, 10013]}]}, {"id": "ch01p02", "audio": true, "sents": [{"fr": "J’ai alors beaucoup réfléchi sur les aventures de la jungle et, à mon tour, j’ai réussi, avec un crayon de couleur, à tracer mon premier dessin.", "zh": "” 从此，我对丛林的种种奇事产生了无穷尽的遐想。", "t": [100, 9025]}, {"fr": "Mon dessin numéro 1.", "zh": "我称它为一号画。", "t": [9025, 10038]}, {"fr": "Il était comme ça :", "zh": "我称它为一号画。", "t": [10038, 12825]}]}, {"id": "ch01p03", "audio": true, "sents": [{"fr": "J’ai montré mon chef d’œuvre aux grandes personnes et je leur ai demandé si mon dessin leur faisait peur.", "zh": "一号画如下： 我把我的杰作拿给大人看，还问他们，我的画是否吓坏了他们。", "t": [100, 4650]}]}, {"id": "ch01p04", "audio": true, "sents": [{"fr": "Elles m’ont répondu : \"Pourquoi un chapeau ferait-il peur ?\"", "zh": "他们回答我说：“一顶帽子有什么可怕的？", "t": [100, 4250]}]}, {"id": "ch01p05", "audio": true, "sents": [{"fr": "Mon dessin ne représentait pas un chapeau.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [100, 2962]}, {"fr": "Il représentait un serpent boa qui digérait un éléphant.", "zh": "” 我画的不是一顶帽子，而是一条正在消化大象的蟒蛇啊。", "t": [2962, 6725]}, {"fr": "J’ai alors dessiné l’intérieur du serpent boa, afin que les grandes personnes puissent comprendre.", "zh": "我又画了一张画，画的是蟒蛇和它肚子里的大象，好让大人看懂我的画。", "t": [6725, 12488]}, {"fr": "Elles ont toujours besoin d’explications.", "zh": "他们总是需要我们给他们解释的。", "t": [12488, 15350]}, {"fr": "Mon dessin numéro 2 était comme ça :", "zh": "他们总是需要我们给他们解释的。", "t": [15350, 17937]}]}, {"id": "ch01p06", "audio": true, "sents": [{"fr": "Les grandes personnes m’ont conseillé de laisser de côté les dessins de serpents boas ouverts ou fermés, et de m’intéresser plutôt à la géographie, à l’histoire, au calcul et à la grammaire.", "zh": "我的二号画如下： 大人们劝我，别画这些肚子没打开或打开了的蟒蛇了，把心思放到地理、历史、算术、语法上去吧。", "t": [100, 10600]}, {"fr": "C’est ainsi que j’ai abandonné, à l’âge de six ans, une magnifique carrière de peintre.", "zh": "就这样，我在六岁这一年放弃了画家的光辉生涯。", "t": [10600, 16188]}, {"fr": "J’avais été découragé par l’insuccès de mon dessin numéro 1 et de mon dessin numéro 2.", "zh": "一号画、二号画的失败令我垂头丧气。", "t": [16188, 20638]}, {"fr": "Les grandes personnes ne comprennent jamais rien toutes seules, et c’est fatigant, pour les enfants, de toujours leur donner des explications.", "zh": "我只好选择另一门职业。", "t": [20638, 28612]}]}, {"id": "ch01p07", "audio": true, "sents": [{"fr": "J’ai donc dû choisir un autre métier et j’ai appris à piloter des avions.", "zh": "我学会了驾驶飞机，几乎跑遍了世界各地。", "t": [100, 4812]}, {"fr": "J’ai volé un peu partout dans le monde.", "zh": "地理确实帮了我的大忙。", "t": [4812, 7550]}, {"fr": "Et la géographie, c’est exact, m’a beaucoup servi.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [7550, 11812]}, {"fr": "Je savais reconnaître, du premier coup d’œil, la Chine de l’Arizona.", "zh": "在空中，我一眼就能认出中国和亚利桑那 [1] ，这样的本领很管用——如果夜航时迷了路。", "t": [11812, 16825]}, {"fr": "C’est très utile, si l’on est égaré pendant la nuit.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [16825, 19500]}]}, {"id": "ch01p08", "audio": true, "sents": [{"fr": "J’ai ainsi eu, au cours de ma vie, des tas de contacts avec des tas de gens sérieux.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [100, 5200]}, {"fr": "J’ai beaucoup vécu chez les grandes personnes.", "zh": "我一生与许多重要人物打过交道，我在大人当中生活了很长时间，我仔细地观察过他们，然而我对他们的看法没有多大的改善。", "t": [5200, 8188]}, {"fr": "Je les ai vues de très près.", "zh": "我始终保留着我的一号画。", "t": [8188, 10350]}, {"fr": "Ça n’a pas trop amélioré mon opinion.", "zh": "我始终保留着我的一号画。", "t": [10350, 12325]}]}, {"id": "ch01p09", "audio": true, "sents": [{"fr": "Quand j’en rencontrais une qui me paraissait un peu lucide, je faisais l’expérience sur elle de mon dessin n° 1 que j’ai toujours conservé.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [100, 7850]}, {"fr": "Je voulais savoir si elle était vraiment compréhensive.", "zh": "遇到一个我认为略为懂事的大人，我就用这幅画做试验，看他是否真的懂事，但他们总是这样回答我：“这是一顶帽子。", "t": [7850, 11400]}, {"fr": "Mais toujours elle me répondait : \"C’est un chapeau.\" Alors je ne lui parlais ni de serpents boas, ni de forêts vierges, ni d’étoiles.", "zh": "”听了这样的话，我就不再与他们谈蟒蛇、原始森林、星星了。", "t": [11400, 20888]}, {"fr": "Je me mettais à sa portée.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [20888, 23238]}, {"fr": "Je lui parlais de bridge, de golf, de politique et de cravates.", "zh": "我谈他们能理解的事情，例如桥牌啦，高尔夫球啦，政治啦，领带啦。", "t": [23238, 27888]}, {"fr": "Et la grande personne était bien contente de connaître un homme aussi raisonnable.", "zh": "大人们便很满意，以为他们认识了一个通情达理、善解人意的人。", "t": [27888, 31688]}]}, {"id": "ch01p10", "audio": true, "sents": []}]}, {"id": "ch02", "title_fr": "Chapitre II", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"fr": "J’ai ainsi vécu seul, sans personne avec qui parler véritablement, jusqu’à une panne dans le désert du Sahara, il y a six ans.", "zh": "从此我孤独地生活着，没有一个可以推心置腹的朋友。", "t": [100, 7825]}, {"fr": "Quelque chose s’était cassé dans mon moteur.", "zh": "六年前，我的飞机出了故障，发动机里的某个部件被撞坏了，我被迫在撒哈拉沙漠降落。", "t": [7825, 10888]}, {"fr": "Et comme je n’avais avec moi ni mécanicien, ni passagers, je me préparai à essayer de réussir, tout seul, une réparation difficile.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [10888, 19675]}, {"fr": "C’était pour moi une question de vie ou de mort.", "zh": "身边没有机械师，没有一个乘客，我只好勉为其难，自己动手，试着修理部件。", "t": [19675, 22750]}, {"fr": "J’avais à peine de l’eau à boire pour huit jours.", "zh": "我带的水仅够喝一个星期，能否修好飞机，关系到我的生死存亡了。", "t": [22750, 25025]}]}, {"id": "ch02p01", "audio": true, "sents": [{"fr": "Le premier soir je me suis donc endormi sur le sable à mille milles de toute terre habitée.", "zh": "第一夜，我在远离人烟、千里之遥的沙漠上睡觉。", "t": [100, 5175]}, {"fr": "J’étais bien plus isolé qu’un naufragé sur un radeau au milieu de l’océan.", "zh": "比起那些乘着木排，在茫茫大洋中挣扎漂浮的遇险者，我更显得孤独无助。", "t": [5175, 9762]}, {"fr": "Alors vous imaginez ma surprise, au lever du jour, quand une drôle de petite voix m’a réveillé.", "zh": "朝霞初露的时候，一个细细的奇妙的声音把我唤醒。", "t": [9762, 15850]}, {"fr": "Elle disait :", "zh": "你不难想像我当时有多惊讶了。", "t": [15850, 17274]}]}, {"id": "ch02p02", "audio": true, "sents": [{"fr": "— S’il vous plaît…", "zh": "你不难想像我当时有多惊讶了。", "t": [100, 2125]}, {"fr": "dessine-moi un mouton !", "zh": "你不难想像我当时有多惊讶了。", "t": [2125, 3887]}]}, {"id": "ch02p03", "audio": true, "sents": [{"fr": "— Hein !", "zh": "你不难想像我当时有多惊讶了。", "t": [100, 2163]}]}, {"id": "ch02p04", "audio": true, "sents": [{"fr": "— Dessine-moi un mouton…", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [100, 2387]}]}, {"id": "ch02p05", "audio": true, "sents": [{"fr": "J’ai sauté sur mes pieds comme si j’avais été frappé par la foudre.", "zh": "这细细的奇妙的声音说： “劳驾……请你给我画一只绵羊吧！", "t": [100, 4088]}, {"fr": "J’ai bien frotté mes yeux.", "zh": "” “你说什么？", "t": [4088, 6225]}, {"fr": "J’ai bien regardé.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [6225, 8200]}, {"fr": "Et j’ai vu un petit bonhomme tout à fait extraordinaire qui me considérait gravement.", "zh": "” “给我画一只绵羊……” 我像遭了雷击，一跃而起。", "t": [8200, 13100]}, {"fr": "Voilà le meilleur portrait que, plus tard, j’ai réussi à faire de lui.", "zh": "我使劲揉我的眼睛，仔细地看了看，只见一个很奇特的小小的人儿，他正在那儿注视我呢。", "t": [13100, 17962]}, {"fr": "Mais mon dessin, bien sûr, est beaucoup moins ravissant que le modèle.", "zh": "下面就是以后我给他画的最为成功的一幅肖像画。", "t": [17962, 22712]}, {"fr": "Ce n’est pas ma faute.", "zh": "下面就是以后我给他画的最为成功的一幅肖像画。", "t": [22712, 24688]}, {"fr": "J’avais été découragé dans ma carrière de peintre par les grandes personnes, à l’âge de six ans, et je n’avais rien appris à dessiner, sauf les boas fermés et les boas ouverts.", "zh": "当然，它没有他本人可爱俊美，这可不能怪我，该怪大人，是他们在我六岁那年葬送了我的画家生涯。", "t": [24688, 33812]}]}, {"id": "ch02p06", "audio": true, "sents": [{"fr": "Je regardai donc cette apparition avec des yeux tout ronds d’étonnement.", "zh": "我大吃一惊，眼睛瞪得溜圆，看着这位突然出现的人儿。", "t": [100, 4875]}, {"fr": "N’oubliez pas que je me trouvais à mille milles de toute région habitée.", "zh": "你们可别忘了，这儿是远离人烟、千里之遥的地方啊。", "t": [4875, 8300]}, {"fr": "Or mon petit bonhomme ne me semblait ni égaré, ni mort de fatigue, ni mort de faim, ni mort de soif, ni mort de peur.", "zh": "我的这个小人儿一点不像迷了路，也不像是累死、饿死、渴死、吓死的鬼魂。", "t": [8300, 16250]}, {"fr": "Il n’avait en rien l’apparence d’un enfant perdu au milieu du désert, à mille milles de toute région habitée.", "zh": "他一点不像迷失于沙漠中的孩子，不像远离人烟、千里之遥的孩子。", "t": [16250, 22388]}, {"fr": "Quand je réussis enfin à parler, je lui dis :", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [22388, 25538]}]}, {"id": "ch02p07", "audio": true, "sents": [{"fr": "— Mais…", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [100, 1650]}, {"fr": "qu’est-ce que tu fais là ?", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [1650, 3263]}]}, {"id": "ch02p08", "audio": true, "sents": [{"fr": "Et il me répéta alors, tout doucement, comme une chose très sérieuse :", "zh": "我终于能够张口说话了，我问他： “……你在这儿干什么？", "t": [100, 4387]}]}, {"id": "ch02p09", "audio": true, "sents": [{"fr": "— S’il vous plaît…", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 2112]}, {"fr": "dessine-moi un mouton…", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [2112, 3162]}]}, {"id": "ch02p10", "audio": true, "sents": [{"fr": "Quand le mystère est trop impressionnant, on n’ose pas désobéir.", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 4150]}, {"fr": "Aussi absurde que cela me semblât à mille milles de tous les endroits habités et en danger de mort, je sortis de ma poche une feuille de papier et un stylographe.", "zh": "虽然，身处远离人烟的荒漠，面临死亡的威胁，叫人画画的要求又未免荒堂，我还是从口袋里掏出一张纸和一枝钢笔。", "t": [4150, 13125]}, {"fr": "Mais je me rappelai alors que j’avais surtout étudié la géographie, l’histoire, le calcul et la grammaire et je dis au petit bonhomme (avec un peu de mauvaise humeur) que je ne savais pas dessiner.", "zh": "我忽然记起，除了钻研地理、历史、算术、语法，我没有画过画，便没好气地冲小人儿说，我不会画画。", "t": [13125, 24125]}, {"fr": "Il me répondit :", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [24125, 25850]}]}, {"id": "ch02p11", "audio": true, "sents": [{"fr": "— Ça ne fait rien.", "zh": "他说：“不要紧，给我画一只绵羊吧。", "t": [100, 2912]}, {"fr": "Dessine-moi un mouton.", "zh": "” 我从没画过绵羊，只画过那两张画。", "t": [2912, 4126]}]}, {"id": "ch02p12", "audio": true, "sents": [{"fr": "Comme je n’avais jamais dessiné un mouton je refis, pour lui, l’un des deux seuls dessins dont j’étais capable.", "zh": "我就给他画了其中的一张，就是没有打开肚子的蟒蛇。", "t": [100, 6462]}, {"fr": "Celui du boa fermé.", "zh": "我吓了一跳，我听见小人儿说： “不！", "t": [6462, 8588]}, {"fr": "Et je fus stupéfait d’entendre le petit bonhomme me répondre :", "zh": "不！", "t": [8588, 12162]}]}, {"id": "ch02p13", "audio": true, "sents": [{"fr": "— Non !", "zh": "我不要象在蟒蛇的肚子里。", "t": [100, 3125]}, {"fr": "Non !", "zh": "蟒蛇太可怕，象太占地方。", "t": [3125, 5112]}, {"fr": "Je ne veux pas d’un éléphant dans un boa.", "zh": "蟒蛇太可怕，象太占地方。", "t": [5112, 7950]}, {"fr": "Un boa c’est très dangereux, et un éléphant c’est très encombrant.", "zh": "我要绵羊，给我画一只绵羊吧。", "t": [7950, 12025]}, {"fr": "Chez moi c’est tout petit.", "zh": "” 我便画了一头羊。", "t": [12025, 14150]}, {"fr": "J’ai besoin d’un mouton.", "zh": "他仔细看看，然后说： “不好！", "t": [14150, 16300]}, {"fr": "Dessine-moi un mouton.", "zh": "他仔细看看，然后说： “不好！", "t": [16300, 17513]}]}, {"id": "ch02p14", "audio": true, "sents": [{"fr": "Alors j’ai dessiné.", "zh": "这是一头患了重病的羊。", "t": [100, 1237]}]}, {"id": "ch02p15", "audio": true, "sents": [{"fr": "Il regarda attentivement, puis :", "zh": "给我画另一头吧。", "t": [100, 2687]}]}, {"id": "ch02p16", "audio": true, "sents": [{"fr": "— Non !", "zh": "给我画另一头吧。", "t": [100, 3125]}, {"fr": "Celui-là est déjà très malade.", "zh": "” 我又画了一只羊。", "t": [3125, 5775]}, {"fr": "Fais-en un autre.", "zh": "” 我又画了一只羊。", "t": [5775, 6750]}]}, {"id": "ch02p17", "audio": true, "sents": [{"fr": "Je dessinai :", "zh": "” 我又画了一只羊。", "t": [100, 1750]}]}, {"id": "ch02p18", "audio": true, "sents": [{"fr": "Mon ami sourit gentiment, avec indulgence :", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [100, 3287]}]}, {"id": "ch02p19", "audio": true, "sents": [{"fr": "— Tu vois bien…", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [100, 2100]}, {"fr": "ce n’est pas un mouton, c’est un bélier.", "zh": "我的朋友露出亲切可爱的微笑，并没有责怪我的意思，他说： “你瞧瞧，这不是小羊，是公羊，它长着角哩。", "t": [2100, 4938]}, {"fr": "Il a des cornes…", "zh": "” 我又画了一张。", "t": [4938, 5837]}]}, {"id": "ch02p20", "audio": true, "sents": [{"fr": "Je refis donc encore mon dessin :", "zh": "” 我又画了一张。", "t": [100, 2600]}]}, {"id": "ch02p21", "audio": true, "sents": [{"fr": "Mais il fut refusé, comme les précédents :", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [100, 3100]}]}, {"id": "ch02p22", "audio": true, "sents": [{"fr": "— Celui-là est trop vieux.", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [100, 3200]}, {"fr": "Je veux un mouton qui vive longtemps.", "zh": "这一张画和前面两张一样，遭到了他的拒绝： “这只太老了，我要一只能活很久的绵羊。", "t": [3200, 4974]}]}, {"id": "ch02p23", "audio": true, "sents": [{"fr": "Alors, faute de patience, comme j’avais hâte de commencer le démontage de mon moteur, je griffonnai ce dessin-ci.", "zh": "” 我急于着手拆卸我的发动机，失去了耐性。", "t": [100, 6788]}]}, {"id": "ch02p24", "audio": true, "sents": [{"fr": "Et je lançai :", "zh": "我胡乱涂了下面这幅画。", "t": [100, 1687]}]}, {"id": "ch02p25", "audio": true, "sents": [{"fr": "— Ça c’est la caisse.", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [100, 3038]}, {"fr": "Le mouton que tu veux est dedans.", "zh": "而且我冲他说： “这是一只箱子，你要的绵羊在里面。", "t": [3038, 4612]}]}, {"id": "ch02p26", "audio": true, "sents": [{"fr": "Mais je fus bien surpris de voir s’illuminer le visage de mon jeune juge :", "zh": "” 然而我惊讶地看到，我的这位小法官竟眉开眼笑： “我要的正是这样的箱子！", "t": [100, 4063]}]}, {"id": "ch02p27", "audio": true, "sents": [{"fr": "— C’est tout à fait comme ça que je le voulais !", "zh": "这只绵羊要很多草吗？", "t": [100, 4575]}, {"fr": "Crois-tu qu’il faille beaucoup d’herbe à ce mouton ?", "zh": "这只绵羊要很多草吗？", "t": [4575, 7512]}]}, {"id": "ch02p28", "audio": true, "sents": [{"fr": "— Pourquoi ?", "zh": "” “为什么你提这个问题？", "t": [100, 2462]}]}, {"id": "ch02p29", "audio": true, "sents": [{"fr": "— Parce que chez moi c’est tout petit…", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [100, 2687]}]}, {"id": "ch02p30", "audio": true, "sents": [{"fr": "— Ça suffira sûrement.", "zh": "” “因为我的家太小啦……” “肯定够了。", "t": [100, 3200]}, {"fr": "Je t’ai donné un tout petit mouton.", "zh": "我给你的是一只很小很小的绵羊。", "t": [3200, 4975]}]}, {"id": "ch02p31", "audio": true, "sents": [{"fr": "Il pencha la tête vers le dessin :", "zh": "” 他低头看画。", "t": [100, 2538]}]}, {"id": "ch02p32", "audio": true, "sents": [{"fr": "— Pas si petit que ça…", "zh": "“没有这个这么小吧……咦！", "t": [100, 3025]}, {"fr": "Tiens !", "zh": "“没有这个这么小吧……咦！", "t": [3025, 5088]}, {"fr": "Il s’est endormi…", "zh": "“没有这个这么小吧……咦！", "t": [5088, 6150]}]}, {"id": "ch02p33", "audio": true, "sents": [{"fr": "Et c’est ainsi que je fis la connaissance du petit prince.", "zh": "它睡熟了……” 我就这样认识了小王子。", "t": [100, 2750]}]}, {"id": "ch02p34", "audio": true, "sents": []}]}, {"id": "ch03", "title_fr": "Chapitre III", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"fr": "Il me fallut longtemps pour comprendre d’où il venait.", "zh": "过了好久好久，我才弄明白他是打哪儿来的。", "t": [100, 3325]}, {"fr": "Le petit prince, qui me posait beaucoup de questions, ne semblait jamais entendre les miennes.", "zh": "小王子向我提了许多问题，却从不理会我对他提的问题。", "t": [3325, 8988]}, {"fr": "Ce sont des mots prononcés par hasard qui, peu à peu, m’ont tout révélé.", "zh": "我从他无意中吐出的片言只语里，逐渐知道了他的来历。", "t": [8988, 13850]}, {"fr": "Ainsi, quand il aperçut pour la première fois mon avion (je ne dessinerai pas mon avion, c’est un dessin beaucoup trop compliqué pour moi) il me demanda :", "zh": "例如，当他第一次看见我的飞机的时候（我不愿画飞机，太复杂了），就问我： “这是什么玩艺儿呀？", "t": [13850, 22400]}]}, {"id": "ch03p01", "audio": true, "sents": [{"fr": "— Qu’est ce que c’est que cette chose-là ?", "zh": "这是飞机，是我的飞机。", "t": [100, 3388]}]}, {"id": "ch03p02", "audio": true, "sents": [{"fr": "— Ce n’est pas une chose.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [100, 3150]}, {"fr": "Ça vole.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [3150, 4725]}, {"fr": "C’est un avion.", "zh": "” 我挺自豪地告诉他我会飞。", "t": [4725, 6488]}, {"fr": "C’est mon avion.", "zh": "他嚷起来： “怎么？", "t": [6488, 7388]}]}, {"id": "ch03p03", "audio": true, "sents": [{"fr": "Et j’étais fier de lui apprendre que je volais.", "zh": "你是从天上掉下来的吗？", "t": [100, 3100]}, {"fr": "Alors il s’écria :", "zh": "” “是的。", "t": [3100, 5050]}]}, {"id": "ch03p04", "audio": true, "sents": [{"fr": "— Comment !", "zh": "” “是的。", "t": [100, 3238]}, {"fr": "tu es tombé du ciel !", "zh": "”我并没有吹嘘的意思。", "t": [3238, 4988]}]}, {"id": "ch03p05", "audio": true, "sents": [{"fr": "— Oui, fis-je modestement.", "zh": "“啊！", "t": [100, 2750]}]}, {"id": "ch03p06", "audio": true, "sents": [{"fr": "— Ah !", "zh": "“啊！", "t": [100, 3038]}, {"fr": "ça c’est drôle…", "zh": "这就奇了……” 小王子发出清脆悦耳的笑声，他这一笑可惹恼了我。", "t": [3038, 3974]}]}, {"id": "ch03p07", "audio": true, "sents": [{"fr": "Et le petit prince eut un très joli éclat de rire qui m’irrita beaucoup.", "zh": "这就奇了……” 小王子发出清脆悦耳的笑声，他这一笑可惹恼了我。", "t": [100, 4300]}, {"fr": "Je désire que l’on prenne mes malheurs au sérieux.", "zh": "我不喜欢别人对我的不幸打哈哈。", "t": [4300, 7450]}, {"fr": "Puis il ajouta :", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [7450, 9162]}]}, {"id": "ch03p08", "audio": true, "sents": [{"fr": "— Alors, toi aussi tu viens du ciel !", "zh": "然后他又说： “这么说，你也是从天上下来的！", "t": [100, 4700]}, {"fr": "De quelle planète es-tu ?", "zh": "你住在哪一个星球上？", "t": [4700, 6524]}]}, {"id": "ch03p09", "audio": true, "sents": [{"fr": "J’entrevis aussitôt une lueur, dans le mystère de sa présence, et j’interrogeai brusquement :", "zh": "” 这句话犹如一道亮光，让我马上瞥见了他突然出现的秘密。", "t": [100, 5812]}]}, {"id": "ch03p10", "audio": true, "sents": [{"fr": "— Tu viens donc d’une autre planète ?", "zh": "我以突袭的方式问他： “你是从另一个星球来的？", "t": [100, 3500]}]}, {"id": "ch03p11", "audio": true, "sents": [{"fr": "Mais il ne me répondit pas.", "zh": "” 他不答。", "t": [100, 2200]}, {"fr": "Il hochait la tête doucement tout en regardant mon avion :", "zh": "” 他不答。", "t": [2200, 5512]}]}, {"id": "ch03p12", "audio": true, "sents": [{"fr": "— C’est vrai que, là-dessus, tu ne peux pas venir de bien loin…", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 4463]}]}, {"id": "ch03p13", "audio": true, "sents": [{"fr": "Et il s’enfonça dans une rêverie qui dura longtemps.", "zh": "他看着我的飞机，轻轻地点头： “从你乘的这玩艺来看，你确实不可能来自很远的地方……” 他陷入沉思。", "t": [100, 3350]}, {"fr": "Puis, sortant mon mouton de sa poche, il se plongea dans la contemplation de son trésor.", "zh": "过了很久，他从口袋里掏出我画的绵羊，低头凝视他的宝贝。", "t": [3350, 8362]}]}, {"id": "ch03p14", "audio": true, "sents": [{"fr": "Vous imaginez combien j’avais pu être intrigué par cette demi-confidence sur \"les autres planètes\".", "zh": "你们不难想像，听了他那句无意透露的“其他星球”的话后，我会怎样惊讶吧。", "t": [100, 5950]}, {"fr": "Je m’efforçai donc d’en savoir plus long :", "zh": "我竭力从中探听他的来历： “我的小人儿，你从哪儿来？", "t": [5950, 8688]}]}, {"id": "ch03p15", "audio": true, "sents": [{"fr": "— D’où viens-tu mon petit bonhomme ?", "zh": "你的家在哪儿？", "t": [100, 4162]}, {"fr": "Où est-ce \"chez toi\" ?", "zh": "你的家在哪儿？", "t": [4162, 6775]}, {"fr": "Où veux-tu emporter mon mouton ?", "zh": "你要把你的绵羊牵到哪儿去？", "t": [6775, 8950]}]}, {"id": "ch03p16", "audio": true, "sents": [{"fr": "Il me répondit après un silence méditatif :", "zh": "” 他默默不答。", "t": [100, 3138]}]}, {"id": "ch03p17", "audio": true, "sents": [{"fr": "— Ce qui est bien, avec la caisse que tu m’as donnée, c’est que, la nuit, ça lui servira de maison.", "zh": "夜里可以给绵羊做屋子了。", "t": [100, 6587]}]}, {"id": "ch03p18", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "” “是呀，如果你乖，我还要给你一根绳子，白天给你拴羊用。", "t": [100, 2750]}, {"fr": "Et si tu es gentil, je te donnerai aussi une corde pour l’attacher pendant le jour.", "zh": "我还要给你一根拴羊的桩。", "t": [2750, 7788]}, {"fr": "Et un piquet.", "zh": "我还要给你一根拴羊的桩。", "t": [7788, 8513]}]}, {"id": "ch03p19", "audio": true, "sents": [{"fr": "La proposition parut choquer le petit prince :", "zh": "” 我的建议显然惹恼了小王子： “拴住它？", "t": [100, 3063]}]}, {"id": "ch03p20", "audio": true, "sents": [{"fr": "— L’attacher ?", "zh": "亏你想得出这样的主意！", "t": [100, 3462]}, {"fr": "Quelle drôle d’idée !", "zh": "亏你想得出这样的主意！", "t": [3462, 5200]}]}, {"id": "ch03p21", "audio": true, "sents": [{"fr": "— Mais si tu ne l’attaches pas, il ira n’importe où, et il se perdra…", "zh": "” “你不拴住它，它会乱跑的呀，会走失的呀。", "t": [100, 4650]}]}, {"id": "ch03p22", "audio": true, "sents": [{"fr": "Et mon ami eut un nouvel éclat de rire :", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [100, 2675]}]}, {"id": "ch03p23", "audio": true, "sents": [{"fr": "— Mais où veux-tu qu’il aille !", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [100, 2937]}]}, {"id": "ch03p24", "audio": true, "sents": [{"fr": "— N’importe où.", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [100, 2775]}, {"fr": "Droit devant lui…", "zh": "” 我的朋友发出清脆的笑声： “你以为它会跑到哪儿去呢？", "t": [2775, 3763]}]}, {"id": "ch03p25", "audio": true, "sents": [{"fr": "Alors le petit prince remarqua gravement :", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [100, 2838]}]}, {"id": "ch03p26", "audio": true, "sents": [{"fr": "— Ça ne fait rien, c’est tellement petit, chez moi !", "zh": "” “到处乱跑呗，朝前跑呗……” 小王子告诉我： “这倒不成问题，我的家小得很呢！", "t": [100, 4488]}]}, {"id": "ch03p27", "audio": true, "sents": [{"fr": "Et, avec un peu de mélancolie, peut-être, il ajouta :", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [100, 4088]}]}, {"id": "ch03p28", "audio": true, "sents": [{"fr": "Droit devant soi on ne peut pas aller bien loin…", "zh": "” 他的神色略带忧伤，说： “朝前跑，也跑不了多远……”", "t": [100, 2250]}]}, {"id": "ch03p29", "audio": true, "sents": []}, {"id": "ch03p30", "audio": true, "sents": []}]}, {"id": "ch04", "title_fr": "Chapitre IV", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"fr": "J’avais ainsi appris une seconde chose très importante : C’est que sa planète d’origine était à peine plus grande qu’une maison !", "zh": "就这样，我知道了第二件很重要的事情：他打那儿来的星球比一幢房子大不了多少！", "t": [100, 7250]}]}, {"id": "ch04p01", "audio": true, "sents": [{"fr": "Ça ne pouvait pas m’étonner beaucoup.", "zh": "我并不因此大惊小怪。", "t": [100, 2662]}, {"fr": "Je savais bien qu’en dehors des grosses planètes comme la Terre, Jupiter, Mars, Vénus, auxquelles on a donné des noms, il y en a des centaines d’autres qui sont quelque-fois si petites qu’on a beaucoup de mal à les apercevoir au télescope.", "zh": "有些星球小到连望远镜都难以观测。", "t": [2662, 15575]}, {"fr": "Quand un astronome découvre l’une d’elles, il lui donne pour nom un numéro.", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [15575, 20338]}, {"fr": "Il l’appelle par exemple : \"l’astéroïde 3251.\"", "zh": "我有充分的证据认为小王子打那儿来的星球就是B612号小行星。", "t": [20338, 24713]}]}, {"id": "ch04p02", "audio": true, "sents": [{"fr": "J’ai de sérieuses raisons de croire que la planète d’où venait le petit prince est l’astéroïde B 612.", "zh": "这颗小行星仅仅在一九〇九年被一位土耳其天文学家用望远镜看见过一回。", "t": [100, 4638]}, {"fr": "Cet astéroïde n’a été aperçu qu’une fois au télescope, en 1909, par un astronome turc.", "zh": "在国际天文会议上，他为他的发现做了雄辩的论证，但没有人相信他的报告。", "t": [4638, 12162]}]}, {"id": "ch04p03", "audio": true, "sents": [{"fr": "Il avait fait alors une grande démonstration de sa découverte à un Congrès International d’Astronomie.", "zh": "因为他穿的是土耳其人的服装。", "t": [100, 6175]}, {"fr": "Mais personne ne l’avait cru à cause de son costume.", "zh": "大人们就这个德性：以衣冠取人。", "t": [6175, 9525]}, {"fr": "Les grandes personnes sont comme ça.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [9525, 11225]}]}, {"id": "ch04p04", "audio": true, "sents": [{"fr": "Heureusement pour la réputation de l’astéroïde B 612 un dictateur turc imposa à son peuple, sous peine de mort, de s’habiller à l’Européenne.", "zh": "幸好，为了维护B612小行星的声誉，土耳其独裁者颁布了一条法令，命令百姓改穿欧式服装，否则处以死刑。", "t": [100, 9550]}, {"fr": "L’astronome refit sa démonstration en 1920, dans un habit très élégant.", "zh": "一九二〇年，这位土耳其天文学家身穿一套极考究的西服，再一次在国际会议上做了论证。", "t": [9550, 14162]}, {"fr": "Et cette fois-ci tout le monde fut de son avis.", "zh": "这一回，他得到了大家的认可。", "t": [14162, 16400]}]}, {"id": "ch04p05", "audio": true, "sents": [{"fr": "Si je vous ai raconté ces détails sur l’astéroïde B 612 et si je vous ai confié son numéro, c’est à cause des grandes personnes.", "zh": "我对你们详细报告发现小行星B612的这些细节，把它的号码告诉你们，都是由于那些大人们的缘故。", "t": [100, 7838]}, {"fr": "Les grandes personnes aiment les chiffres.", "zh": "因为大人们对数字情有独钟。", "t": [7838, 10325]}, {"fr": "Quand vous leur parlez d’un nouvel ami, elles ne vous questionnent jamais sur l’essentiel.", "zh": "因为大人们对数字情有独钟。", "t": [10325, 15112]}, {"fr": "Elles ne vous disent jamais : \"Quel est le son de sa voix ?", "zh": "如果你对他们介绍一个新朋友，他们从不打听他的基本情况，他们从不会问你：“他的嗓子怎么样？", "t": [15112, 19850]}, {"fr": "Quels sont les jeux qu’il préfère ?", "zh": "他喜欢玩什么游戏？", "t": [19850, 22725]}, {"fr": "Est-ce qu’il collectionne les papillons ?\" Elles vous demandent : \"Quel âge a-t-il ?", "zh": "”而是问：“他几岁了？", "t": [22725, 29912]}, {"fr": "Combien a-t-il de frères ?", "zh": "体重多少？", "t": [29912, 32612]}, {"fr": "Combien pèse-t-il ?", "zh": "他的父亲挣多少钱？", "t": [32612, 34988]}, {"fr": "Combien gagne son père ?\" Alors seulement elles croient le connaître.", "zh": "”他们认为了解了这些情况，就了解了一个人。", "t": [34988, 40262]}, {"fr": "Si vous dites aux grandes personnes : \"J’ai vu une belle maison en briques roses, avec des géraniums aux fenêtres et des colombes sur le toit…\" elles ne parviennent pas à s’imaginer cette maison.", "zh": "如果你告诉大人：“我看见一幢漂亮的红砖房子，窗前摆着天竺葵，鸽子在屋顶栖息……”他们便无法想像这是一幢怎样的房子。", "t": [40262, 51275]}, {"fr": "Il faut leur dire : \"J’ai vu une maison de cent mille francs.\" Alors elles s’écrient : \"Comme c’est joli !\"", "zh": "你必须对他们说：“我看见一幢值十万法郎的房子！", "t": [51275, 59050]}]}, {"id": "ch04p06", "audio": true, "sents": [{"fr": "Ainsi, si vous leur dites : \"La preuve que le petit prince a existé c’est qu’il était ravissant, qu’il riait, et qu’il voulait un mouton.", "zh": "” 所以，如果你对他们说：“这世上确实存在一位王子，证据就是他可爱俊美，脸带笑容，他要一只绵羊。", "t": [100, 8488]}, {"fr": "Quand on veut un mouton, c’est la preuve qu’on existe\" elles hausseront les épaules et vous traiteront d’enfant !", "zh": "一个人要一只绵羊，就是他存在的证明。", "t": [8488, 14612]}, {"fr": "Mais si vous leur dites : \"La planète d’où il venait est l’astéroïde B 612\" alors elles seront convaincues, et elles vous laisseront tranquille avec leurs questions.", "zh": "但如果你对他们说：“他打那儿来的星球是小行星B612。", "t": [14612, 23888]}, {"fr": "Elles sont comme ça.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [23888, 25725]}, {"fr": "Il ne faut pas leur en vouloir.", "zh": "”他们就深信不疑了，就不会用没完没了的问题烦你了。", "t": [25725, 28088]}, {"fr": "Les enfants doivent être très indulgents envers les grandes personnes.", "zh": "他们就这副德性。", "t": [28088, 31312]}]}, {"id": "ch04p07", "audio": true, "sents": [{"fr": "Mais, bien sûr, nous qui comprenons la vie, nous nous moquons bien des numéros !", "zh": "当然，我们是理解生活的人，我们才不会把数字放在眼里呢！", "t": [100, 6125]}, {"fr": "J’aurais aimé commencer cette histoire à la façon des contes de fées.", "zh": "我喜欢以讲童话的方式讲这个故事。", "t": [6125, 10262]}, {"fr": "J’aurais aimé dire :", "zh": "我喜欢以讲童话的方式讲这个故事。", "t": [10262, 11925]}]}, {"id": "ch04p08", "audio": true, "sents": [{"fr": "\"Il était une fois un petit prince qui habitait une planète à peine plus grande que lui, et qui avait besoin d’un ami…\" Pour ceux qui comprennent la vie, ça aurait eu l’air beaucoup plus vrai.", "zh": "这颗行星比他自己大不了多少。", "t": [100, 9538]}]}, {"id": "ch04p09", "audio": true, "sents": [{"fr": "Car je n’aime pas qu’on lise mon livre à la légère.", "zh": "”对于理解生活的人，这样讲似乎要真实得多。", "t": [100, 3375]}, {"fr": "J’éprouve tant de chagrin à raconter ces souvenirs.", "zh": "我不喜欢别人漫不经心地读我的书。", "t": [3375, 6925]}, {"fr": "Il y a six ans déjà que mon ami s’en est allé avec son mouton.", "zh": "我的朋友牵着他的羊走了六年了。", "t": [6925, 10812]}, {"fr": "Si j’essaie ici de le décrire, c’est afin de ne pas l’oublier.", "zh": "我在这儿讲述他的故事，是为了不忘记他。", "t": [10812, 15262]}, {"fr": "C’est triste d’oublier un ami.", "zh": "忘了朋友是可悲的。", "t": [15262, 17562]}, {"fr": "Tout le monde n’a pas eu un ami.", "zh": "并不是每个人都有朋友的。", "t": [17562, 20050]}, {"fr": "Et je puis devenir comme les grandes personnes qui ne s’intéressent plus qu’aux chiffres.", "zh": "也许有一天我也像大人那样，除了数字，对别的东西都失去兴趣。", "t": [20050, 24525]}, {"fr": "C’est donc pour ça encore que j’ai acheté une boîte de couleurs et des crayons.", "zh": "为了这个缘故，我买了一盒颜料和几枝铅笔。", "t": [24525, 29188]}, {"fr": "C’est dur de se remettre au dessin, à mon âge, quand on n’a jamais fait d’autres tentatives que celle d’un boa fermé et celle d’un boa ouvert, à l’âge de six ans !", "zh": "而且，除了在六岁那年画过一条打开肚子的蟒蛇和一条没打开肚子的蟒蛇之外，我没画过别的画。", "t": [29188, 38762]}, {"fr": "J’essaierai, bien sûr, de faire des portraits le plus ressemblants possible.", "zh": "当然，我可以画最逼真的人像画。", "t": [38762, 43912]}, {"fr": "Mais je ne suis pas tout à fait certain de réussir.", "zh": "但能否成功，我把握不大。", "t": [43912, 47112]}, {"fr": "Un dessin va, et l’autre ne ressemble plus.", "zh": "这一幅画得可以，另一幅却画得不像。", "t": [47112, 50375]}, {"fr": "Je me trompe un peu aussi sur la taille.", "zh": "对他的个儿高矮，我也记得不太真切。", "t": [50375, 53250]}, {"fr": "Ici le petit prince est trop grand.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [53250, 55738]}, {"fr": "Là il est trop petit.", "zh": "这幅把他画得太高，另一幅把他画得太矮。", "t": [55738, 57738]}, {"fr": "J’hésite aussi sur la couleur de son costume.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [57738, 60925]}, {"fr": "Alors je tâtonne comme ci et comme ça, tant bien que mal.", "zh": "该给他的衣服抹什么颜色，我也犹豫不决。", "t": [60925, 64912]}, {"fr": "Je me tromperai enfin sur certains détails plus importants.", "zh": "我在画纸上抹来抹去，画了张约莫相似的肖像，但某些重要部位也许弄错了。", "t": [64912, 68650]}, {"fr": "Mais ça, il faudra me le pardonner.", "zh": "对这一点，你们一定要谅解。", "t": [68650, 71588]}, {"fr": "Mon ami ne donnait jamais d’explications.", "zh": "对这一点，你们一定要谅解。", "t": [71588, 74588]}, {"fr": "Il me croyait peut-être semblable à lui.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [74588, 77588]}, {"fr": "Mais moi, malheureusement, je ne sais pas voir les moutons à travers les caisses.", "zh": "我的朋友从不向我解释，大概他以为我和他一样；可是我呢，很遗憾，我不能透过箱子看到里面的绵羊。", "t": [77588, 82488]}, {"fr": "Je suis peut-être un peu comme les grandes personnes.", "zh": "也许我有点像大人了。", "t": [82488, 85612]}, {"fr": "J’ai dû vieillir.", "zh": "我大概老了。", "t": [85612, 86674]}]}, {"id": "ch04p10", "audio": true, "sents": []}]}, {"id": "ch05", "title_fr": "Chapitre V", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"fr": "Chaque jour j’apprenais quelque chose sur la planète, sur le départ, sur le voyage.", "zh": "每一天，我都从他那儿获得一些有关星球、启程、旅行的知识。", "t": [100, 5562]}, {"fr": "Ça venait tout doucement, au hasard des réflexions.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [5562, 9162]}, {"fr": "C’est ainsi que, le troisième jour, je connus le drame des baobabs.", "zh": "这些知识是逐渐得到的，只要想到什么问题就提什么问题。", "t": [9162, 13026]}]}, {"id": "ch05p01", "audio": true, "sents": [{"fr": "Cette fois-ci encore ce fut grâce au mouton, car brusquement le petit prince m’interrogea, comme pris d’un doute grave :", "zh": "这一回还真亏了绵羊。", "t": [100, 6563]}]}, {"id": "ch05p02", "audio": true, "sents": [{"fr": "— C’est bien vrai, n’est-ce pas, que les moutons mangent les arbustes ?", "zh": "因为小王子突然对一件事产生了极大的怀疑，突然问我： “羊吃灌木，这是真的吗？", "t": [100, 5025]}]}, {"id": "ch05p03", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” “是呀，是真的呀。", "t": [100, 2400]}, {"fr": "C’est vrai.", "zh": "” “是呀，是真的呀。", "t": [2400, 3000]}]}, {"id": "ch05p04", "audio": true, "sents": [{"fr": "— Ah !", "zh": "” “是呀，是真的呀。", "t": [100, 3038]}, {"fr": "Je suis content.", "zh": "” “是呀，是真的呀。", "t": [3038, 3938]}]}, {"id": "ch05p05", "audio": true, "sents": [{"fr": "Je ne compris pas pourquoi il était si important que les moutons mangeassent les arbustes.", "zh": "” “啊，那我很高兴。", "t": [100, 5062]}, {"fr": "Mais le petit prince ajouta :", "zh": "” 我不明白，羊吃灌木为什么这么重要。", "t": [5062, 7288]}]}, {"id": "ch05p06", "audio": true, "sents": [{"fr": "— Par conséquent ils mangent aussi les baobabs ?", "zh": "小王子又问： “这么说，它们也吃猴面包树啦？", "t": [100, 3850]}]}, {"id": "ch05p07", "audio": true, "sents": [{"fr": "Je fis remarquer au petit prince que les baobabs ne sont pas des arbustes, mais des arbres grand comme des églises et que, si même il emportait avec lui tout un troupeau d’éléphants, ce troupeau ne viendrait pas à bout d’un seul baobab.", "zh": "” 我提醒小王子，猴面包树不是灌木丛，而是像教堂一样巍峨高大的树。", "t": [100, 11200]}]}, {"id": "ch05p08", "audio": true, "sents": [{"fr": "L’idée du troupeau d’éléphants fit rire le petit prince :", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 3338]}]}, {"id": "ch05p09", "audio": true, "sents": [{"fr": "— Il faudrait les mettre les uns sur les autres…", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 3013]}]}, {"id": "ch05p10", "audio": true, "sents": [{"fr": "Mais il remarqua avec sagesse :", "zh": "想到一群象啃猴面包树的情景，小王子忍不住笑了： “那它们非得叠罗汉了……” 他很机灵，指出： “猴面包树的树苗挺小的呢！", "t": [100, 2437]}]}, {"id": "ch05p11", "audio": true, "sents": [{"fr": "— Les baobabs, avant de grandir, ça commence par être petit.", "zh": "” “你说得对！", "t": [100, 4837]}]}, {"id": "ch05p12", "audio": true, "sents": [{"fr": "— C’est exact !", "zh": "” “你说得对！", "t": [100, 3512]}, {"fr": "Mais pourquoi veux-tu que tes moutons mangent les petits baobabs ?", "zh": "可是你为什么希望你的绵羊吃猴面包树苗呢？", "t": [3512, 6974]}]}, {"id": "ch05p13", "audio": true, "sents": [{"fr": "Il me répondit : \"Ben !", "zh": "” 他说：“嘿！", "t": [100, 3875]}, {"fr": "Voyons !\" comme s’il s’agissait là d’une évidence.", "zh": "”似乎这是再明白不过的事情。", "t": [3875, 8162]}, {"fr": "Et il me fallut un grand effort d’intelligence pour comprendre à moi seul ce problème.", "zh": "而要我自己想明白这个问题，我确实要绞尽脑汁了。", "t": [8162, 12213]}]}, {"id": "ch05p14", "audio": true, "sents": [{"fr": "Et en effet, sur la planète du petit prince, il y avait comme sur toutes les planètes, de bonnes herbes et de mauvaises herbes.", "zh": "是的，小王子的星球和其他星球一样，长着益草，也长着毒草，因此也就有了益草的种子和毒草的种子。", "t": [100, 7512]}, {"fr": "Par conséquent de bonnes graines de bonnes herbes et de mauvaises graines de mauvaises herbes.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [7512, 12162]}, {"fr": "Mais les graines sont invisibles.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [12162, 14675]}, {"fr": "Elles dorment dans le secret de la terre jusqu’à ce qu’il prenne fantaisie à l’une d’elles de se réveiller.", "zh": "但种子是看不见的，它们沉埋在土地深处，直至其中一颗突然苏醒……它伸伸懒腰，羞羞答答，向着太阳伸出一株青嫩可爱、娇小玲珑、不伤人的幼苗来。", "t": [14675, 19900]}, {"fr": "Alors elle s’étire, et pousse d’abord timidement vers le soleil une ravissante petite brindille inoffensive.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [19900, 26212]}, {"fr": "S’il s’agît d’une brindille de radis ou de rosier, on peut la laisser pousser comme elle veut.", "zh": "倘若它是萝卜或玫瑰的幼苗，我们可以任由它茁壮成长；倘若它是有毒的植物，一经认出，我们就必须马上拔除。", "t": [26212, 61863]}, {"fr": "Mais s’il s’agit d’une mauvaise plante, il faut arracher la plante aussitôt, dès qu’on a su la reconnaître.", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [61863, 62363]}, {"fr": "Or il y avait des graines terribles sur la planète du petit prince…", "zh": "小王子的星球上埋着可怕的种子……这就是猴面包树的种子，星球的土壤饱受其害，不及时动手除掉它们，你就永远别想摆脱它们的侵害。", "t": [62363, 62863]}, {"fr": "c’étaient les graines de baobabs.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [62863, 63363]}, {"fr": "Le sol de la planète en était infesté.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [63363, 63863]}, {"fr": "Or un baobab, si l’on s’y prend trop tard, on ne peut jamais plus s’en débarrasser.", "zh": "它的树身枝叶占据整个星球，如果星球小，而猴面包树过多，就会撑破星球。", "t": [63863, 64363]}, {"fr": "Il encombre toute la planète.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [64363, 64863]}, {"fr": "Il la perfore de ses racines.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [64863, 65363]}, {"fr": "Et si la planète est trop petite, et si les baobabs sont trop nombreux, ils la font éclater.", "zh": "后来小王子对我说：“人早上梳洗之后，一定要小心清理地球，要经常督促自己，要养成良好的习惯。", "t": [65363, 65863]}]}, {"id": "ch05p15", "audio": true, "sents": [{"fr": "\"C’est une question de discipline, me disait plus tard le petit prince.", "zh": "猴面包树的苗儿与玫瑰花的苗儿长得极相似，把它们区别开来之后，就要经常督促自己拔除猴面包树苗。", "t": [100, 4625]}, {"fr": "Quand on a terminé sa toilette du matin, il faut faire soigneusement la toilette de la planète.", "zh": "这活儿单调乏味，但也挺容易干。", "t": [4625, 10500]}, {"fr": "Il faut s’astreindre régulièrement à arracher les baobabs dès qu’on les distingue d’avec les rosiers auxquels ils ressemblent beaucoup quand ils sont très jeunes.", "zh": "” 有一天，他建议我用心画一幅猴面包树的画，要让我们那儿的孩子牢牢记住它。", "t": [10500, 18362]}, {"fr": "C’est un travail très ennuyeux, mais très facile.\"", "zh": "他对我说：“有朝一日他们外出旅行，这幅画就派上用场了。", "t": [18362, 21100]}]}, {"id": "ch05p16", "audio": true, "sents": [{"fr": "Et un jour il me conseilla de m’appliquer à réussir un beau dessin, pour bien faire entrer ça dans la tête des enfants de chez moi.", "zh": "有些时候，耽搁了的工夫造不成多大的恶果，然而对猴面包树的危害却不能轻视。", "t": [100, 7075]}, {"fr": "\"S’ils voyagent un jour, me disait-il, ça pourra leur servir.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [7075, 11762]}, {"fr": "Il est quelquefois sans inconvénient de remettre à plus tard son travail.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [11762, 16062]}, {"fr": "Mais, s’il s’agit des baobabs, c’est toujours une catastrophe.", "zh": "我知道，有一颗星球上住着一个懒人，他忽略了剔除三棵猴面包树苗的事儿……” 在小王子的指点下，我画了这个星球。", "t": [16062, 20550]}, {"fr": "J’ai connu une planète, habitée par un paresseux.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [20550, 24062]}, {"fr": "Il avait négligé trois arbustes…\"", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [24062, 25825]}]}, {"id": "ch05p17", "audio": true, "sents": [{"fr": "Et, sur les indications du petit prince, j’ai dessiné cette planète-là.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [100, 4775]}, {"fr": "Je n’aime guère prendre le ton d’un moraliste.", "zh": "我素来不喜欢装腔作势，摆出一副道学家的面孔训人，但许多人对猴面包树的危害认识不足，在小行星上迷路的人遇到的风险又那么大，我不能不一反平日矜持的常态，大声疾呼：“孩子们，当心猴面包树啊！", "t": [4775, 7812]}, {"fr": "Mais le danger des baobabs est si peu connu, et les risques courus par celui qui s’égarerait dans un astéroïde sont si considérables, que, pour une fois, je fais exception à ma réserve.", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [7812, 18612]}, {"fr": "Je dis : \"Enfants !", "zh": "”为了向朋友们发出警告，让他们提防早已威胁我们的危险——而他们和我一样，对这样的危险一无所知——我对这幅画下足了功夫。", "t": [18612, 22125]}, {"fr": "Faites attention aux baobabs !\" C’est pour avertir mes amis d’un danger qu’ils frôlaient depuis longtemps, comme moi-même, sans le connaître, que j’ai tant travaillé ce dessin-là.", "zh": "提醒大家警惕危险，是我义不容辞的责任。", "t": [22125, 33025]}, {"fr": "La leçon que je donnais en valait la peine.", "zh": "也许你们看了这幅画后会纳闷：“为什么他在这本书里画的其他画没有这张猴面包树的画雄壮，有气势？", "t": [33025, 35912]}, {"fr": "Vous vous demanderez peut-être : Pourquoi n’y a-t-il pas, dans ce livre, d’autres dessins aussi grandioses que le dessin des baobabs ?", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [35912, 44550]}, {"fr": "La réponse est bien simple : J’ai essayé mais je n’ai pas pu réussir.", "zh": "”我的回答很简单：我尽了力去画其他的画，但心有余而力不足。", "t": [44550, 49688]}, {"fr": "Quand j’ai dessiné les baobabs j’ai été animé par le sentiment de l’urgence.", "zh": "而画猴面包树的时候，为急迫的需要所激励，我的画便超出了原有的水平。", "t": [49688, 53475]}]}, {"id": "ch05p18", "audio": true, "sents": []}]}, {"id": "ch06", "title_fr": "Chapitre VI", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"fr": "Ah !", "zh": "啊！", "t": [100, 2012]}, {"fr": "petit prince, j’ai compris, peu à peu, ainsi, ta petite vie mélancolique.", "zh": "我就是这样逐渐了解到，你过着并不顺心愉快的生活。", "t": [2012, 7712]}, {"fr": "Tu n’avais eu longtemps pour distraction que la douceur des couchers de soleil.", "zh": "长期以来，你惟一的消遣就是观赏夕阳西下的美景。", "t": [7712, 12088]}, {"fr": "J’ai appris ce détail nouveau, le quatrième jour au matin, quand tu m’as dit :", "zh": "第四天早晨，我又知道了这一件事。", "t": [12088, 16788]}]}, {"id": "ch06p01", "audio": true, "sents": [{"fr": "— J’aime bien les couchers de soleil.", "zh": "你对我说： “我喜欢夕阳。", "t": [100, 3738]}, {"fr": "Allons voir un coucher de soleil…", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [3738, 5387]}]}, {"id": "ch06p02", "audio": true, "sents": [{"fr": "— Mais il faut attendre…", "zh": "我们去看日落的壮观吧……” “可是要等啊……” “等什么？", "t": [100, 2362]}]}, {"id": "ch06p03", "audio": true, "sents": [{"fr": "— Attendre quoi ?", "zh": "” “等太阳下山的时刻呀。", "t": [100, 2750]}]}, {"id": "ch06p04", "audio": true, "sents": [{"fr": "— Attendre que le soleil se couche.", "zh": "” “等太阳下山的时刻呀。", "t": [100, 2987]}]}, {"id": "ch06p05", "audio": true, "sents": [{"fr": "Tu as eu l’air très surpris d’abord, et puis tu as ri de toi-même.", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [100, 4325]}, {"fr": "Et tu m’as dit :", "zh": "” 你露出惊讶的神气，然后又自觉可笑，说道： “我老以为我是在自己家里呢！", "t": [4325, 5775]}]}, {"id": "ch06p06", "audio": true, "sents": [{"fr": "— Je me crois toujours chez moi !", "zh": "” 这话说得不错。", "t": [100, 3212]}]}, {"id": "ch06p07", "audio": true, "sents": [{"fr": "En effet.", "zh": "” 这话说得不错。", "t": [100, 1550]}, {"fr": "Quand il est midi aux États-Unis, le soleil, tout le monde le sait, se couche sur la France.", "zh": "大家都知道，在美国，太阳正在天空的当中，而这时在法国，太阳已经西下。", "t": [1550, 7600]}, {"fr": "Il suffirait de pouvoir aller en France en une minute pour assister au coucher de soleil.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [7600, 12838]}, {"fr": "Malheureusement la France est bien trop éloignée.", "zh": "若能在一分钟之内赶到法国，就可以观看落日的壮景，遗憾的是法国离得太远了。", "t": [12838, 15975]}, {"fr": "Mais, sur ta si petite planète, il te suffisait de tirer ta chaise de quelques pas.", "zh": "但是，在你那小小的星球上，你只要把椅子挪几步就能看到日落了。", "t": [15975, 21350]}, {"fr": "Et tu regardais le crépuscule chaque fois que tu le désirais…", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [21350, 24200]}]}, {"id": "ch06p08", "audio": true, "sents": [{"fr": "— Un jour, j’ai vu le soleil se coucher quarante-trois fois !", "zh": "什么时候要看夕晖都能看得到…… “有一天，我看了四十三次太阳下山！", "t": [100, 4750]}]}, {"id": "ch06p09", "audio": true, "sents": [{"fr": "Et un peu plus tard tu ajoutais :", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 2400]}]}, {"id": "ch06p10", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [100, 1888]}, {"fr": "quand on est tellement triste on aime les couchers de soleil…", "zh": "” 过了一会儿，你又说： “你知道……一个人愁闷的时候，都爱看西下的夕阳……” “看了四十三次太阳西下的那一天，你的心情差得很吧？", "t": [1888, 4325]}]}, {"id": "ch06p11", "audio": true, "sents": [{"fr": "Le jour des quarante-trois fois tu étais donc tellement triste ?", "zh": "” 小王子没有答话。", "t": [100, 4400]}, {"fr": "Mais le petit prince ne répondit pas.", "zh": "” 小王子没有答话。", "t": [4400, 6162]}]}, {"id": "ch06p12", "audio": true, "sents": []}]}, {"id": "ch07", "title_fr": "Chapitre VII", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"fr": "Le cinquième jour, toujours grâce au mouton, ce secret de la vie du petit prince me fut révélé.", "zh": "第五天，仍然是多亏了那只绵羊，小王子生活中的秘密才被泄露了出来。", "t": [100, 6162]}, {"fr": "Il me demanda avec brusquerie, sans préambule, comme le fruit d’un problème longtemps médité en silence :", "zh": "他似乎对一个问题反复思考了许久，然后开门见山，直截了当地突然问我： “绵羊吃灌木，它也吃花吗？", "t": [6162, 12300]}]}, {"id": "ch07p01", "audio": true, "sents": [{"fr": "— Un mouton, s’il mange les arbustes, il mange aussi les fleurs ?", "zh": "他似乎对一个问题反复思考了许久，然后开门见山，直截了当地突然问我： “绵羊吃灌木，它也吃花吗？", "t": [100, 5113]}]}, {"id": "ch07p02", "audio": true, "sents": [{"fr": "— Un mouton mange tout ce qu’il rencontre.", "zh": "” “绵羊遇见什么吃什么。", "t": [100, 3126]}]}, {"id": "ch07p03", "audio": true, "sents": [{"fr": "— Même les fleurs qui ont des épines ?", "zh": "” “带刺的花也吃？", "t": [100, 3350]}]}, {"id": "ch07p04", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” “吃的。", "t": [100, 2400]}, {"fr": "Même les fleurs qui ont des épines.", "zh": "带刺的花也吃。", "t": [2400, 4050]}]}, {"id": "ch07p05", "audio": true, "sents": [{"fr": "— Alors les épines, à quoi servent-elles ?", "zh": "” “那刺还有什么作用呢？", "t": [100, 3800]}]}, {"id": "ch07p06", "audio": true, "sents": [{"fr": "Je ne le savais pas.", "zh": "” 我不知道刺还有什么作用。", "t": [100, 1962]}, {"fr": "J’étais alors très occupé à essayer de dévisser un boulon trop serré de mon moteur.", "zh": "当时我正忙于把发动机上拧得过紧的螺栓弄下来。", "t": [1962, 7075]}, {"fr": "J’étais très soucieux car ma panne commençait de m’apparaître comme très grave, et l’eau à boire qui s’épuisait me faisait craindre le pire.", "zh": "看来故障极其严重，我正在犯愁呢。", "t": [7075, 13762]}]}, {"id": "ch07p07", "audio": true, "sents": [{"fr": "— Les épines, à quoi servent-elles ?", "zh": "“那刺还有什么作用呢？", "t": [100, 3538]}]}, {"id": "ch07p08", "audio": true, "sents": [{"fr": "Le petit prince ne renonçait jamais à une question, une fois qu’il l’avait posée.", "zh": "” 小王子一旦提出疑问，就要寻根究底，追问个没完，绝不会中途而废。", "t": [100, 4950]}, {"fr": "J’étais irrité par mon boulon et je répondis n’importe quoi :", "zh": "我正被螺栓闹得心烦意乱，便顺口答道：“刺不起作用，都是因为花儿心眼太坏！", "t": [4950, 8800]}]}, {"id": "ch07p09", "audio": true, "sents": [{"fr": "— Les épines, ça ne sert à rien, c’est de la pure méchanceté de la part des fleurs !", "zh": "我正被螺栓闹得心烦意乱，便顺口答道：“刺不起作用，都是因为花儿心眼太坏！", "t": [100, 5975]}]}, {"id": "ch07p10", "audio": true, "sents": [{"fr": "— Oh !", "zh": "” “哦？", "t": [100, 2176]}]}, {"id": "ch07p11", "audio": true, "sents": [{"fr": "Mais après un silence il me lança, avec une sorte de rancune :", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [100, 4063]}]}, {"id": "ch07p12", "audio": true, "sents": [{"fr": "— Je ne te crois pas !", "zh": "” 沉默了一会儿，他悻悻地说： “我不信你说的话！", "t": [100, 3625]}, {"fr": "Les fleurs sont faibles.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [3625, 5725]}, {"fr": "Elles sont naïves.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [5725, 7462]}, {"fr": "Elles se rassurent comme elles peuvent.", "zh": "花儿弱不禁风，花儿天真无邪，她们自顾不暇呢。", "t": [7462, 9875]}, {"fr": "Elles se croient terribles avec leurs épines…", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [9875, 11875]}]}, {"id": "ch07p13", "audio": true, "sents": [{"fr": "Je ne répondis rien.", "zh": "她们身上长了刺，是为了给自己壮胆，为了保护自己……” 我不说话。", "t": [100, 2225]}, {"fr": "A cet instant-là je me disais : \"Si ce boulon résiste encore, je le ferai sauter d’un coup de marteau.\" Le petit prince dérangea de nouveau mes réflexions :", "zh": "这时我的念头是：“如果这颗螺栓拧不下来，我就用锤子把它砸了。", "t": [2225, 12438]}]}, {"id": "ch07p14", "audio": true, "sents": [{"fr": "— Et tu crois, toi, que les fleurs…", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [100, 3187]}]}, {"id": "ch07p15", "audio": true, "sents": [{"fr": "— Mais non !", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [100, 3200]}, {"fr": "Mais non !", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [3200, 5312]}, {"fr": "Je ne crois rien !", "zh": "” 小王子打断我的思路： “你相信，你，相信花……” “别烦我了！", "t": [5312, 7900]}, {"fr": "J’ai répondu n’importe quoi.", "zh": "别烦我了！", "t": [7900, 10362]}, {"fr": "Je m’occupe, moi, de choses sérieuses !", "zh": "我什么也不信！", "t": [10362, 13476]}]}, {"id": "ch07p16", "audio": true, "sents": [{"fr": "Il me regarda stupéfiait.", "zh": "我不过在信口开河啊。", "t": [100, 1600]}]}, {"id": "ch07p17", "audio": true, "sents": [{"fr": "— De choses sérieuses !", "zh": "我，我在忙正经事呢。", "t": [100, 2826]}]}, {"id": "ch07p18", "audio": true, "sents": [{"fr": "Il me voyait, mon marteau à la main, et les doigts noirs de cambouis, penché sur un objet qui lui semblait très laid.", "zh": "“你在忙正经事！", "t": [100, 6000]}]}, {"id": "ch07p19", "audio": true, "sents": [{"fr": "— Tu parles comme les grandes personnes !", "zh": "” 他看见我手攥锤子，两手油污，俯身对着一件他认为很丑的物件。", "t": [100, 3375]}]}, {"id": "ch07p20", "audio": true, "sents": [{"fr": "Ça me fit un peu honte.", "zh": "“你说话的时候像个大人！", "t": [100, 2250]}, {"fr": "Mais, impitoyable, il ajouta :", "zh": "“你说话的时候像个大人！", "t": [2250, 5250]}]}, {"id": "ch07p21", "audio": true, "sents": [{"fr": "— Tu confonds tout…", "zh": "“你说话的时候像个大人！", "t": [100, 2162]}, {"fr": "tu mélanges tout !", "zh": "” 听了这话，我有点难为情。", "t": [2162, 3675]}]}, {"id": "ch07p22", "audio": true, "sents": [{"fr": "Il était vraiment très irrité.", "zh": "” 听了这话，我有点难为情。", "t": [100, 2550]}, {"fr": "Il secouait au vent des cheveux tout dorés :", "zh": "然而他又毫不留情地讲了一句： “你是非不分……你混淆黑白！", "t": [2550, 5162]}]}, {"id": "ch07p23", "audio": true, "sents": [{"fr": "— Je connais une planète où il y a un Monsieur cramoisi.", "zh": "” 他真的气坏了。", "t": [100, 4450]}, {"fr": "Il n’a jamais respiré une fleur.", "zh": "一头金发在风中乱摇。", "t": [4450, 7125]}, {"fr": "Il n’a jamais regardé une étoile.", "zh": "一头金发在风中乱摇。", "t": [7125, 9838]}, {"fr": "Il n’a jamais aimé personne.", "zh": "“我知道一颗行星，上面有一位红脸先生。", "t": [9838, 12225]}, {"fr": "Il n’a jamais rien fait d’autre que des additions.", "zh": "他从未嗅过一朵花。", "t": [12225, 15325]}, {"fr": "Et toute la journée il répète comme toi : \"Je suis un homme sérieux !", "zh": "他从未爱过一个人。", "t": [15325, 20938]}, {"fr": "Je suis un homme sérieux !\" et ça le fait gonfler d’orgueil.", "zh": "他什么事也没干过，只会做算术中的加法。", "t": [20938, 25638]}, {"fr": "Mais ce n’est pas un homme, c’est un champignon !", "zh": "他整天就像你一样，反复地唠叨：‘我是个正经人！", "t": [25638, 28562]}]}, {"id": "ch07p24", "audio": true, "sents": [{"fr": "— Un quoi ?", "zh": "他整天就像你一样，反复地唠叨：‘我是个正经人！", "t": [100, 2412]}]}, {"id": "ch07p25", "audio": true, "sents": [{"fr": "— Un champignon !", "zh": "我是正经人！", "t": [100, 2687]}]}, {"id": "ch07p26", "audio": true, "sents": [{"fr": "Le petit prince était maintenant tout pâle de colère.", "zh": "’真是自命不凡，神气活现！", "t": [100, 2662]}]}, {"id": "ch07p27", "audio": true, "sents": [{"fr": "— Il y a des millions d’années que les fleurs fabriquent des épines.", "zh": "可他不是人，是蘑菇！", "t": [100, 4625]}, {"fr": "Il y a des millions d’années que les moutons mangent quand même les fleurs.", "zh": "” 小王子气得脸色发白。", "t": [4625, 8500]}, {"fr": "Et ce n’est pas sérieux de chercher à comprendre pourquoi elles se donnent tant de mal pour se fabriquer des épines qui ne servent jamais à rien ?", "zh": "“几百万年以来，花儿都长着刺；几百万年以来，羊也在吃花。", "t": [8500, 16288]}, {"fr": "Ce n’est pas important la guerre des moutons et des fleurs ?", "zh": "这不比红脸胖子的加法更正经，更重要吗？", "t": [16288, 20250]}, {"fr": "Ce n’est pas plus sérieux et plus important que les additions d’un gros Monsieur rouge ?", "zh": "这不比红脸胖子的加法更正经，更重要吗？", "t": [20250, 25388]}, {"fr": "Et si je connais, moi, une fleur unique au monde, qui n’existe nulle part, sauf dans ma planète, et qu’un petit mouton peut anéantir d’un seul coup, comme ça, un matin, sans se rendre compte de ce qu’il fait, ce n’est pas important ça !", "zh": "要是我认识的世界上的一朵独一无二的花，她哪儿也不去，就爱长在我的星球上，可是却在某天早晨，被小绵羊一不留神咬死了，难道这样的事也不重要吗？", "t": [25388, 38912]}]}, {"id": "ch07p28", "audio": true, "sents": [{"fr": "Il rougit, puis reprit :", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [100, 2262]}]}, {"id": "ch07p29", "audio": true, "sents": [{"fr": "— Si quelqu’un aime une fleur qui n’existe qu’à un exemplaire dans les millions et les millions d’étoiles, ça suffit pour qu’il soit heureux quand il les regarde.", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [100, 9375]}, {"fr": "Il se dit : \"Ma fleur est là quelque part…\" Mais si le mouton mange la fleur, c’est pour lui comme si, brusquement, toutes les étoiles s’éteignaient !", "zh": "” 他的脸由白转红，然后说： “要是有个人爱上了一朵花，这朵花不长在亿万颗星球上，只长在他的星球上，而他只要仰望星空，想到‘我的花儿就在那儿……’，心就陶醉在幸福里，羊却吃了他心爱的花——这对他而言，简直是整个星空都黯淡无光了，难道这样的事还不重要吗？", "t": [9375, 19975]}, {"fr": "Et ce n’est pas important ça !", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [19975, 21937]}]}, {"id": "ch07p30", "audio": true, "sents": [{"fr": "Il ne put rien dire de plus.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [100, 2275]}, {"fr": "Il éclata brusquement en sanglots.", "zh": "” 他说不出话来，突然嚎啕大哭。", "t": [2275, 4962]}, {"fr": "La nuit était tombée.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [4962, 6950]}, {"fr": "J’avais lâché mes outils.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [6950, 9188]}, {"fr": "Je me moquais bien de mon marteau, de mon boulon, de la soif et de la mort.", "zh": "夜幕降临，我扔下手里的工具，顾不得锤子、螺栓、干渴、死亡了。", "t": [9188, 14162]}, {"fr": "Il y avait, sur une étoile, une planète, la mienne, la Terre, un petit prince à consoler !", "zh": "在一颗星球上，在我的行星地球上，有一个小王子需要安慰！", "t": [14162, 21125]}, {"fr": "Je le pris dans les bras.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [21125, 23112]}, {"fr": "Je le berçai.", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [23112, 24900]}, {"fr": "Je lui disais : \"La fleur que tu aimes n’est pas en danger…", "zh": "我把他搂进怀里，轻柔地摇着他。", "t": [24900, 29288]}, {"fr": "Je lui dessinerai une muselière, à ton mouton…", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [29288, 32888]}, {"fr": "Je te dessinerai une armure pour ta fleur…", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [32888, 36075]}, {"fr": "Je…\" Je ne savais pas trop quoi dire.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [36075, 39838]}, {"fr": "Je me sentais très maladroit.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [39838, 42275]}, {"fr": "Je ne savais comment l’atteindre, où le rejoindre…", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [42275, 45675]}, {"fr": "C’est tellement mystérieux, le pays des larmes.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [45675, 48212]}]}]}, {"id": "ch08", "title_fr": "Chapitre VIII", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"fr": "J’appris bien vite à mieux connaître cette fleur.", "zh": "我很快就对这朵花有了更深的了解。", "t": [100, 3400]}, {"fr": "Il y avait toujours eu, sur la planète du petit prince, des fleurs très simples, ornées d’un seul rang de pétales, et qui ne tenaient point de place, et qui ne dérangeaient personne.", "zh": "小王子生活的星球上长着很朴素的单瓣花，她们一点儿也不占地方，也不扰人，在草地上朝开暮落。", "t": [3400, 13575]}, {"fr": "Elles apparaissaient un matin dans l’herbe, et puis elles s’éteignaient le soir.", "zh": "小王子密切注视着她的与众不同的嫩枝。", "t": [13575, 17988]}, {"fr": "Mais celle-là avait germé un jour, d’une graine apportée d’on ne sait où, et le petit prince avait surveillé de très près cette brindille qui ne ressemblait pas aux autres brindilles.", "zh": "然而枝条很快就停止伸展，竟开始结花蕾。", "t": [17988, 27038]}, {"fr": "Ça pouvait être un nouveau genre de baobab.", "zh": "小王子看着硕大的花苞，预感到她会绽放出奇异的花朵。", "t": [27038, 30038]}, {"fr": "Mais l’arbuste cessa vite de croître, et commença de préparer une fleur.", "zh": "然而花儿躲在绿莹莹的屋子里精心打扮。", "t": [30038, 34938]}, {"fr": "Le petit prince, qui assistait à l’installation d’un bouton énorme, sentait bien qu’il en sortirait une apparition miraculeuse, mais la fleur n’en finissait pas de se préparer à être belle, à l’abri de sa chambre verte.", "zh": "她不肯像虞美人那样，皱巴巴地就往外跑，就亮相。", "t": [34938, 47300]}, {"fr": "Elle choisissait avec soin ses couleurs.", "zh": "不错，她就是朵极爱俏的花儿。", "t": [47300, 50262]}, {"fr": "Elle s’habillait lentement, elle ajustait un à un ses pétales.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [50262, 54188]}, {"fr": "Elle ne voulait pas sortir toute fripée comme les coquelicots.", "zh": "她神秘兮兮地梳妆打扮了好几天，终于在一天早晨，在太阳出来的那一刻，她露脸亮相了。", "t": [54188, 57838]}, {"fr": "Elle ne voulait apparaître que dans le plein rayonnement de sa beauté.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [57838, 61762]}, {"fr": "Eh !", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [61762, 63650]}, {"fr": "oui.", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [63650, 64912]}, {"fr": "Elle était très coquette !", "zh": "精心打扮了几天，算准了出场的时间，她却打着哈欠说： “唉！", "t": [64912, 67488]}, {"fr": "Sa toilette mystérieuse avait donc duré des jours et des jours.", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [67488, 71625]}, {"fr": "Et puis voici qu’un matin, justement à l’heure du lever du soleil, elle s’était montrée.", "zh": "我刚刚睡醒呢……请你原谅……我的妆还零乱呢……” 小王子忍不住赞叹： “您真美啊！", "t": [71625, 76237]}]}, {"id": "ch08p01", "audio": true, "sents": [{"fr": "Et elle, qui avait travaillé avec tant de précision, dit en bâillant :", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 4413]}]}, {"id": "ch08p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [100, 3038]}, {"fr": "Je me réveille à peine…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [3038, 5200]}, {"fr": "Je vous demande pardon…", "zh": "” “是吗，”花儿柔声说，“我和太阳同时诞生……” 小王子看准她并非谦恭的女子，不过，她确实美丽动人！", "t": [5200, 7300]}, {"fr": "Je suis encore toute décoiffée…", "zh": "“是吃早点的时候了吧。", "t": [7300, 8950]}]}, {"id": "ch08p03", "audio": true, "sents": [{"fr": "Le petit prince, alors, ne put contenir son admiration :", "zh": "“是吃早点的时候了吧。", "t": [100, 4488]}]}, {"id": "ch08p04", "audio": true, "sents": [{"fr": "— Que vous êtes belle !", "zh": "”很快她又说。", "t": [100, 2638]}]}, {"id": "ch08p05", "audio": true, "sents": [{"fr": "— N’est-ce pas, répondit doucement la fleur.", "zh": "”很快她又说。", "t": [100, 4350]}, {"fr": "Et je suis née en même temps que le soleil…", "zh": "“劳驾您给我……” 小王子为自己的疏忽而感到羞惭，赶紧找了一壶清水，侍候花儿用餐。", "t": [4350, 6225]}]}, {"id": "ch08p06", "audio": true, "sents": [{"fr": "Le petit prince devina bien qu’elle n’était pas trop modeste, mais elle était si émouvante !", "zh": "不久，她爱慕虚荣的性情开始折磨他。", "t": [100, 4937]}]}, {"id": "ch08p07", "audio": true, "sents": [{"fr": "— C’est l’heure, je crois, du petit déjeuner, avait-elle bientôt ajouté, auriez-vous la bonté de penser à moi…", "zh": "例如，有一天，她对小王子说到她身上长的四根刺的用途。", "t": [100, 7313]}]}, {"id": "ch08p08", "audio": true, "sents": [{"fr": "Et le petit prince, tout confus, ayant été chercher un arrosoir d’eau fraîche, avait servi la fleur.", "zh": "她说： “这儿也许有老虎吧，老虎的爪子锋利得很呢！", "t": [100, 5774]}]}, {"id": "ch08p09", "audio": true, "sents": [{"fr": "Ainsi l’avait-elle bien vite tourmenté par sa vanité un peu ombrageuse.", "zh": "再说，老虎不吃草。", "t": [100, 4450]}, {"fr": "Un jour, par exemple, parlant de ses quatre épines, elle avait dit au petit prince :", "zh": "“我可不是草。", "t": [4450, 9674]}]}, {"id": "ch08p10", "audio": true, "sents": [{"fr": "— Ils peuvent venir, les tigres, avec leurs griffes !", "zh": "“对不起……” “我一点也不畏惧老虎，但我讨厌风。", "t": [100, 4500]}]}, {"id": "ch08p11", "audio": true, "sents": [{"fr": "— Il n’y a pas de tigres sur ma planète, avait objecté le petit prince, et puis les tigres ne mangent pas l’herbe.", "zh": "” “你居然讨厌风啊……这可不好。", "t": [100, 6713]}]}, {"id": "ch08p12", "audio": true, "sents": [{"fr": "— Je ne suis pas une herbe, avait doucement répondu la fleur.", "zh": "”小王子对她有了看法。", "t": [100, 4237]}]}, {"id": "ch08p13", "audio": true, "sents": [{"fr": "— Pardonnez-moi…", "zh": "“这朵花倒很复杂……” “晚上您用罩子把我罩起来吧。", "t": [100, 1963]}]}, {"id": "ch08p14", "audio": true, "sents": [{"fr": "— Je ne crains rien des tigres, mais j’ai horreur des courants d’air.", "zh": "您这儿太冷，位置不好。", "t": [100, 5250]}, {"fr": "Vous n’auriez pas un paravent ?", "zh": "我来的那个地方……” 她住了口。", "t": [5250, 7338]}]}, {"id": "ch08p15", "audio": true, "sents": [{"fr": "\"Horreur des courants d’air…", "zh": "我来的那个地方……” 她住了口。", "t": [100, 1525]}, {"fr": "ce n’est pas de chance, pour une plante, avait remarqué le petit prince.", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [1525, 6362]}, {"fr": "Cette fleur est bien compliquée…\"", "zh": "来这儿的时候她还是一颗种子呢，怎么可能了解别的地方呢。", "t": [6362, 7975]}]}, {"id": "ch08p16", "audio": true, "sents": [{"fr": "— Le soir vous me mettrez sous globe.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [100, 3738]}, {"fr": "Il fait très froid chez vous.", "zh": "她撒的谎幼稚可笑，让人一下子就能识破。", "t": [3738, 5788]}, {"fr": "C’est mal installé.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [5788, 7712]}, {"fr": "Là d’où je viens…", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [7712, 8650]}]}, {"id": "ch08p17", "audio": true, "sents": [{"fr": "Mais elle s’était interrompue.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [100, 2325]}, {"fr": "Elle était venue sous forme de graine.", "zh": "她觉得丢脸，便咳嗽了两三声，想把过错推到小王子身上去： “我要的屏风呢？", "t": [2325, 4975]}, {"fr": "Elle n’avait rien pu connaître des autres mondes.", "zh": "……” “我正要去找屏风，是您和我说话的呀！", "t": [4975, 8075]}, {"fr": "Humiliée de s’être laissé surprendre à préparer un mensonge aussi naïf, elle avait toussé deux ou trois fois, pour mettre le petit prince dans son tort :", "zh": "” 她又故意咳嗽，存心让他内疚不安。", "t": [8075, 15888]}]}, {"id": "ch08p18", "audio": true, "sents": [{"fr": "— Ce paravent ?…", "zh": "小王子很怜爱她，但她的做作令他生疑。", "t": [100, 2563]}]}, {"id": "ch08p19", "audio": true, "sents": [{"fr": "— J’allais le chercher mais vous me parliez !", "zh": "他是个做事一丝不苟的人，常把无关紧要的闲话当真，难免招来不少麻烦。", "t": [100, 3663]}]}, {"id": "ch08p20", "audio": true, "sents": [{"fr": "Alors elle avait forcé sa toux pour lui infliger quand même des remords.", "zh": "他是个做事一丝不苟的人，常把无关紧要的闲话当真，难免招来不少麻烦。", "t": [100, 3337]}]}, {"id": "ch08p21", "audio": true, "sents": [{"fr": "Ainsi le petit prince, malgré la bonne volonté de son amour, avait vite douté d’elle.", "zh": "有一天，他向我倾诉他的心事：“我本不该听信她的话的。", "t": [100, 5888]}, {"fr": "Il avait pris au sérieux des mots sans importance, et était devenu très malheureux.", "zh": "她们的作用就是供人观赏，供人嗅闻。", "t": [5888, 9962]}]}, {"id": "ch08p22", "audio": true, "sents": [{"fr": "\"J’aurais dû ne pas l’écouter, me confia-t-il un jour, il ne faut jamais écouter les fleurs.", "zh": "我的花熏香了我的星球，但我不懂得为此高兴。", "t": [100, 5812]}, {"fr": "Il faut les regarder et les respirer.", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [5812, 8562]}, {"fr": "La mienne embaumait ma planète, mais je ne savais pas m’en réjouir.", "zh": "她说的老虎爪子的话，本来应该打动我的心，我却生了她的气。", "t": [8562, 12888]}, {"fr": "Cette histoire de griffes, qui m’avait tellement agacé, eût dû m’attendrir…\"", "zh": "” 他还说： “那时我真是不懂事。", "t": [12888, 16912]}]}, {"id": "ch08p23", "audio": true, "sents": [{"fr": "Il me confia encore :", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 1962]}]}, {"id": "ch08p24", "audio": true, "sents": [{"fr": "\"Je n’ai alors rien su comprendre !", "zh": "要对一个人下定论，不应听其言，而应观其行。", "t": [100, 3288]}, {"fr": "J’aurais dû la juger sur les actes et non sur les mots.", "zh": "她芬芳馥郁，赏心悦目，我不应抛下她一走了之！", "t": [3288, 6612]}, {"fr": "Elle m’embaumait et m’éclairait.", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [6612, 8862]}, {"fr": "Je n’aurais jamais dû m’enfuir !", "zh": "我不理解她那不聪明的谎言饱含的深情。", "t": [8862, 11825]}, {"fr": "J’aurais dû deviner sa tendresse derrière ses pauvres ruses.", "zh": "花儿是缺点不少、但优点也很多的矛盾的东西！", "t": [11825, 15562]}, {"fr": "Les fleurs sont si contradictoires !", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [15562, 18775]}, {"fr": "Mais j’étais trop jeune pour savoir l’aimer.\"", "zh": "那时我年纪太轻，不懂得珍惜她，爱她。", "t": [18775, 20712]}]}, {"id": "ch08p25", "audio": true, "sents": []}, {"id": "ch08p26", "audio": true, "sents": []}]}, {"id": "ch09", "title_fr": "Chapitre IX", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"fr": "Je crois qu’il profita, pour son évasion, d’une migration d’oiseaux sauvages.", "zh": "我估计他是趁候鸟迁徙时出走的。", "t": [100, 5275]}, {"fr": "Au matin du départ il mit sa planète bien en ordre.", "zh": "出走的那天早晨，他认真收拾整理他的星球，仔细疏通火山口。", "t": [5275, 8788]}, {"fr": "Il ramona soigneusement ses volcans en activité.", "zh": "他有两座活火山，热早饭挺方便的。", "t": [8788, 12388]}, {"fr": "Il possédait deux volcans en activité.", "zh": "他还有一座死火山。", "t": [12388, 15375]}, {"fr": "Et c’était bien commode pour faire chauffer le petit déjeuner du matin.", "zh": "可是正如他说的：“日后的事很难说！", "t": [15375, 19450]}, {"fr": "Il possédait aussi un volcan éteint.", "zh": "”谁知道死火山会不会变活呢？", "t": [19450, 22275]}, {"fr": "Mais, comme il disait, \"On ne sait jamais !\" Il ramona donc également le volcan éteint.", "zh": "经过疏通，火山里的火焰缓缓燃烧，火山就不会喷发。", "t": [22275, 29275]}, {"fr": "S’ils sont bien ramonés, les volcans brûlent doucement et régulièrement, sans éruptions.", "zh": "火山喷发的道理与炉火一样。", "t": [29275, 34738]}, {"fr": "Les éruptions volcaniques sont comme des feux de cheminée.", "zh": "我们这些人太渺小，没有疏通火山的能力，所以火山才给我们造成很多麻烦。", "t": [34738, 38525]}, {"fr": "Évidemment sur notre terre nous sommes beaucoup trop petits pour ramoner nos volcans.", "zh": "小王子闷闷地拔除了最后几棵猴面包树苗。", "t": [38525, 43138]}, {"fr": "C’est pourquoi ils nous causent des tas d’ennuis.", "zh": "他知道自己不会再回来了。", "t": [43138, 45250]}]}, {"id": "ch09p01", "audio": true, "sents": [{"fr": "Le petit prince arracha aussi, avec un peu de mélancolie, les dernières pousses de baobabs.", "zh": "那天早晨，他觉得所有的家务活干起来都挺亲切的。", "t": [100, 6162]}, {"fr": "Il croyait ne jamais devoir revenir.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他竟觉得他想哭。", "t": [6162, 9050]}, {"fr": "Mais tous ces travaux familiers lui parurent, ce matin-là, extrêmement doux.", "zh": "他对花儿说：“别了。", "t": [9050, 13875]}, {"fr": "Et, quand il arrosa une dernière fois la fleur, et se prépara à la mettre à l’abri sous son globe, il se découvrit l’envie de pleurer.", "zh": "花儿咳嗽，可不是因为着了凉。", "t": [13875, 20913]}]}, {"id": "ch09p02", "audio": true, "sents": [{"fr": "— Adieu, dit-il à la fleur.", "zh": "好好地享受生活吧，愿你幸福。", "t": [100, 2875]}]}, {"id": "ch09p03", "audio": true, "sents": [{"fr": "Mais elle ne lui répondit pas.", "zh": "好好地享受生活吧，愿你幸福。", "t": [100, 1450]}]}, {"id": "ch09p04", "audio": true, "sents": [{"fr": "— Adieu, répéta-t-il.", "zh": "” 她并没有责备他的意思。", "t": [100, 2762]}]}, {"id": "ch09p05", "audio": true, "sents": [{"fr": "La fleur toussa.", "zh": "他觉得挺意外。", "t": [100, 1950]}, {"fr": "Mais ce n’était pas à cause de son rhume.", "zh": "他觉得挺意外。", "t": [1950, 3724]}]}, {"id": "ch09p06", "audio": true, "sents": [{"fr": "— J’ai été sotte, lui dit-elle enfin.", "zh": "他不知所措地站在那儿，高举着罩子。", "t": [100, 4000]}, {"fr": "Je te demande pardon.", "zh": "他不理解她的脉脉深情。", "t": [4000, 6138]}, {"fr": "Tâche d’être heureux.", "zh": "他不理解她的脉脉深情。", "t": [6138, 7124]}]}, {"id": "ch09p07", "audio": true, "sents": [{"fr": "Il fut surpris par l’absence de reproches.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [100, 3162]}, {"fr": "Il restait là tout déconcerté, le globe en l’air.", "zh": "“是的，我爱你，”花儿对他说，“你丝毫没察觉到我对你的爱，这是我的错。", "t": [3162, 6775]}, {"fr": "Il ne comprenait pas cette douceur calme.", "zh": "如今说也没用了。", "t": [6775, 8712]}]}, {"id": "ch09p08", "audio": true, "sents": [{"fr": "— Mais oui, je t’aime, lui dit la fleur.", "zh": "你和我一样傻。", "t": [100, 4388]}, {"fr": "Tu n’en as rien su, par ma faute.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [4388, 7338]}, {"fr": "Cela n’a aucune importance.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [7338, 9825]}, {"fr": "Mais tu as été aussi sot que moi.", "zh": "好好地享受生活吧，愿你幸福……你把这罩子放一边去吧，我不需要它。", "t": [9825, 12438]}, {"fr": "Tâche d’être heureux…", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [12438, 14262]}, {"fr": "Laisse ce globe tranquille.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [14262, 16638]}, {"fr": "Je n’en veux plus.", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [16638, 17562]}]}, {"id": "ch09p09", "audio": true, "sents": [{"fr": "— Mais le vent…", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 1713]}]}, {"id": "ch09p10", "audio": true, "sents": [{"fr": "— Je ne suis pas si enrhumée que ça…", "zh": "” “可是风……” “我并非如此的弱不禁风……清新的夜风对我的健康有好处，我是一朵花儿嘛。", "t": [100, 3575]}, {"fr": "L’air frais de la nuit me fera du bien.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [3575, 6300]}, {"fr": "Je suis une fleur.", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [6300, 7413]}]}, {"id": "ch09p11", "audio": true, "sents": [{"fr": "— Mais les bêtes…", "zh": "” “可是动物……” “如果我想认识蝴蝶，就必须能承受两三条毛虫。", "t": [100, 1912]}]}, {"id": "ch09p12", "audio": true, "sents": [{"fr": "— Il faut bien que je supporte deux ou trois chenilles si je veux connaître les papillons.", "zh": "这似乎是很美的事。", "t": [100, 5925]}, {"fr": "Il paraît que c’est tellement beau.", "zh": "你呢，又快离我而去了。", "t": [5925, 8188]}, {"fr": "Sinon qui me rendra visite ?", "zh": "你呢，又快离我而去了。", "t": [8188, 11175]}, {"fr": "Tu seras loin, toi.", "zh": "我一点不畏惧大的动物，我有爪子呀。", "t": [11175, 13500]}, {"fr": "Quant aux grosses bêtes, je ne crains rien.", "zh": "” 她天真地伸出她的四根刺。", "t": [13500, 16400]}, {"fr": "J’ai mes griffes.", "zh": "” 她天真地伸出她的四根刺。", "t": [16400, 17288]}]}, {"id": "ch09p13", "audio": true, "sents": [{"fr": "Et elle montrait naïvement ses quatre épines.", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [100, 2988]}, {"fr": "Puis elle ajouta :", "zh": "然后又说： “别婆婆妈妈，磨磨蹭蹭的了，闹得人心乱。", "t": [2988, 4700]}]}, {"id": "ch09p14", "audio": true, "sents": [{"fr": "— Ne traîne pas comme ça, c’est agaçant.", "zh": "你既已下了决心，那就走吧。", "t": [100, 4050]}, {"fr": "Tu as décidé de partir.", "zh": "你既已下了决心，那就走吧。", "t": [4050, 6412]}, {"fr": "Va-t’en.", "zh": "你既已下了决心，那就走吧。", "t": [6412, 6924]}]}, {"id": "ch09p15", "audio": true, "sents": [{"fr": "Car elle ne voulait pas qu’il la vît pleurer.", "zh": "” 她不愿让小王子看见她哭。", "t": [100, 2812]}, {"fr": "C’était une fleur tellement orgueilleuse…", "zh": "她是一朵多么骄傲的花儿哟……", "t": [2812, 4637]}]}, {"id": "ch09p16", "audio": true, "sents": []}, {"id": "ch09p17", "audio": true, "sents": []}, {"id": "ch09p18", "audio": true, "sents": []}, {"id": "ch09p19", "audio": true, "sents": []}, {"id": "ch09p20", "audio": true, "sents": []}, {"id": "ch09p21", "audio": true, "sents": []}, {"id": "ch09p22", "audio": true, "sents": []}, {"id": "ch09p23", "audio": true, "sents": []}, {"id": "ch09p24", "audio": true, "sents": []}]}, {"id": "ch10", "title_fr": "Chapitre X", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"fr": "Il se trouvait dans la région des astéroïdes 325, 326, 327, 328, 329 et 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 9888]}, {"fr": "Il commença donc par les visiter pour y chercher une occupation et pour s’instruire.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [9888, 14150]}]}, {"id": "ch10p01", "audio": true, "sents": [{"fr": "La première était habitée par un roi.", "zh": "于是他决定首先拜访它们，在那儿找事干，并增长见识。", "t": [100, 2912]}, {"fr": "Le roi siégeait, habillé de pourpre et d’hermine, sur un trône très simple et cependant majestueux.", "zh": "325号行星上住着一位国王。", "t": [2912, 8050]}]}, {"id": "ch10p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [100, 3038]}, {"fr": "Voilà un sujet, s’écria le roi quand il aperçut le petit prince.", "zh": "他穿着镶有紫红色袖口和领口的白鼬皮衣服，坐在式样简单然而威严的宝座上。", "t": [3038, 6900]}]}, {"id": "ch10p03", "audio": true, "sents": [{"fr": "Et le petit prince se demanda :", "zh": "看见小王子，国王大声嚷： “哈！", "t": [100, 2500]}]}, {"id": "ch10p04", "audio": true, "sents": [{"fr": "— Comment peut-il me reconnaître puisqu’il ne m’a encore jamais vu !", "zh": "来了一个老百姓。", "t": [100, 4838]}]}, {"id": "ch10p05", "audio": true, "sents": [{"fr": "Il ne savait pas que, pour les rois, le monde est très simplifié.", "zh": "” 小王子心想： “他从未见过我，怎么认得出我呢？", "t": [100, 4325]}, {"fr": "Tous les hommes sont des sujets.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [4325, 5675]}]}, {"id": "ch10p06", "audio": true, "sents": [{"fr": "— Approche-toi que je te voie mieux, lui dit le roi qui était tout fier d’être roi pour quelqu’un.", "zh": "” 他不知道，国王们把世界看得很简单，他们以为普天下的人都是他的百姓。", "t": [100, 5612]}]}, {"id": "ch10p07", "audio": true, "sents": [{"fr": "Le petit prince chercha des yeux où s’asseoir, mais la planète était toute encombrée par le magnifique manteau d’hermine.", "zh": "他对小王子说：“过来，让我好好地瞧瞧你。", "t": [100, 6812]}, {"fr": "Il resta donc debout, et, comme il était fatigué, il bâilla.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [6812, 10574]}]}, {"id": "ch10p08", "audio": true, "sents": [{"fr": "— Il est contraire à l’étiquette de bâiller en présence d’un roi, lui dit le monarque.", "zh": "” 小王子用眼睛搜寻可坐之处，可是行星被国王豪华的鼬皮塞满了，他只好站着，因为累了，他打了个哈欠。", "t": [100, 6250]}, {"fr": "Je te l’interdis.", "zh": "“在国王面前打哈欠，违反礼节，我不准你打哈欠。", "t": [6250, 7350]}]}, {"id": "ch10p09", "audio": true, "sents": [{"fr": "— Je ne peux pas m’en empêcher, répondit le petit prince tout confus.", "zh": "”国王说道。", "t": [100, 5538]}, {"fr": "J’ai fait un long voyage et je n’ai pas dormi…", "zh": "小王子抱歉地说：“我不是有意的。", "t": [5538, 7575]}]}, {"id": "ch10p10", "audio": true, "sents": [{"fr": "— Alors, lui dit le roi, je t’ordonne de bâiller.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [100, 4888]}, {"fr": "Je n’ai vu personne bâiller depuis des années.", "zh": "我长途跋涉，没有睡眠……” “既然如此，”国王对他说，“我命令你打哈欠。", "t": [4888, 7950]}, {"fr": "Les bâillements sont pour moi des curiosités.", "zh": "我已经多年没看见别人打哈欠了。", "t": [7950, 11050]}, {"fr": "Allons !", "zh": "我已经多年没看见别人打哈欠了。", "t": [11050, 13125]}, {"fr": "bâille encore.", "zh": "依我看，打哈欠挺好玩的。", "t": [13125, 14850]}, {"fr": "C’est un ordre.", "zh": "依我看，打哈欠挺好玩的。", "t": [14850, 15737]}]}, {"id": "ch10p11", "audio": true, "sents": [{"fr": "— Ça m’intimide…", "zh": "快！", "t": [100, 2300]}, {"fr": "je ne peux plus…", "zh": "打吧！", "t": [2300, 3162]}, {"fr": "fit le petit prince tout rougissant.", "zh": "这是命令。", "t": [3162, 4713]}]}, {"id": "ch10p12", "audio": true, "sents": [{"fr": "— Hum !", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [100, 2962]}, {"fr": "Hum !", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [2962, 4350]}, {"fr": "répondit le roi.", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [4350, 6125]}, {"fr": "Alors je…", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [6125, 6950]}, {"fr": "je t’ordonne tantôt de bâiller et tantôt de…", "zh": "” “您的命令让我害怕……我打不了……”小王子涨红了脸。", "t": [6950, 9087]}]}, {"id": "ch10p13", "audio": true, "sents": [{"fr": "Il bredouillait un peu et paraissait vexé.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 2225]}]}, {"id": "ch10p14", "audio": true, "sents": [{"fr": "Car le roi tenait essentiellement à ce que son autorité fût respectée.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [100, 4500]}, {"fr": "Il ne tolérait pas la désobéissance.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [4500, 7300]}, {"fr": "C’était un monarque absolu.", "zh": "“嗯，嗯，”国王说，“那么我……我命令你一会儿打，一会儿不打……” 显然，挨了小王子的冲撞，他有点气恼，话也说不流利了。", "t": [7300, 9638]}, {"fr": "Mais, comme il était très bon, il donnait des ordres raisonnables.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [9638, 13012]}]}, {"id": "ch10p15", "audio": true, "sents": [{"fr": "\"Si j’ordonnais, disait-il couramment, si j’ordonnais à un général de se changer en oiseau de mer, et si le général n’obéissait pas, ce ne serait pas la faute du général.", "zh": "国王最关心的是别人尊重他的权威，他不允许别人违抗他的命令，他是一个典型的专制君王，但他毕竟是个善良之辈，下达的命令都合乎情理。", "t": [100, 10600]}, {"fr": "Ce serait ma faute.\"", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [10600, 11738]}]}, {"id": "ch10p16", "audio": true, "sents": [{"fr": "— Puis-je m’asseoir ?", "zh": "“要是我向一个将军下令，要他变成海鸟，将军是不愿服从的。", "t": [100, 3450]}, {"fr": "s’enquit timidement le petit prince.", "zh": "这样，错不在将军，错在我身上。", "t": [3450, 5325]}]}, {"id": "ch10p17", "audio": true, "sents": [{"fr": "— Je t’ordonne de t’asseoir, lui répondit le roi, qui ramena majestueusement un pan de son manteau d’hermine.", "zh": "“我可以坐下来吗？", "t": [100, 6837]}]}, {"id": "ch10p18", "audio": true, "sents": [{"fr": "Mais le petit prince s’étonnait.", "zh": "“我命令你坐下。", "t": [100, 2500]}, {"fr": "La planète était minuscule.", "zh": "”国王说，他威风凛凛地一挥白鼬皮皇袍的下摆。", "t": [2500, 5000]}, {"fr": "Sur quoi le roi pouvait-il bien régner ?", "zh": "”国王说，他威风凛凛地一挥白鼬皮皇袍的下摆。", "t": [5000, 7650]}]}, {"id": "ch10p19", "audio": true, "sents": [{"fr": "— Sire, lui dit-il…", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 2662]}, {"fr": "je vous demande pardon de vous interroger…", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [2662, 4587]}]}, {"id": "ch10p20", "audio": true, "sents": [{"fr": "— Je t’ordonne de m’interroger, se hâta de dire le roi.", "zh": "小王子有个问题弄不明白：这颗星球小得惊人，国王统治什么？", "t": [100, 4076]}]}, {"id": "ch10p21", "audio": true, "sents": [{"fr": "— Sire…", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [100, 1712]}, {"fr": "sur quoi régnez-vous ?", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [1712, 3374]}]}, {"id": "ch10p22", "audio": true, "sents": [{"fr": "— Sur tout, répondit le roi, avec une grande simplicité.", "zh": "“陛下……”他说，“请原谅我向您提个问题……” “我命令你向我提问题……”国王急忙说。", "t": [100, 4587]}]}, {"id": "ch10p23", "audio": true, "sents": [{"fr": "— Sur tout ?", "zh": "“陛下……您统治什么？", "t": [100, 2350]}]}, {"id": "ch10p24", "audio": true, "sents": [{"fr": "Le roi d’un geste discret désigna sa planète, les autres planètes et les étoiles.", "zh": "” “统治一切！", "t": [100, 4750]}]}, {"id": "ch10p25", "audio": true, "sents": [{"fr": "— Sur tout ça ?", "zh": "” 国王指指他的星球，其他星球，所有的星球。", "t": [100, 2838]}, {"fr": "dit le petit prince.", "zh": "” 国王指指他的星球，其他星球，所有的星球。", "t": [2838, 3826]}]}, {"id": "ch10p26", "audio": true, "sents": [{"fr": "— Sur tout ça…", "zh": "“所有这一切？", "t": [100, 2112]}, {"fr": "répondit le roi.", "zh": "“所有这一切？", "t": [2112, 3013]}]}, {"id": "ch10p27", "audio": true, "sents": [{"fr": "Car non seulement c’était un monarque absolu mais c’était un monarque universel.", "zh": "“所有这一切……”国王答道。", "t": [100, 3950]}]}, {"id": "ch10p28", "audio": true, "sents": [{"fr": "— Et les étoiles vous obéissent ?", "zh": "因为他不但是个专制君主，还是宇宙之王。", "t": [100, 3176]}]}, {"id": "ch10p29", "audio": true, "sents": [{"fr": "— Bien sûr, lui dit le roi.", "zh": "“所有的星星都听命于您吗？", "t": [100, 3725]}, {"fr": "Elles obéissent aussitôt.", "zh": "“所有的星星都听命于您吗？", "t": [3725, 5838]}, {"fr": "Je ne tolère pas l’indiscipline.", "zh": "” “当然啦，”国王说，“它们令出即行。", "t": [5838, 7513]}]}, {"id": "ch10p30", "audio": true, "sents": [{"fr": "Un tel pouvoir émerveilla le petit prince.", "zh": "” “当然啦，”国王说，“它们令出即行。", "t": [100, 3175]}, {"fr": "S’il l’avait détenu lui-même, il aurait pu assister, non pas à quarante-quatre, mais à soixante-douze, ou même à cent, ou même à deux cents couchers de soleil dans la même journée, sans avoir jamais à tirer sa chaise !", "zh": "” 小王子既赞叹又羡慕国王的权威。", "t": [3175, 15388]}, {"fr": "Et comme il se sentait un peu triste à cause du souvenir de sa petite planète abandonnée, il s’enhardit à solliciter une grâce du roi :", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [15388, 22575]}]}, {"id": "ch10p31", "audio": true, "sents": [{"fr": "— Je voudrais voir un coucher de soleil…", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [100, 3838]}, {"fr": "Faites-moi plaisir…", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [3838, 5825]}, {"fr": "Ordonnez au soleil de se coucher…", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [5825, 7600]}]}, {"id": "ch10p32", "audio": true, "sents": [{"fr": "— Si j’ordonnais à un général de voler d’une fleur à l’autre à la façon d’un papillon, ou d’écrire une tragédie, ou de se changer en oiseau de mer, et si le général n’exécutait pas l’ordre reçu, qui, de lui ou de moi, serait dans son tort ?", "zh": "他壮壮胆，请求国王开恩： “我想观看夕阳西下……求您开恩……命令太阳下去吧……” “如果我命令将军像蝴蝶那样，在花间飞来飞去，或命令他写一部悲剧，或变成海鸟，如果将军接到命令后不愿执行，你说是他的错还是我的错？", "t": [100, 14350]}]}, {"id": "ch10p33", "audio": true, "sents": [{"fr": "— Ce serait vous, dit fermement le petit prince.", "zh": "”小王子不假思索便脱口而出。", "t": [100, 3650]}]}, {"id": "ch10p34", "audio": true, "sents": [{"fr": "— Exact.", "zh": "“你说得对，不能强人所难。", "t": [100, 2738]}, {"fr": "Il faut exiger de chacun ce que chacun peut donner, reprit le roi.", "zh": "”国王说。", "t": [2738, 7212]}, {"fr": "L’autorité repose d’abord sur la raison.", "zh": "“权威首先必须建筑在理性上。", "t": [7212, 10338]}, {"fr": "Si tu ordonnes à ton peuple d’aller se jeter à la mer, il fera la révolution.", "zh": "如果你命令你的人民跳海，他们定会造反。", "t": [10338, 15362]}, {"fr": "J’ai le droit d’exiger l’obéissance parce que mes ordres sont raisonnables.", "zh": "” “那么，我要求的日落呢？", "t": [15362, 18988]}]}, {"id": "ch10p35", "audio": true, "sents": [{"fr": "— Alors mon coucher de soleil ?", "zh": "”小王子问道。", "t": [100, 4188]}, {"fr": "rappela le petit prince qui jamais n’oubliait une question une fois qu’il l’avait posée.", "zh": "一旦提出一个问题，他是不会中途而废的。", "t": [4188, 8012]}]}, {"id": "ch10p36", "audio": true, "sents": [{"fr": "— Ton coucher de soleil, tu l’auras.", "zh": "“你会看到你要求的日落的，我会发布命令。", "t": [100, 4025]}, {"fr": "Je l’exigerai.", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [4025, 5888]}, {"fr": "Mais j’attendrai, dans ma science du gouvernement, que les conditions soient favorables.", "zh": "要科学管理一个国家，下命令应等时机成熟。", "t": [5888, 10413]}]}, {"id": "ch10p37", "audio": true, "sents": [{"fr": "— Quand ça sera-t-il ?", "zh": "”小王子问。", "t": [100, 3638]}, {"fr": "s’informa le petit prince.", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [3638, 5163]}]}, {"id": "ch10p38", "audio": true, "sents": [{"fr": "— Hem !", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [100, 2975]}, {"fr": "Hem !", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [2975, 4875]}, {"fr": "lui répondit le roi, qui consulta d’abord un gros calendrier, hem !", "zh": "“嗯，嗯，首先我要查看大皇历。", "t": [4875, 10262]}, {"fr": "hem !", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [10262, 12162]}, {"fr": "ce sera, vers…", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [12162, 13588]}, {"fr": "vers…", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [13588, 14138]}, {"fr": "ce sera ce soir vers sept heures quarante !", "zh": "嗯，嗯，要等到……今晚……十时四十分左右……左右……你会看到他们怎样执行我的命令。", "t": [14138, 17488]}, {"fr": "Et tu verras comme je suis bien obéi.", "zh": "” 小王子打了个哈欠。", "t": [17488, 19350]}]}, {"id": "ch10p39", "audio": true, "sents": [{"fr": "Le petit prince bâilla.", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [100, 2175]}, {"fr": "Il regrettait son coucher de soleil manqué.", "zh": "他感到惋惜，因为他的要求泡汤了。", "t": [2175, 5225]}, {"fr": "Et puis il s’ennuyait déjà un peu :", "zh": "再说，他已经有点儿腻烦了。", "t": [5225, 7550]}]}, {"id": "ch10p40", "audio": true, "sents": [{"fr": "— Je n’ai plus rien à faire ici, dit-il au roi.", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [100, 4488]}, {"fr": "Je vais repartir !", "zh": "“我在这儿没事可干了，”他对国王说，“我要告辞了！", "t": [4488, 6138]}]}, {"id": "ch10p41", "audio": true, "sents": [{"fr": "— Ne pars pas, répondit le roi qui était si fier d’avoir un sujet.", "zh": "” “你别走。", "t": [100, 5350]}, {"fr": "Ne pars pas, je te fais ministre !", "zh": "”国王说，拥有一个百姓，对他来说是一件值得自豪的事。", "t": [5350, 7850]}]}, {"id": "ch10p42", "audio": true, "sents": [{"fr": "— Ministre de quoi ?", "zh": "“别走，我任命你为部长！", "t": [100, 2925]}]}, {"id": "ch10p43", "audio": true, "sents": [{"fr": "— De…", "zh": "“别走，我任命你为部长！", "t": [100, 1588]}, {"fr": "de la justice !", "zh": "“别走，我任命你为部长！", "t": [1588, 3025]}]}, {"id": "ch10p44", "audio": true, "sents": [{"fr": "— Mais il n’y a personne à juger !", "zh": "” “哪个部的部长？", "t": [100, 3412]}]}, {"id": "ch10p45", "audio": true, "sents": [{"fr": "— On ne sait pas, lui dit le roi.", "zh": "” “……司法部。", "t": [100, 3662]}, {"fr": "Je n’ai pas fait encore le tour de mon royaume.", "zh": "” “可这儿没人可审呀！", "t": [3662, 6738]}, {"fr": "Je suis très vieux, je n’ai pas de place pour un carrosse, et ça me fatigue de marcher.", "zh": "” “这可就难说了，”国王说，“我还没视察过我的王国呢。", "t": [6738, 11238]}]}, {"id": "ch10p46", "audio": true, "sents": [{"fr": "— Oh !", "zh": "我上了年纪，这儿又没有停马车的地方，走路又太累了。", "t": [100, 3038]}, {"fr": "Mais j’ai déjà vu, dit le petit prince qui se pencha pour jeter encore un coup d’œil sur l’autre côté de la planète.", "zh": "” “啊，我已经看过了。", "t": [3038, 9675]}, {"fr": "Il n’y a personne là-bas non plus…", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [9675, 11212]}]}, {"id": "ch10p47", "audio": true, "sents": [{"fr": "— Tu te jugeras donc toi-même, lui répondit le roi.", "zh": "”小王子俯身朝星球的另一端又瞟了一眼。", "t": [100, 4962]}, {"fr": "C’est le plus difficile.", "zh": "“那儿也没一个人……” “你就审你自己吧，”国王说，“这是最难办的事。", "t": [4962, 7112]}, {"fr": "Il est bien plus difficile de se juger soi-même que de juger autrui.", "zh": "审自己比审别人难得多。", "t": [7112, 11400]}, {"fr": "Si tu réussis à bien te juger, c’est que tu es un véritable sage.", "zh": "你若能审自己，你就是真正的聪明人。", "t": [11400, 15050]}]}, {"id": "ch10p48", "audio": true, "sents": [{"fr": "— Moi, dit le petit prince, je puis me juger moi-même n’importe où.", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [100, 5512]}, {"fr": "Je n’ai pas besoin d’habiter ici.", "zh": "” “我嘛，”小王子说，“无论在什么地方我都能审自己，无需住在这儿。", "t": [5512, 7337]}]}, {"id": "ch10p49", "audio": true, "sents": [{"fr": "— Hem !", "zh": "” “嗯，嗯，我知道。", "t": [100, 2975]}, {"fr": "Hem !", "zh": "” “嗯，嗯，我知道。", "t": [2975, 4250]}, {"fr": "dit le roi, je crois bien que sur ma planète il y a quelque part un vieux rat.", "zh": "”国王说。", "t": [4250, 8700]}, {"fr": "Je l’entends la nuit.", "zh": "“在我的星球的某一处，有一只老耗子。", "t": [8700, 10712]}, {"fr": "Tu pourras juger ce vieux rat.", "zh": "我在夜里听到的。", "t": [10712, 13100]}, {"fr": "Tu le condamneras à mort de temps en temps.", "zh": "你可以审这只老耗子。", "t": [13100, 16038]}, {"fr": "Ainsi sa vie dépendra de ta justice.", "zh": "隔一段时间判它一次死刑。", "t": [16038, 18912]}, {"fr": "Mais tu le gracieras chaque fois pour l’économiser.", "zh": "这样，它的死活就由你的裁判决定了。", "t": [18912, 22250]}, {"fr": "Il n’y en a qu’un.", "zh": "但你每一次都要免除它的死罪，你要悠着点，因为就只有这一个犯人了。", "t": [22250, 23124]}]}, {"id": "ch10p50", "audio": true, "sents": [{"fr": "— Moi, répondit le petit prince, je n’aime pas condamner à mort, et je crois bien que je m’en vais.", "zh": "但你每一次都要免除它的死罪，你要悠着点，因为就只有这一个犯人了。", "t": [100, 6275]}]}, {"id": "ch10p51", "audio": true, "sents": [{"fr": "— Non, dit le roi.", "zh": "” “我可不喜欢判人死刑。", "t": [100, 2325]}]}, {"id": "ch10p52", "audio": true, "sents": [{"fr": "Mais le petit prince, ayant achevé ses préparatifs, ne voulut point peiner le vieux monarque :", "zh": "” “别走。", "t": [100, 5688]}]}, {"id": "ch10p53", "audio": true, "sents": [{"fr": "— Si Votre Majesté désirait être obéie ponctuellement, elle pourrait me donner un ordre raisonnable.", "zh": "小王子已经做好走的准备，但他不愿伤老国王的心，他对老国王说：“如果陛下您希望令出即行，您可以向我下达合理的命令。", "t": [100, 6962]}, {"fr": "Elle pourrait m’ordonner, par exemple, de partir avant une minute.", "zh": "例如说，可以命令我在一分钟之内离开。", "t": [6962, 11588]}, {"fr": "Il me semble que les conditions sont favorables…", "zh": "例如说，可以命令我在一分钟之内离开。", "t": [11588, 13876]}]}, {"id": "ch10p54", "audio": true, "sents": [{"fr": "Le roi n’ayant rien répondu, le petit prince hésita d’abord, puis, avec un soupir, prit le départ.", "zh": "我认为时机已经成熟……” 国王一言不发。", "t": [100, 6338]}]}, {"id": "ch10p55", "audio": true, "sents": [{"fr": "— Je te fais mon ambassadeur, se hâta alors de crier le roi.", "zh": "国王急忙大叫：“我封你为大使。", "t": [100, 4513]}]}, {"id": "ch10p56", "audio": true, "sents": [{"fr": "Il avait un grand air d’autorité.", "zh": "” 他摆出威风凛凛的神气。", "t": [100, 1850]}]}, {"id": "ch10p57", "audio": true, "sents": [{"fr": "Les grandes personnes sont bien étranges, se dit le petit prince, en lui-même, durant son voyage.", "zh": "小王子一面赶路，一面自言自语： “大人们真怪。", "t": [100, 5663]}]}, {"id": "ch10p58", "audio": true, "sents": []}]}, {"id": "ch11", "title_fr": "Chapitre XI", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"fr": "La seconde planète était habitée par un vaniteux :", "zh": "第二颗星球住着一个爱慕虚荣的人。", "t": [100, 3287]}]}, {"id": "ch11p01", "audio": true, "sents": [{"fr": "— Ah !", "zh": "“啊！", "t": [100, 3038]}, {"fr": "Ah !", "zh": "“啊！", "t": [3038, 4950]}, {"fr": "Voilà la visite d’un admirateur !", "zh": "啊！", "t": [4950, 7938]}, {"fr": "s’écria de loin le vaniteux dès qu’il aperçut le petit prince.", "zh": "”看见小王子，这位爱慕虚荣的人打老远就高声喊。", "t": [7938, 10974]}]}, {"id": "ch11p02", "audio": true, "sents": [{"fr": "Car, pour les vaniteux, les autres hommes sont des admirateurs.", "zh": "爱慕虚荣的人以为别人都崇拜他。", "t": [100, 3888]}]}, {"id": "ch11p03", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "“您好。", "t": [100, 3938]}, {"fr": "Vous avez un drôle de chapeau.", "zh": "”小王子说。", "t": [3938, 5337]}]}, {"id": "ch11p04", "audio": true, "sents": [{"fr": "— C’est pour saluer, lui répondit le vaniteux.", "zh": "“您的帽子真怪。", "t": [100, 4400]}, {"fr": "C’est pour saluer quand on m’acclame.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [4400, 6962]}, {"fr": "Malheureusement il ne passe jamais personne par ici.", "zh": "” “这顶帽子是用来敬礼的，”爱慕虚荣的人说，“有人向我欢呼的时候，我就用它敬礼。", "t": [6962, 9588]}]}, {"id": "ch11p05", "audio": true, "sents": [{"fr": "— Ah oui ?", "zh": "可惜这儿没一个人来。", "t": [100, 2562]}, {"fr": "dit le petit prince qui ne comprit pas.", "zh": "可惜这儿没一个人来。", "t": [2562, 4187]}]}, {"id": "ch11p06", "audio": true, "sents": [{"fr": "— Frappe tes mains l’une contre l’autre, conseilla donc le vaniteux.", "zh": "”小王子听不懂他的话。", "t": [100, 4400]}]}, {"id": "ch11p07", "audio": true, "sents": [{"fr": "Le petit prince frappa ses mains l’une contre l’autre.", "zh": "”爱慕虚荣的人建议。", "t": [100, 3412]}, {"fr": "Le vaniteux salua modestement en soulevant son chapeau.", "zh": "小王子依言鼓掌。", "t": [3412, 6338]}]}, {"id": "ch11p08", "audio": true, "sents": [{"fr": "— Ça c’est plus amusant que la visite au roi, se dit en lui-même le petit prince.", "zh": "“这比拜访国王有趣多了。", "t": [100, 5988]}, {"fr": "Et il recommença de frapper ses mains l’une contre l’autre.", "zh": "他又一次拍巴掌。", "t": [5988, 9488]}, {"fr": "Le vaniteux recommença de saluer en soulevant son chapeau.", "zh": "爱慕虚荣的人又举帽子行礼。", "t": [9488, 12400]}]}, {"id": "ch11p09", "audio": true, "sents": [{"fr": "Après cinq minutes d’exercice le petit prince se fatigua de la monotonie du jeu :", "zh": "反复操练了五分钟之后，小王子厌倦了这个单调的游戏。", "t": [100, 5037]}]}, {"id": "ch11p10", "audio": true, "sents": [{"fr": "— Et, pour que le chapeau tombe, demanda-t-il, que faut-il faire ?", "zh": "”小王子问。", "t": [100, 5450]}]}, {"id": "ch11p11", "audio": true, "sents": [{"fr": "Mais le vaniteux ne l’entendit pas.", "zh": "爱慕虚荣的人听不见这句话。", "t": [100, 2562]}, {"fr": "Les vaniteux n’entendent jamais que les louanges.", "zh": "爱慕虚荣的人只听得见赞扬声。", "t": [2562, 4637]}]}, {"id": "ch11p12", "audio": true, "sents": [{"fr": "— Est-ce que tu m’admires vraiment beaucoup ?", "zh": "“你对我真的崇拜到了五体投地？", "t": [100, 3850]}, {"fr": "demanda-t-il au petit prince.", "zh": "”他问小王子。", "t": [3850, 5325]}]}, {"id": "ch11p13", "audio": true, "sents": [{"fr": "— Qu’est-ce que signifie admirer ?", "zh": "“什么叫做‘崇拜’？", "t": [100, 3376]}]}, {"id": "ch11p14", "audio": true, "sents": [{"fr": "— Admirer signifie reconnaître que je suis l’homme le plus beau, le mieux habillé, le plus riche et le plus intelligent de la planète.", "zh": "” “‘崇拜’就是承认我是星球上最帅、衣着最讲究、最富有、最聪明的人。", "t": [100, 7738]}]}, {"id": "ch11p15", "audio": true, "sents": [{"fr": "— Mais tu es seul sur ta planète !", "zh": "” “在你的星球上只有你一个人啊！", "t": [100, 3262]}]}, {"id": "ch11p16", "audio": true, "sents": [{"fr": "— Fais-moi ce plaisir.", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [100, 3175]}, {"fr": "Admire-moi quand même !", "zh": "” “你就让我享受被人崇拜的快乐吧，仍然崇拜我吧！", "t": [3175, 4900]}]}, {"id": "ch11p17", "audio": true, "sents": [{"fr": "— Je t’admire, dit le petit prince, en haussant un peu les épaules, mais en quoi cela peut-il bien t’intéresser ?", "zh": "” “我崇拜你，”小王子耸耸肩，“这有什么值得你快乐的呢？", "t": [100, 7638]}]}, {"id": "ch11p18", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut.", "zh": "” 小王子走了。", "t": [100, 1550]}]}, {"id": "ch11p19", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément bien bizarres, se dit-il simplement en lui-même durant son voyage.", "zh": "“大人们确实怪得出奇。", "t": [100, 5487]}]}, {"id": "ch11p20", "audio": true, "sents": []}]}, {"id": "ch12", "title_fr": "Chapitre XII", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": []}, {"id": "ch12p01", "audio": true, "sents": [{"fr": "La planète suivante était habitée par un buveur.", "zh": "下一颗星球住着一个酒鬼。", "t": [100, 3650]}, {"fr": "Cette visite fut très courte, mais elle plongea le petit prince dans une grande mélancolie :", "zh": "“你在干什么？", "t": [3650, 8862]}]}, {"id": "ch12p02", "audio": true, "sents": [{"fr": "— Que fais-tu là ?", "zh": "“你在干什么？", "t": [100, 2988]}, {"fr": "dit-il au buveur, qu’il trouva installé en silence devant une collection de bouteilles vides et une collection de bouteilles pleines.", "zh": "”小王子看见酒鬼在喝闷酒，面前摆着一大堆空瓶子和装满了酒的瓶子，就这样问他。", "t": [2988, 8963]}]}, {"id": "ch12p03", "audio": true, "sents": [{"fr": "— Je bois, répondit le buveur, d’un air lugubre.", "zh": "“你为什么喝酒呢？", "t": [100, 4237]}]}, {"id": "ch12p04", "audio": true, "sents": [{"fr": "— Pourquoi bois-tu ?", "zh": "”小王子问他。", "t": [100, 3588]}, {"fr": "lui demanda le petit prince.", "zh": "“为了忘记呗。", "t": [3588, 5150]}]}, {"id": "ch12p05", "audio": true, "sents": [{"fr": "— Pour oublier, répondit le buveur.", "zh": "”酒鬼答。", "t": [100, 3338]}]}, {"id": "ch12p06", "audio": true, "sents": [{"fr": "— Pour oublier quoi ?", "zh": "“为了忘记什么？", "t": [100, 3762]}, {"fr": "s’enquit le petit prince qui déjà le plaignait.", "zh": "”小王子有点可怜他，又问。", "t": [3762, 5900]}]}, {"id": "ch12p07", "audio": true, "sents": [{"fr": "— Pour oublier que j’ai honte, avoua le buveur en baissant la tête.", "zh": "”酒鬼低着头，老老实实地承认。", "t": [100, 4625]}]}, {"id": "ch12p08", "audio": true, "sents": [{"fr": "— Honte de quoi ?", "zh": "“为了什么事羞愧呢？", "t": [100, 3638]}, {"fr": "s’informa le petit prince qui désirait le secourir.", "zh": "”小王子打算帮助他，又问。", "t": [3638, 6387]}]}, {"id": "ch12p09", "audio": true, "sents": [{"fr": "— Honte de boire !", "zh": "“我为喝酒羞愧！", "t": [100, 3488]}, {"fr": "acheva le buveur qui s’enferma définitivement dans le silence.", "zh": "”酒鬼讲完后，闭了嘴巴不再讲话。", "t": [3488, 6750]}]}, {"id": "ch12p10", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut, perplexe.", "zh": "小王子大惑不解。", "t": [100, 2450]}]}, {"id": "ch12p11", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément très très bizarres, se disait-il en lui-même durant le voyage.", "zh": "“大人们真是没法理解。", "t": [100, 5175]}]}, {"id": "ch12p12", "audio": true, "sents": []}]}, {"id": "ch13", "title_fr": "Chapitre XIII", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"fr": "La quatrième planète était celle du businessman.", "zh": "第四颗星球是商人的星球。", "t": [100, 3575]}, {"fr": "Cet homme était si occupé qu’il ne leva même pas la tête à l’arrivée du petit prince.", "zh": "“您好！", "t": [3575, 7562]}]}, {"id": "ch13p01", "audio": true, "sents": [{"fr": "— Bonjour, lui dit celui-ci.", "zh": "“您的香烟已经熄灭了。", "t": [100, 3912]}, {"fr": "Votre cigarette est éteinte.", "zh": "“您的香烟已经熄灭了。", "t": [3912, 5537]}]}, {"id": "ch13p02", "audio": true, "sents": [{"fr": "— Trois et deux font cinq.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [100, 3362]}, {"fr": "Cinq et sept douze.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [3362, 5425]}, {"fr": "Douze et trois quinze.", "zh": "” “三加二等于五，五加七等于十二，十二加三等于十五，你好。", "t": [5425, 7475]}, {"fr": "Bonjour.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [7475, 9050]}, {"fr": "Quinze et sept vingt-deux.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [9050, 11050]}, {"fr": "Vingt-deux et six vingt-huit.", "zh": "十五加七等于二十二，二十二加六等于二十八，我没时间点烟。", "t": [11050, 13538]}, {"fr": "Pas le temps de la rallumer.", "zh": "二十六加五等于三十一。", "t": [13538, 15688]}, {"fr": "Vingt-six et cinq trente et un.", "zh": "嗬！", "t": [15688, 18200]}, {"fr": "Ouf !", "zh": "嗬！", "t": [18200, 20125]}, {"fr": "Ça fait donc cinq cent un millions six cent vingt-deux mille sept cent trente et un.", "zh": "” “五亿个什么？", "t": [20125, 23513]}]}, {"id": "ch13p03", "audio": true, "sents": [{"fr": "— Cinq cents millions de quoi ?", "zh": "你还在这儿？", "t": [100, 3162]}]}, {"id": "ch13p04", "audio": true, "sents": [{"fr": "— Hein ?", "zh": "你还在这儿？", "t": [100, 3038]}, {"fr": "Tu es toujours là ?", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [3038, 5512]}, {"fr": "Cinq cent un millions de…", "zh": "五亿零一百……我也闹糊涂了……我的活太忙了！", "t": [5512, 6875]}, {"fr": "je ne sais plus…", "zh": "我是个正经人，不爱讲废话！", "t": [6875, 8400]}, {"fr": "J’ai tellement de travail !", "zh": "我是个正经人，不爱讲废话！", "t": [8400, 11138]}, {"fr": "Je suis sérieux, moi, je ne m’amuse pas à des balivernes !", "zh": "二加五等于七……” “五亿零一百万个什么？", "t": [11138, 15862]}, {"fr": "Deux et cinq sept…", "zh": "”小王子还在追问，他一旦提出问题，绝不中途而废。", "t": [15862, 17062]}]}, {"id": "ch13p05", "audio": true, "sents": [{"fr": "— Cinq cent un millions de quoi, répéta le petit prince qui jamais de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [100, 8188]}]}, {"id": "ch13p06", "audio": true, "sents": [{"fr": "Le businessman leva la tête :", "zh": "商人抬起头： “我住在这个星球已经五十四年了，只受过三次干扰。", "t": [100, 2362]}]}, {"id": "ch13p07", "audio": true, "sents": [{"fr": "— Depuis cinquante-quatre ans que j’habite cette planète-ci, je n’ai été dérangé que trois fois.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [100, 6388]}, {"fr": "La première fois ç’a été, il y a vingt-deux ans, par un hanneton qui était tombé Dieu sait d’où.", "zh": "第一次干扰发生在二十二年前，鬼知道从哪儿掉下一个愣头青，发出的声音大得吓人，弄得我的加法出了四个错；第二次干扰发生在十一年前，我患了关节炎，我缺乏体育锻炼，我没时间闲逛，我是个正经人；第三次……就是这一次！", "t": [6388, 11950]}, {"fr": "Il répandait un bruit épouvantable, et j’ai fait quatre erreurs dans une addition.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [11950, 16900]}, {"fr": "La seconde fois ç’a été, il y a onze ans, par une crise de rhumatisme.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [16900, 21788]}, {"fr": "Je manque d’exercice.", "zh": "我刚好算到五亿零一百万个……” “五亿零一百万个什么？", "t": [21788, 23988]}, {"fr": "Je n’ai pas le temps de flâner.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [23988, 26238]}, {"fr": "Je suis sérieux, moi.", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [26238, 28688]}, {"fr": "La troisième fois…", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [28688, 29912]}, {"fr": "la voici !", "zh": "” 商人知道他休想安宁了： “五亿零一百万个小东西，有时在天上看得到的小东西。", "t": [29912, 32125]}, {"fr": "Je disais donc cinq cent un millions…", "zh": "” “苍蝇吗？", "t": [32125, 33862]}]}, {"id": "ch13p08", "audio": true, "sents": [{"fr": "— Millions de quoi ?", "zh": "” “苍蝇吗？", "t": [100, 2788]}]}, {"id": "ch13p09", "audio": true, "sents": [{"fr": "Le businessman comprit qu’il n’était point d’espoir de paix :", "zh": "” “蜜蜂吗？", "t": [100, 3600]}]}, {"id": "ch13p10", "audio": true, "sents": [{"fr": "— Millions de ces petites choses que l’on voit quelquefois dans le ciel.", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [100, 4126]}]}, {"id": "ch13p11", "audio": true, "sents": [{"fr": "— Des mouches ?", "zh": "” “不是，是金色的小东西，能教闲得发慌的人发痴做梦的小东西，可我是正经人，我没时间遐想做梦。", "t": [100, 2400]}]}, {"id": "ch13p12", "audio": true, "sents": [{"fr": "— Mais non, des petites choses qui brillent.", "zh": "” “啊！", "t": [100, 3162]}]}, {"id": "ch13p13", "audio": true, "sents": [{"fr": "— Des abeilles ?", "zh": "” “啊！", "t": [100, 2537]}]}, {"id": "ch13p14", "audio": true, "sents": [{"fr": "— Mais non.", "zh": "是满天的繁星吗？", "t": [100, 2462]}, {"fr": "Des petites choses dorées qui font rêvasser les fainéants.", "zh": "” “就是这个。", "t": [2462, 5812]}, {"fr": "Mais je suis sérieux, moi !", "zh": "” “你要五亿多颗星星做什么？", "t": [5812, 8862]}, {"fr": "Je n’ai pas le temps de rêvasser.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [8862, 10362]}]}, {"id": "ch13p15", "audio": true, "sents": [{"fr": "— Ah !", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [100, 3038]}, {"fr": "des étoiles ?", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [3038, 4426]}]}, {"id": "ch13p16", "audio": true, "sents": [{"fr": "— C’est bien ça.", "zh": "” “是五亿零一百六十二万二千七百三十一颗。", "t": [100, 2800]}, {"fr": "Des étoiles.", "zh": "我是个一丝不苟的人，我务求精确。", "t": [2800, 3663]}]}, {"id": "ch13p17", "audio": true, "sents": [{"fr": "— Et que fais-tu de cinq cents millions d’étoiles ?", "zh": "我是个一丝不苟的人，我务求精确。", "t": [100, 3650]}]}, {"id": "ch13p18", "audio": true, "sents": [{"fr": "— Cinq cent un millions six cent vingt-deux mille sept cent trente et un.", "zh": "” “我要它们干什么？", "t": [100, 4862]}, {"fr": "Je suis sérieux, moi, je suis précis.", "zh": "我拥有它们。", "t": [4862, 7450]}]}, {"id": "ch13p19", "audio": true, "sents": [{"fr": "— Et que fais-tu de ces étoiles ?", "zh": "” “你拥有星星？", "t": [100, 3150]}]}, {"id": "ch13p20", "audio": true, "sents": [{"fr": "— Ce que j’en fais ?", "zh": "” “是呀。", "t": [100, 2650]}]}, {"id": "ch13p21", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” “是呀。", "t": [100, 1525]}]}, {"id": "ch13p22", "audio": true, "sents": [{"fr": "— Rien.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [100, 2512]}, {"fr": "Je les possède.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [2512, 3538]}]}, {"id": "ch13p23", "audio": true, "sents": [{"fr": "— Tu possèdes les étoiles ?", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [100, 3013]}]}, {"id": "ch13p24", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” “我见过一个国王，他……” “国王不是‘拥有’，他是‘统治’。", "t": [100, 1525]}]}, {"id": "ch13p25", "audio": true, "sents": [{"fr": "— Mais j’ai déjà vu un roi qui…", "zh": "大不相同。", "t": [100, 2676]}]}, {"id": "ch13p26", "audio": true, "sents": [{"fr": "— Les rois ne possèdent pas.", "zh": "” “你拥有星星又怎么样呢？", "t": [100, 3188]}, {"fr": "Ils \"règnent\" sur.", "zh": "” “你拥有星星又怎么样呢？", "t": [3188, 5238]}, {"fr": "C’est très différent.", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [5238, 6200]}]}, {"id": "ch13p27", "audio": true, "sents": [{"fr": "— Et à quoi cela te sert-il de posséder les étoiles ?", "zh": "” “拥有了星星，我就成了大富翁呗。", "t": [100, 4275]}]}, {"id": "ch13p28", "audio": true, "sents": [{"fr": "— Ça me sert à être riche.", "zh": "” “成了富翁有什么好处？", "t": [100, 2475]}]}, {"id": "ch13p29", "audio": true, "sents": [{"fr": "— Et à quoi cela te sert-il d’être riche ?", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [100, 3737]}]}, {"id": "ch13p30", "audio": true, "sents": [{"fr": "— A acheter d’autres étoiles, si quelqu’un en trouve.", "zh": "” “如果又有人发现了新的星星，我就把它们买下来呀。", "t": [100, 3976]}]}, {"id": "ch13p31", "audio": true, "sents": [{"fr": "Celui-là, se dit en lui-même le petit prince, il raisonne un peu comme mon ivrogne.", "zh": "” 小王子心想：“这个人的推理方法有点像我见过的那个酒鬼。", "t": [100, 4675]}]}, {"id": "ch13p32", "audio": true, "sents": [{"fr": "Cependant il posa encore des questions :", "zh": "” 他仍然提出问题： “怎样才能拥有星星？", "t": [100, 2900]}]}, {"id": "ch13p33", "audio": true, "sents": [{"fr": "— Comment peut-on posséder les étoiles ?", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [100, 3513]}]}, {"id": "ch13p34", "audio": true, "sents": [{"fr": "— A qui sont-elles ?", "zh": "” 商人烦了，没好气地反问： “你说，这满天的星星属于谁？", "t": [100, 3488]}, {"fr": "riposta, grincheux, le businessman.", "zh": "” “我不知道。", "t": [3488, 6188]}]}, {"id": "ch13p35", "audio": true, "sents": [{"fr": "— Je ne sais pas.", "zh": "它们不属于任何人。", "t": [100, 2725]}, {"fr": "A personne.", "zh": "它们不属于任何人。", "t": [2725, 3500]}]}, {"id": "ch13p36", "audio": true, "sents": [{"fr": "— Alors elles sont à moi, car j’y ai pensé le premier.", "zh": "” “那么它们属于我。", "t": [100, 3937]}]}, {"id": "ch13p37", "audio": true, "sents": [{"fr": "— Ça suffit ?", "zh": "因为我是第一个想到要拥有它们的人。", "t": [100, 2613]}]}, {"id": "ch13p38", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "因为我是第一个想到要拥有它们的人。", "t": [100, 2750]}, {"fr": "Quand tu trouves un diamant qui n’est à personne, il est à toi.", "zh": "” “光是想就行了吗？", "t": [2750, 6675]}, {"fr": "Quand tu trouves une île qui n’est à personne, elle est à toi.", "zh": "你发现一颗没有主人的钻石，这颗钻石就归你了。", "t": [6675, 10350]}, {"fr": "Quand tu as une idée le premier, tu la fais breveter : elle est à toi.", "zh": "你发现一个不属于任何人的岛，这岛就是你的了。", "t": [10350, 15512]}, {"fr": "Et moi je possède les étoiles, puisque jamais personne avant moi n’a songé à les posséder.", "zh": "你头一个想出一个主意，你就可以申请专利，这个主意就是你的了。", "t": [15512, 20138]}]}, {"id": "ch13p39", "audio": true, "sents": [{"fr": "— Ça c’est vrai, dit le petit prince.", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [100, 4000]}, {"fr": "Et qu’en fais-tu ?", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [4000, 5537]}]}, {"id": "ch13p40", "audio": true, "sents": [{"fr": "— Je les gère.", "zh": "而我呢，我拥有星星，因为在我之前没有一个人想过要拥有星星。", "t": [100, 2812]}, {"fr": "Je les compte et je les recompte, dit le businessman.", "zh": "” “这倒是真的。", "t": [2812, 6575]}, {"fr": "C’est difficile.", "zh": "“你要星星做什么用？", "t": [6575, 8450]}, {"fr": "Mais je suis un homme sérieux !", "zh": "” “我管理它们。", "t": [8450, 10475]}]}, {"id": "ch13p41", "audio": true, "sents": [{"fr": "Le petit prince n’était pas satisfait encore.", "zh": "我数它们，一次又一次地数它们。", "t": [100, 2413]}]}, {"id": "ch13p42", "audio": true, "sents": [{"fr": "— Moi, si je possède un foulard, je puis le mettre autour de mon cou et l’emporter.", "zh": "“这是件困难的事，但我是个正经人！", "t": [100, 6225]}, {"fr": "Moi, si je possède une fleur, je puis cueillir ma fleur et l’emporter.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [6225, 11038]}, {"fr": "Mais tu ne peux pas cueillir les étoiles !", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [11038, 13374]}]}, {"id": "ch13p43", "audio": true, "sents": [{"fr": "— Non, mais je puis les placer en banque.", "zh": "” 小王子对这个回答还不满意： “我若拥有一条围巾，我可以把它围在脖子上带走；我若拥有一朵花，我可以把它摘下带走；可你摘不下星星呀！", "t": [100, 3162]}]}, {"id": "ch13p44", "audio": true, "sents": [{"fr": "— Qu’est-ce que ça veut dire ?", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [100, 2876]}]}, {"id": "ch13p45", "audio": true, "sents": [{"fr": "— Ça veut dire que j’écris sur un petit papier le nombre de mes étoiles.", "zh": "” “我不能摘星星，但我能把它们存入银行。", "t": [100, 5275]}, {"fr": "Et puis j’enferme à clef ce papier-là dans un tiroir.", "zh": "” “这是怎么回事？", "t": [5275, 7850]}]}, {"id": "ch13p46", "audio": true, "sents": [{"fr": "— Et c’est tout ?", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [100, 2413]}]}, {"id": "ch13p47", "audio": true, "sents": [{"fr": "— Ça suffit !", "zh": "” “我在一张小纸条上写上我的星星的数目，然后把它锁进抽屉里。", "t": [100, 2600]}]}, {"id": "ch13p48", "audio": true, "sents": [{"fr": "C’est amusant, pensa le petit prince.", "zh": "” “就这样？", "t": [100, 3250]}, {"fr": "C’est assez poétique.", "zh": "” “这就行啦！", "t": [3250, 5312]}, {"fr": "Mais ce n’est pas très sérieux.", "zh": "” “这就行啦！", "t": [5312, 6537]}]}, {"id": "ch13p49", "audio": true, "sents": [{"fr": "Le petit prince avait sur les choses sérieuses des idées très différentes des idées des grandes personnes.", "zh": "” 小王子想：“这倒是挺好玩的，还挺有诗意的呢，但算不上是严肃正经的事儿。", "t": [100, 4900]}]}, {"id": "ch13p50", "audio": true, "sents": [{"fr": "— Moi, dit-il encore, je possède une fleur que j’arrose tous les jours.", "zh": "” 对“严肃正经的事儿”，小王子的看法与大人的看法极不相同。", "t": [100, 5712]}, {"fr": "Je possède trois volcans que je ramone toutes les semaines.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [5712, 9338]}, {"fr": "Car je ramone aussi celui qui est éteint.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [9338, 12238]}, {"fr": "On ne sait jamais.", "zh": "小王子说：“我呢，我拥有一朵花，我就天天给它浇水；我拥有三座火山，我就每个星期给它们疏通清理。", "t": [12238, 13900]}, {"fr": "C’est utile à mes volcans, et c’est utile à ma fleur, que je les possède.", "zh": "我也疏通死火山，因为日后的事难说。", "t": [13900, 18925]}, {"fr": "Mais tu n’es pas utile aux étoiles…", "zh": "我能做对火山、对花有益的事，才叫做拥有它们。", "t": [18925, 20650]}]}, {"id": "ch13p51", "audio": true, "sents": [{"fr": "Le businessman ouvrit la bouche mais ne trouva rien à répondre, et le petit prince s’en fut.", "zh": "但你却不给星星做有益的事。", "t": [100, 4888]}]}, {"id": "ch13p52", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément tout à fait extraordinaires, se disait-il simplement en lui-même durant le voyage.", "zh": "“大人们真是怪得没法说。", "t": [100, 6262]}]}, {"id": "ch13p53", "audio": true, "sents": []}]}, {"id": "ch14", "title_fr": "Chapitre XIV", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"fr": "La cinquième planète était très curieuse.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [100, 3075]}, {"fr": "C’était la plus petite de toutes.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [3075, 5612]}, {"fr": "Il y avait là juste assez de place pour loger un réverbère et un allumeur de réverbères.", "zh": "第五颗星球稀奇古怪，它是熠熠繁星中最小的一颗，它仅能容纳一盏路灯和一个点灯人。", "t": [5612, 10875]}, {"fr": "Le petit prince ne parvenait pas à s’expliquer à quoi pouvaient servir, quelque part dans le ciel, sur une planète sans maison, ni population, un réverbère et un allumeur de réverbères.", "zh": "小王子怎么想都想不明白，这颗位于太空中不起眼的星球，既没有房屋，又没有居民，这路灯和点灯人有何用途。", "t": [10875, 21712]}, {"fr": "Cependant il se dit en lui-même :", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [21712, 23938]}]}, {"id": "ch14p01", "audio": true, "sents": [{"fr": "— Peut-être bien que cet homme est absurde.", "zh": "他想：“这个点灯人也许古怪，然而他不会比国王、爱慕虚荣的人、商人、酒鬼更荒谬吧，至少他干的工作还有意义。", "t": [100, 4050]}, {"fr": "Cependant il est moins absurde que le roi, que le vaniteux, que le businessman et que le buveur.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [4050, 9962]}, {"fr": "Au moins son travail a-t-il un sens.", "zh": "他点亮路灯，如同给太空增添一颗星星，或一朵鲜花；他熄灭路灯，就是让花儿和星星休息睡眠。", "t": [9962, 12675]}, {"fr": "Quand il allume son réverbère, c’est comme s’il faisait naître une étoile de plus, ou une fleur.", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [12675, 18525]}, {"fr": "Quand il éteint son réverbère ça endort la fleur ou l’étoile.", "zh": "这活儿充满诗意，既然充满诗意，那就是有益的工作。", "t": [18525, 22775]}, {"fr": "C’est une occupation très jolie.", "zh": "” 他走近星球，毕恭毕敬地向点灯人行礼： “你好。", "t": [22775, 25138]}, {"fr": "C’est véritablement utile puisque c’est joli.", "zh": "” 他走近星球，毕恭毕敬地向点灯人行礼： “你好。", "t": [25138, 27475]}]}, {"id": "ch14p02", "audio": true, "sents": [{"fr": "Lorsqu’il aborda la planète il salua respectueusement l’allumeur :", "zh": "” “这是规定。", "t": [100, 4138]}]}, {"id": "ch14p03", "audio": true, "sents": [{"fr": "— Bonjour.", "zh": "”点灯人答道。", "t": [100, 2712]}, {"fr": "Pourquoi viens-tu d’éteindre ton réverbère ?", "zh": "“早上好。", "t": [2712, 5388]}]}, {"id": "ch14p04", "audio": true, "sents": [{"fr": "— C’est la consigne, répondit l’allumeur.", "zh": "” “熄灯的规定。", "t": [100, 4375]}, {"fr": "Bonjour.", "zh": "晚上好。", "t": [4375, 5087]}]}, {"id": "ch14p05", "audio": true, "sents": [{"fr": "— Qu’est-ce que la consigne ?", "zh": "” 他点上灯。", "t": [100, 2900]}]}, {"id": "ch14p06", "audio": true, "sents": [{"fr": "— C’est d’éteindre mon réverbère.", "zh": "“你怎么又把灯点着了？", "t": [100, 3675]}, {"fr": "Bonsoir.", "zh": "” “这是规定。", "t": [3675, 4500]}]}, {"id": "ch14p07", "audio": true, "sents": [{"fr": "Et il le ralluma.", "zh": "” “这是规定。", "t": [100, 1012]}]}, {"id": "ch14p08", "audio": true, "sents": [{"fr": "— Mais pourquoi viens-tu de le rallumer ?", "zh": "“我不明白。", "t": [100, 3675]}]}, {"id": "ch14p09", "audio": true, "sents": [{"fr": "— C’est la consigne, répondit l’allumeur.", "zh": "”小王子说。", "t": [100, 3512]}]}, {"id": "ch14p10", "audio": true, "sents": [{"fr": "— Je ne comprends pas, dit le petit prince.", "zh": "“用不着明白，”点灯人说，“规定就是规定。", "t": [100, 3424]}]}, {"id": "ch14p11", "audio": true, "sents": [{"fr": "— Il n’y a rien à comprendre, dit l’allumeur.", "zh": "” 他灭掉路灯。", "t": [100, 4375]}, {"fr": "La consigne c’est la consigne.", "zh": "然后他用红方格手帕抹抹额头。", "t": [4375, 6912]}, {"fr": "Bonjour.", "zh": "然后他用红方格手帕抹抹额头。", "t": [6912, 7624]}]}, {"id": "ch14p12", "audio": true, "sents": [{"fr": "Et il éteignit son réverbère.", "zh": "“这活儿可把我累苦了。", "t": [100, 1674]}]}, {"id": "ch14p13", "audio": true, "sents": [{"fr": "Puis il s’épongea le front avec un mouchoir à carreaux rouges.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [100, 2938]}]}, {"id": "ch14p14", "audio": true, "sents": [{"fr": "— Je fais là un métier terrible.", "zh": "从前的规定还合乎情理，早上熄灯，晚上点灯。", "t": [100, 3525]}, {"fr": "C’était raisonnable autrefois.", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [3525, 5962]}, {"fr": "J’éteignais le matin et j’allumais le soir.", "zh": "熄灯之后休息，点灯之后睡觉……” “现在的规定改了？", "t": [5962, 9062]}, {"fr": "J’avais le reste du jour pour me reposer, et le reste de la nuit pour dormir…", "zh": "” “规定倒没有改，”点灯人说，“倒霉就倒霉在这儿！", "t": [9062, 13287]}]}, {"id": "ch14p15", "audio": true, "sents": [{"fr": "— Et, depuis cette époque, la consigne a changé ?", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [100, 4550]}]}, {"id": "ch14p16", "audio": true, "sents": [{"fr": "— La consigne n’a pas changé, dit l’allumeur.", "zh": "行星一年转得比一年快，而规定却没有改变！", "t": [100, 4675]}, {"fr": "C’est bien là le drame !", "zh": "” “这是怎么回事？", "t": [4675, 7000]}, {"fr": "La planète d’année en année a tourné de plus en plus vite, et la consigne n’a pas changé !", "zh": "” “现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [7000, 12188]}]}, {"id": "ch14p17", "audio": true, "sents": [{"fr": "— Alors ?", "zh": "每分钟要点亮、熄灭一次灯火！", "t": [100, 2575]}, {"fr": "dit le petit prince.", "zh": "每分钟要点亮、熄灭一次灯火！", "t": [2575, 3576]}]}, {"id": "ch14p18", "audio": true, "sents": [{"fr": "— Alors maintenant qu’elle fait un tour par minute, je n’ai plus une seconde de repos.", "zh": "” “这怎么可能呢？", "t": [100, 5938]}, {"fr": "J’allume et j’éteins une fois par minute !", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [5938, 8388]}]}, {"id": "ch14p19", "audio": true, "sents": [{"fr": "— Ça c’est drôle !", "zh": "” “怎么不可能，”点灯人说，“我们已经聊了一个月了。", "t": [100, 3362]}, {"fr": "Les jours chez toi durent une minute !", "zh": "” “一个月？", "t": [3362, 5563]}]}, {"id": "ch14p20", "audio": true, "sents": [{"fr": "— Ce n’est pas drôle du tout, dit l’allumeur.", "zh": "” “一个月？", "t": [100, 4388]}, {"fr": "Ça fait déjà un mois que nous parlons ensemble.", "zh": "晚上好。", "t": [4388, 6500]}]}, {"id": "ch14p21", "audio": true, "sents": [{"fr": "— Un mois ?", "zh": "晚上好。", "t": [100, 2350]}]}, {"id": "ch14p22", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” 点灯人又点亮了路灯。", "t": [100, 2400]}, {"fr": "Trente minutes.", "zh": "” 点灯人又点亮了路灯。", "t": [2400, 4262]}, {"fr": "Trente jours !", "zh": "” 点灯人又点亮了路灯。", "t": [4262, 6438]}, {"fr": "Bonsoir.", "zh": "” 点灯人又点亮了路灯。", "t": [6438, 7263]}]}, {"id": "ch14p23", "audio": true, "sents": [{"fr": "Et il ralluma son réverbère.", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [100, 1700]}]}, {"id": "ch14p24", "audio": true, "sents": [{"fr": "Le petit prince le regarda et il aima cet allumeur qui était tellement fidèle à la consigne.", "zh": "小王子看着他，小王子喜欢这个一丝不苟，按章办事的点灯人。", "t": [100, 5662]}, {"fr": "Il se souvint des couchers de soleil que lui-même allait autrefois chercher, en tirant sa chaise.", "zh": "他很愿意帮助他的朋友。", "t": [5662, 11238]}, {"fr": "Il voulut aider son ami :", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [11238, 13325]}]}, {"id": "ch14p25", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [100, 1975]}, {"fr": "je connais un moyen de te reposer quand tu voudras…", "zh": "“你知道吗……我有个办法，你什么时候想休息就可以休息……” “我一直想找个办法呢。", "t": [1975, 4238]}]}, {"id": "ch14p26", "audio": true, "sents": [{"fr": "— Je veux toujours, dit l’allumeur.", "zh": "”点灯人说。", "t": [100, 3113]}]}, {"id": "ch14p27", "audio": true, "sents": [{"fr": "Car on peut être, à la fois, fidèle et paresseux.", "zh": "有个办法既能按章办事又能偷懒就好了。", "t": [100, 3074]}]}, {"id": "ch14p28", "audio": true, "sents": [{"fr": "Le petit prince poursuivit :", "zh": "有个办法既能按章办事又能偷懒就好了。", "t": [100, 2287]}]}, {"id": "ch14p29", "audio": true, "sents": [{"fr": "— Ta planète est tellement petite que tu en fais le tour en trois enjambées.", "zh": "小王子继续说道： “你的星球这么小，走三步就绕了一个圈。", "t": [100, 5262]}, {"fr": "Tu n’as qu’à marcher assez lentement pour rester toujours au soleil.", "zh": "你只要放慢脚步，太阳就老在你的头顶上。", "t": [5262, 9150]}, {"fr": "Quand tu voudras te reposer tu marcheras…", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [9150, 11488]}, {"fr": "et le jour durera aussi longtemps que tu voudras.", "zh": "你想休息的时候，你就往前走……你的白天要多长有多长。", "t": [11488, 13662]}]}, {"id": "ch14p30", "audio": true, "sents": [{"fr": "— Ça ne m’avance pas à grand’chose, dit l’allumeur.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [100, 4600]}, {"fr": "Ce que j’aime dans la vie, c’est dormir.", "zh": "” “这个办法解决不了我多大的问题，”点灯人说，“我平生喜欢的就是睡觉。", "t": [4600, 6776]}]}, {"id": "ch14p31", "audio": true, "sents": [{"fr": "— Ce n’est pas de chance, dit le petit prince.", "zh": "” “那你就太不走运了。", "t": [100, 3475]}]}, {"id": "ch14p32", "audio": true, "sents": [{"fr": "— Ce n’est pas de chance, dit l’allumeur.", "zh": "” “那你就太不走运了。", "t": [100, 4025]}, {"fr": "Bonjour.", "zh": "”小王子说。", "t": [4025, 4737]}]}, {"id": "ch14p33", "audio": true, "sents": [{"fr": "Et il éteignit son réverbère.", "zh": "“我真的不走运。", "t": [100, 1674]}]}, {"id": "ch14p34", "audio": true, "sents": [{"fr": "Celui-là, se dit le petit prince, tandis qu’il poursuivait plus loin son voyage, celui-là serait méprisé par tous les autres, par le roi, par le vaniteux, par le buveur, par le businessman.", "zh": "小王子一面赶路一面想：“这个人会被其他人瞧不起的。", "t": [100, 12112]}, {"fr": "Cependant c’est le seul qui ne me paraisse pas ridicule.", "zh": "会被国王、爱慕虚荣的人、酒鬼、商人瞧不起。", "t": [12112, 15725]}, {"fr": "C’est, peut-être, parce qu’il s’occupe d’autre chose que de soi-même.", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [15725, 19300]}]}, {"id": "ch14p35", "audio": true, "sents": [{"fr": "Il eut un soupir de regret et se dit encore :", "zh": "可是他是惟一的我不觉得可笑的人，也许因为他没有光顾自己吧！", "t": [100, 2950]}]}, {"id": "ch14p36", "audio": true, "sents": [{"fr": "— Celui-là est le seul dont j’eusse pu faire mon ami.", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [100, 4312]}, {"fr": "Mais sa planète est vraiment trop petite.", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [4312, 7125]}, {"fr": "Il n’y a pas de place pour deux…", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [7125, 8475]}]}, {"id": "ch14p37", "audio": true, "sents": [{"fr": "Ce que le petit prince n’osait pas s’avouer, c’est qu’il regrettait cette planète bénie à cause, surtout, des mille quatre cent quarante couchers de soleil par vingt-quatre heures !", "zh": "” 他惋惜地叹口气，又想： “这个人本来是惟一可做我的朋友的人，但他的星球实在太小了，搁不下两个人……” 小王子不敢承认，他对这颗星球颇有好感的原因是，它得天独厚，二十四小时之内就可以观看一千四百四十次日落。", "t": [100, 9063]}]}, {"id": "ch14p38", "audio": true, "sents": []}]}, {"id": "ch15", "title_fr": "Chapitre XV", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"fr": "La sixième planète était une planète dix fois plus vaste.", "zh": "第六颗星球比刚才那颗大十倍。", "t": [100, 4000]}, {"fr": "Elle était habitée par un vieux Monsieur qui écrivait d’énormes livres.", "zh": "星球上住着一位老先生，正在撰写大部头著作。", "t": [4000, 7125]}]}, {"id": "ch15p01", "audio": true, "sents": [{"fr": "— Tiens !", "zh": "看见小王子，他大声嚷： “嗬！", "t": [100, 3200]}, {"fr": "voilà un explorateur !", "zh": "看见小王子，他大声嚷： “嗬！", "t": [3200, 6112]}, {"fr": "s’écria-t-il, quand il aperçut le petit prince.", "zh": "来了一个勘探人员！", "t": [6112, 9075]}]}, {"id": "ch15p02", "audio": true, "sents": [{"fr": "Le petit prince s’assit sur la table et souffla un peu.", "zh": "” 小王子有点气喘，坐在桌子上。", "t": [100, 3600]}, {"fr": "Il avait déjà tant voyagé !", "zh": "“你从哪儿来？", "t": [3600, 5838]}]}, {"id": "ch15p03", "audio": true, "sents": [{"fr": "— D’où viens-tu ?", "zh": "“你从哪儿来？", "t": [100, 3462]}, {"fr": "lui dit le vieux Monsieur.", "zh": "”老先生问他。", "t": [3462, 4562]}]}, {"id": "ch15p04", "audio": true, "sents": [{"fr": "— Quel est ce gros livre ?", "zh": "“这是本什么巨著？", "t": [100, 3188]}, {"fr": "dit le petit prince.", "zh": "”小王子问。", "t": [3188, 5050]}, {"fr": "Que faites-vous ici ?", "zh": "“您在这儿干什么？", "t": [5050, 6738]}]}, {"id": "ch15p05", "audio": true, "sents": [{"fr": "— Je suis géographe, dit le vieux Monsieur.", "zh": "” “我是地理学家。", "t": [100, 3200]}]}, {"id": "ch15p06", "audio": true, "sents": [{"fr": "— Qu’est-ce qu’un géographe ?", "zh": "“什么叫‘地理学家’？", "t": [100, 2875]}]}, {"id": "ch15p07", "audio": true, "sents": [{"fr": "— C’est un savant qui connaît où se trouvent les mers, les fleuves, les villes, les montagnes et les déserts.", "zh": "” “地理学家是学者，知道哪儿有大海、江河、城市、山脉、沙漠。", "t": [100, 6450]}]}, {"id": "ch15p08", "audio": true, "sents": [{"fr": "— Ça c’est bien intéressant, dit le petit prince.", "zh": "” “这倒挺有趣的。", "t": [100, 4612]}, {"fr": "Ça c’est enfin un véritable métier !", "zh": "“总算是真正的职业！", "t": [4612, 8212]}, {"fr": "Et il jeta un coup d’œil autour de lui sur la planète du géographe.", "zh": "”他环顾地理学家的行星。", "t": [8212, 12362]}, {"fr": "Il n’avait jamais vu encore une planète aussi majestueuse.", "zh": "“您的星球真美。", "t": [12362, 15288]}]}, {"id": "ch15p09", "audio": true, "sents": [{"fr": "— Elle est bien belle, votre planète.", "zh": "” “我不可能知道这事。", "t": [100, 4112]}, {"fr": "Est-ce qu’il y a des océans ?", "zh": "”地理学家说。", "t": [4112, 6100]}]}, {"id": "ch15p10", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir, dit le géographe.", "zh": "“啊（小王子有点失望）！", "t": [100, 3512]}]}, {"id": "ch15p11", "audio": true, "sents": [{"fr": "— Ah !", "zh": "有山脉吗？", "t": [100, 3038]}, {"fr": "(Le petit prince était déçu.) Et des montagnes ?", "zh": "” “我不可能知道。", "t": [3038, 6962]}]}, {"id": "ch15p12", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir, dit le géographe.", "zh": "“有城市、河流、沙漠吗？", "t": [100, 3512]}]}, {"id": "ch15p13", "audio": true, "sents": [{"fr": "— Et des villes et des fleuves et des déserts ?", "zh": "” “我也不可能知道。", "t": [100, 3463]}]}, {"id": "ch15p14", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir non plus, dit le géographe.", "zh": "“可你是地理学家啊！", "t": [100, 3838]}]}, {"id": "ch15p15", "audio": true, "sents": [{"fr": "— Mais vous êtes géographe !", "zh": "” “不错，”地理学家说，“但我不是勘探人员。", "t": [100, 2987]}]}, {"id": "ch15p16", "audio": true, "sents": [{"fr": "— C’est exact, dit le géographe, mais je ne suis pas explorateur.", "zh": "” “不错，”地理学家说，“但我不是勘探人员。", "t": [100, 5912]}, {"fr": "Je manque absolument d’explorateurs.", "zh": "我这儿很缺勘探人员。", "t": [5912, 8875]}, {"fr": "Ce n’est pas le géographe qui va faire le compte des villes, des fleuves, des montagnes, des mers, des océans et des déserts.", "zh": "计算城市、江河、山脉、大海、大洋、沙漠的数目，不是地理学家干的事。", "t": [8875, 16612]}, {"fr": "Le géographe est trop important pour flâner.", "zh": "他必须寸步不离办公室。", "t": [16612, 19650]}, {"fr": "Il ne quitte pas son bureau.", "zh": "他必须寸步不离办公室。", "t": [19650, 21875]}, {"fr": "Mais il y reçoit les explorateurs.", "zh": "他在办公室接见勘探人员，询问他们，记下他们的回忆。", "t": [21875, 24612]}, {"fr": "Il les interroge, et il prend en note leurs souvenirs.", "zh": "他在办公室接见勘探人员，询问他们，记下他们的回忆。", "t": [24612, 28388]}, {"fr": "Et si les souvenirs de l’un d’entre eux lui paraissent intéressants, le géographe fait faire une enquête sur la moralité de l’explorateur.", "zh": "” “为什么？", "t": [28388, 34763]}]}, {"id": "ch15p17", "audio": true, "sents": [{"fr": "— Pourquoi ça ?", "zh": "” “一个撒谎的勘探人员会给地理学家的书带来灾难，酒喝得太多的也不行。", "t": [100, 2538]}]}, {"id": "ch15p18", "audio": true, "sents": [{"fr": "— Parce qu’un explorateur qui mentirait entraînerait des catastrophes dans les livres de géographie.", "zh": "” “为什么？", "t": [100, 6775]}, {"fr": "Et aussi un explorateur qui boirait trop.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [6775, 9025]}]}, {"id": "ch15p19", "audio": true, "sents": [{"fr": "— Pourquoi ça ?", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [100, 2850]}, {"fr": "fit le petit prince.", "zh": "” “酒鬼看的东西是重叠的，地理学家就会在有一座山的地方记下两座山。", "t": [2850, 3888]}]}, {"id": "ch15p20", "audio": true, "sents": [{"fr": "— Parce que les ivrognes voient double.", "zh": "” 小王子说：“我认识一个人，他会成为糟糕的勘探员。", "t": [100, 3612]}, {"fr": "Alors le géographe noterait deux montagnes, là où il n’y en a qu’une seule.", "zh": "” 小王子说：“我认识一个人，他会成为糟糕的勘探员。", "t": [3612, 7438]}]}, {"id": "ch15p21", "audio": true, "sents": [{"fr": "— Je connais quelqu’un, dit le petit prince, qui serait mauvais explorateur.", "zh": "勘探人员的品质不错，我就调查他的发现。", "t": [100, 5237]}]}, {"id": "ch15p22", "audio": true, "sents": [{"fr": "— C’est possible.", "zh": "” “你亲自去实地调查吗？", "t": [100, 2850]}, {"fr": "Donc, quand la moralité de l’explorateur paraît bonne, on fait une enquête sur sa découverte.", "zh": "” “不，那太复杂了。", "t": [2850, 8074]}]}, {"id": "ch15p23", "audio": true, "sents": [{"fr": "— On va voir ?", "zh": "我要求勘探人员提供证据。", "t": [100, 2424]}]}, {"id": "ch15p24", "audio": true, "sents": [{"fr": "— Non.", "zh": "我要求勘探人员提供证据。", "t": [100, 2350]}, {"fr": "C’est trop compliqué.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [2350, 4362]}, {"fr": "Mais on exige de l’explorateur qu’il fournisse des preuves.", "zh": "比如说，他发现了一座大山，我就要求他带大石来。", "t": [4362, 8175]}, {"fr": "S’il s’agit par exemple de la découverte d’une grosse montagne, on exige qu’il en rapporte de grosses pierres.", "zh": "你是勘探队员！", "t": [8175, 13787]}]}, {"id": "ch15p25", "audio": true, "sents": [{"fr": "Le géographe soudain s’émut.", "zh": "你给我描写你的星球吧！", "t": [100, 1662]}]}, {"id": "ch15p26", "audio": true, "sents": [{"fr": "— Mais toi, tu viens de loin !", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [100, 4300]}, {"fr": "Tu es explorateur !", "zh": "” 地理学家打开他的登记册，削尖铅笔。", "t": [4300, 6975]}, {"fr": "Tu vas me décrire ta planète !", "zh": "他先用铅笔记下勘探人员的口述。", "t": [6975, 9125]}]}, {"id": "ch15p27", "audio": true, "sents": [{"fr": "Et le géographe, ayant ouvert son registre, tailla son crayon.", "zh": "勘探人员提供证据后，再用钢笔誊写。", "t": [100, 4675]}, {"fr": "On note d’abord au crayon les récits des explorateurs.", "zh": "“请谈吧！", "t": [4675, 8388]}, {"fr": "On attend, pour noter à l’encre, que l’explorateur ait fourni des preuves.", "zh": "“啊！", "t": [8388, 12513]}]}, {"id": "ch15p28", "audio": true, "sents": [{"fr": "— Alors ?", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [100, 3162]}, {"fr": "interrogea le géographe.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [3162, 4512]}]}, {"id": "ch15p29", "audio": true, "sents": [{"fr": "— Oh !", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [100, 3038]}, {"fr": "chez moi, dit le petit prince, ce n’est pas très intéressant, c’est tout petit.", "zh": "我们那儿，可没意思了，”小王子说，“它才一点大，我有三座火山：两座活火山，一座死火山，可谁知道以后会有什么变化呢。", "t": [3038, 8300]}, {"fr": "J’ai trois volcans.", "zh": "” “以后的事谁知道呢。", "t": [8300, 10162]}, {"fr": "Deux volcans en activité, et un volcan éteint.", "zh": "”地理学家说。", "t": [10162, 13762]}, {"fr": "Mais on ne sait jamais.", "zh": "“我还有一朵花。", "t": [13762, 14787]}]}, {"id": "ch15p30", "audio": true, "sents": [{"fr": "— On ne sait jamais, dit le géographe.", "zh": "” “我们不记录花的。", "t": [100, 3162]}]}, {"id": "ch15p31", "audio": true, "sents": [{"fr": "— J’ai aussi une fleur.", "zh": "”地理学家说。", "t": [100, 2426]}]}, {"id": "ch15p32", "audio": true, "sents": [{"fr": "— Nous ne notons pas les fleurs, dit le géographe.", "zh": "“为什么不记录花呢？", "t": [100, 3625]}]}, {"id": "ch15p33", "audio": true, "sents": [{"fr": "— Pourquoi ça !", "zh": "它是最美的东西！", "t": [100, 3388]}, {"fr": "c’est le plus joli !", "zh": "” “因为它‘昙花一现’。", "t": [3388, 5112]}]}, {"id": "ch15p34", "audio": true, "sents": [{"fr": "— Parce que les fleurs sont éphémères.", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 2824]}]}, {"id": "ch15p35", "audio": true, "sents": [{"fr": "— Qu’est ce que signifie : \"éphémère\" ?", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 4550]}]}, {"id": "ch15p36", "audio": true, "sents": [{"fr": "— Les géographies, dit le géographe, sont les livres les plus précieux de tous les livres.", "zh": "” “地理书是一切书籍中最珍贵的书籍，从不会过时。", "t": [100, 6412]}, {"fr": "Elles ne se démodent jamais.", "zh": "山移位，海洋干枯都是极少发生的事。", "t": [6412, 8512]}, {"fr": "Il est très rare qu’une montagne change de place.", "zh": "我们写的是永恒不变的东西。", "t": [8512, 11700]}, {"fr": "Il est très rare qu’un océan se vide de son eau.", "zh": "” “可是死火山也会复苏。", "t": [11700, 14750]}, {"fr": "Nous écrivons des choses éternelles.", "zh": "”小王子打断他的话。", "t": [14750, 16663]}]}, {"id": "ch15p37", "audio": true, "sents": [{"fr": "— Mais les volcans éteints peuvent se réveiller, interrompit le petit prince.", "zh": "” “火山死与不死，在我们看来都是一回事。", "t": [100, 5738]}, {"fr": "Qu’est-ce que signifie \"éphémère\" ?", "zh": "”地理学家说。", "t": [5738, 8088]}]}, {"id": "ch15p38", "audio": true, "sents": [{"fr": "— Que les volcans soient éteints ou soient éveillés, ça revient au même pour nous autres, dit le géographe.", "zh": "” “什么叫做‘昙花一现’？", "t": [100, 6988]}, {"fr": "Ce qui compte pour nous, c’est la montagne.", "zh": "”小王子继续追问。", "t": [6988, 10125]}, {"fr": "Elle ne change pas.", "zh": "他素来如此，一旦提出一个问题，绝不肯放弃。", "t": [10125, 10976]}]}, {"id": "ch15p39", "audio": true, "sents": [{"fr": "— Mais qu’est-ce que signifie \"éphémère\" ?", "zh": "他素来如此，一旦提出一个问题，绝不肯放弃。", "t": [100, 4550]}, {"fr": "répéta le petit prince qui, de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.", "zh": "“‘昙花一现’的意思就是‘面临很快消失的危险’。", "t": [4550, 10188]}]}, {"id": "ch15p40", "audio": true, "sents": [{"fr": "— Ça signifie \"qui est menacé de disparition prochaine\".", "zh": "” “当然。", "t": [100, 4100]}]}, {"id": "ch15p41", "audio": true, "sents": [{"fr": "— Ma fleur est menacée de disparition prochaine ?", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [100, 4013]}]}, {"id": "ch15p42", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "” “我的花会‘昙花一现’，”小王子想，“而她只有四根刺保护自己，应付这个世界！", "t": [100, 1874]}]}, {"id": "ch15p43", "audio": true, "sents": [{"fr": "Ma fleur est éphémère, se dit le petit prince, et elle n’a que quatre épines pour se défendre contre le monde !", "zh": "我却抛弃了她，让她孤苦伶仃地待在我家！", "t": [100, 7125]}, {"fr": "Et je l’ai laissée toute seule chez moi !", "zh": "” 他头一次体会到悔恨的感觉。", "t": [7125, 9426]}]}, {"id": "ch15p44", "audio": true, "sents": [{"fr": "Ce fut là son premier mouvement de regret.", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [100, 2900]}, {"fr": "Mais il reprit courage :", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [2900, 4826]}]}, {"id": "ch15p45", "audio": true, "sents": [{"fr": "— Que me conseillez-vous d’aller visiter ?", "zh": "然而他还是鼓起勇气问： “您能否指点我，我该去哪儿访问？", "t": [100, 3912]}, {"fr": "demanda-t-il.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [3912, 4762]}]}, {"id": "ch15p46", "audio": true, "sents": [{"fr": "— La planète Terre, lui répondit le géographe.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 4762]}, {"fr": "Elle a une bonne réputation…", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [4762, 6188]}]}, {"id": "ch15p47", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut, songeant à sa fleur.", "zh": "” “到地球上去吧，”地理学家说，“它非常有名……” 小王子走了，一路上都在思念他的花儿。", "t": [100, 2850]}]}, {"id": "ch15p48", "audio": true, "sents": []}]}, {"id": "ch16", "title_fr": "Chapitre XVI", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": []}, {"id": "ch16p01", "audio": true, "sents": [{"fr": "La septième planète fut donc la Terre.", "zh": "第七颗星球就是地球。", "t": [100, 2212]}]}, {"id": "ch16p02", "audio": true, "sents": [{"fr": "La Terre n’est pas une planète quelconque !", "zh": "地球可不是等闲之辈！", "t": [100, 3525]}, {"fr": "On y compte cent onze rois (en n’oubliant pas, bien sûr, les rois nègres), sept mille géographes, neuf cent mille businessmen, sept millions et demi d’ivrognes, trois cent onze millions de vaniteux, c’est-à-dire environ deux milliards de grandes personnes.", "zh": "地球上有一百一十一位国王（我当然没有忘记算上黑人国王）、七千位地理学家、九十万个商人、七百五十万个酒鬼、三亿一千一百万个爱慕虚荣的人，也就是说，约莫有二十亿个大人。", "t": [3525, 17075]}]}, {"id": "ch16p03", "audio": true, "sents": [{"fr": "Pour vous donner une idée des dimensions de la Terre je vous dirai qu’avant l’invention de l’électricité on y devait entretenir, sur l’ensemble des six continents, une véritable armée de quatre cent soixante-deux mille cinq cent onze allumeurs de réverbères.", "zh": "为了让你们对地球的面积大小有个具体形象的概念，我给你们打个比方。", "t": [100, 11913]}]}, {"id": "ch16p04", "audio": true, "sents": [{"fr": "Vu d’un peu loin ça faisait un effet splendide.", "zh": "我告诉你们，世界上还没有人发明电的时候，六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。", "t": [100, 3375]}, {"fr": "Les mouvements de cette armée étaient réglés comme ceux d’un ballet d’opéra.", "zh": "从稍远处眺望这支大军，真是蔚为壮观。", "t": [3375, 7925]}, {"fr": "D’abord venait le tour des allumeurs de réverbères de Nouvelle-Zélande et d’Australie.", "zh": "点灯人的动作犹如芭蕾舞演员的动作：整齐划一，井然有序。", "t": [7925, 12500]}, {"fr": "Puis ceux-ci, ayant allumé leurs lampions, s’en allaient dormir.", "zh": "点灯人的动作犹如芭蕾舞演员的动作：整齐划一，井然有序。", "t": [12500, 16788]}, {"fr": "Alors entraient à leur tour dans la danse les allumeurs de réverbères de Chine et de Sibérie.", "zh": "首先上场的是新西兰、澳大利亚的点灯人，他们点亮路灯后就去睡觉。", "t": [16788, 21875]}, {"fr": "Puis eux aussi s’escamotaient dans les coulisses.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [21875, 24862]}, {"fr": "Alors venait le tour des allumeurs de réverbères de Russie et des Indes.", "zh": "接着加入舞蹈行列的是中国和西伯利亚的点灯人，然后他们也隐没于后台。", "t": [24862, 29375]}, {"fr": "Puis de ceux d’Afrique et d’Europe.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [29375, 31750]}, {"fr": "Puis de ceux d’Amérique du Sud.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [31750, 34212]}, {"fr": "Puis de ceux d’Amérique du Nord.", "zh": "然后轮到俄罗斯和印度的点灯人，接着是非洲和欧洲的，然后是南美洲、北美洲。", "t": [34212, 36612]}, {"fr": "Et jamais ils ne se trompaient dans leur ordre d’entrée en scène.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [36612, 40138]}, {"fr": "C’était grandiose.", "zh": "这支大军的进场顺序从不错乱，真是让人叹为观止。", "t": [40138, 41200]}]}, {"id": "ch16p05", "audio": true, "sents": [{"fr": "Seuls, l’allumeur de l’unique réverbère du pôle Nord, et son confrère de l’unique réverbère du pôle Sud, menaient des vies d’oisiveté et de nonchalance : ils travaillaient deux fois par an.", "zh": "惟有北极点灯人和他的南极同行，过着悠闲懒散的生活。", "t": [100, 10625]}]}, {"id": "ch16p06", "audio": true, "sents": []}, {"id": "ch16p07", "audio": true, "sents": []}]}, {"id": "ch17", "title_fr": "Chapitre XVII", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"fr": "Quand on veut faire de l’esprit, il arrive que l’on mente un peu.", "zh": "好出风头，喜欢卖弄聪明的人，多少会讲几句大话，吹点牛皮。", "t": [100, 4012]}, {"fr": "Je n’ai pas été très honnête en vous parlant des allumeurs de réverbères.", "zh": "我给你们介绍点灯人的时候，也不太老实。", "t": [4012, 8375]}, {"fr": "Je risque de donner une fausse idée de notre planète à ceux qui ne la connaissent pas.", "zh": "我也许让不了解我们星球的人产生误解，造成错觉。", "t": [8375, 13000]}, {"fr": "Les hommes occupent très peu de place sur la terre.", "zh": "人在地球上占的位置微乎其微。", "t": [13000, 16312]}, {"fr": "Si les deux milliards d’habitants qui peuplent la terre se tenaient debout et un peu serrés, comme pour un meeting, ils logeraient aisément sur une place publique de vingt milles de long sur vingt milles de large.", "zh": "倘若让散居在地球上的二十亿人口集中在一起开大会，他们可以松快地站在二十英里长二十英里宽的广场上。", "t": [16312, 26325]}, {"fr": "On pourrait entasser l’humanité sur le moindre petit îlot du Pacifique.", "zh": "当然，大人们不会相信这些话。", "t": [26325, 29912]}]}, {"id": "ch17p01", "audio": true, "sents": [{"fr": "Les grandes personnes, bien sûr, ne vous croiront pas.", "zh": "他们以为自己占了很大的位置，自以为自己像猴面包树那么庞大。", "t": [100, 4038]}, {"fr": "Elles s’imaginent tenir beaucoup de place.", "zh": "那你就建议他们算一算。", "t": [4038, 7025]}, {"fr": "Elles se voient importantes comme des baobabs.", "zh": "他们会高兴的。", "t": [7025, 10050]}, {"fr": "Vous leur conseillerez donc de faire le calcul.", "zh": "但我劝你们别多此一举了，挺麻烦的，毫无用处的。", "t": [10050, 13312]}, {"fr": "Elles adorent les chiffres : ça leur plaira.", "zh": "相信我的话吧。", "t": [13312, 16950]}, {"fr": "Mais ne perdez pas votre temps à ce pensum.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [16950, 19962]}, {"fr": "C’est inutile.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [19962, 21825]}, {"fr": "Vous avez confiance en moi.", "zh": "小王子来到地球后，看不见一个人影，不由心里纳闷。", "t": [21825, 23200]}]}, {"id": "ch17p02", "audio": true, "sents": [{"fr": "Le petit prince, une fois sur terre, fut donc bien surpris de ne voir personne.", "zh": "他担心走错了路，到了别的星球了。", "t": [100, 5662]}, {"fr": "Il avait déjà peur de s’être trompé de planète, quand un anneau couleur de lune remua dans le sable.", "zh": "“晚安！", "t": [5662, 10800]}]}, {"id": "ch17p03", "audio": true, "sents": [{"fr": "— Bonne nuit, fit le petit prince à tout hasard.", "zh": "“这儿是什么星球？", "t": [100, 3637]}]}, {"id": "ch17p04", "audio": true, "sents": [{"fr": "— Bonne nuit, fit le serpent.", "zh": "“是地球，非洲。", "t": [100, 2650]}]}, {"id": "ch17p05", "audio": true, "sents": [{"fr": "— Sur quelle planète suis-je tombé ?", "zh": "“哦？", "t": [100, 3688]}, {"fr": "demanda le petit prince.", "zh": "……地球上没人吗？", "t": [3688, 4963]}]}, {"id": "ch17p06", "audio": true, "sents": [{"fr": "— Sur la Terre, en Afrique, répondit le serpent.", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [100, 4025]}]}, {"id": "ch17p07", "audio": true, "sents": [{"fr": "— Ah !…", "zh": "” “这儿是沙漠，沙漠里是没有人烟的，地球很大。", "t": [100, 3038]}, {"fr": "Il n’y a donc personne sur la Terre ?", "zh": "”蛇说。", "t": [3038, 5425]}]}, {"id": "ch17p08", "audio": true, "sents": [{"fr": "— Ici c’est le désert.", "zh": "”蛇说。", "t": [100, 3162]}, {"fr": "Il n’y a personne dans les déserts.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [3162, 5700]}, {"fr": "La Terre est grande, dit le serpent.", "zh": "小王子坐在一块石头上，抬头看天空： “我在想，星星发亮是否为了让每个人有一天能找到自己的星星。", "t": [5700, 7563]}]}, {"id": "ch17p09", "audio": true, "sents": [{"fr": "Le petit prince s’assit sur une pierre et leva les yeux vers le ciel :", "zh": "你看我的星球，它正好在我的头顶上……可它多么的遥远！", "t": [100, 3750]}]}, {"id": "ch17p10", "audio": true, "sents": [{"fr": "— Je me demande, dit-il, si les étoiles sont éclairées afin que chacun puisse un jour retrouver la sienne.", "zh": "” “它真美。", "t": [100, 7638]}, {"fr": "Regarde ma planète.", "zh": "“你来这儿干什么？", "t": [7638, 9938]}, {"fr": "Elle est juste au-dessus de nous…", "zh": "” “我和一朵花赌气闹别扭呢。", "t": [9938, 12125]}, {"fr": "Mais comme elle est loin !", "zh": "”小王子说。", "t": [12125, 13813]}]}, {"id": "ch17p11", "audio": true, "sents": [{"fr": "— Elle est belle, dit le serpent.", "zh": "“哦！", "t": [100, 3538]}, {"fr": "Que viens-tu faire ici ?", "zh": "他们都缄口不言了。", "t": [3538, 5375]}]}, {"id": "ch17p12", "audio": true, "sents": [{"fr": "— J’ai des difficultés avec une fleur, dit le petit prince.", "zh": "”小王子终于开口说话。", "t": [100, 4362]}]}, {"id": "ch17p13", "audio": true, "sents": [{"fr": "— Ah !", "zh": "”小王子终于开口说话。", "t": [100, 2488]}, {"fr": "fit le serpent.", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [2488, 3224]}]}, {"id": "ch17p14", "audio": true, "sents": [{"fr": "Et ils se turent.", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [100, 925]}]}, {"id": "ch17p15", "audio": true, "sents": [{"fr": "— Où sont les hommes ?", "zh": "“待在沙漠有点孤独……” “跟人在一起也孤独。", "t": [100, 2862]}, {"fr": "reprit enfin le petit prince.", "zh": "”蛇说。", "t": [2862, 5175]}, {"fr": "On est un peu seul dans le désert…", "zh": "小王子久久凝视着它。", "t": [5175, 6876]}]}, {"id": "ch17p16", "audio": true, "sents": [{"fr": "— On est seul aussi chez les hommes, dit le serpent.", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [100, 3500]}]}, {"id": "ch17p17", "audio": true, "sents": [{"fr": "Le petit prince le regarda longtemps :", "zh": "“你是奇特的动物，”小王子终于说道，“你像一根指头般细……” “可我比国王的指头强大得多。", "t": [100, 2812]}]}, {"id": "ch17p18", "audio": true, "sents": [{"fr": "— Tu es une drôle de bête, lui dit-il enfin, mince comme un doigt…", "zh": "”蛇说。", "t": [100, 4662]}]}, {"id": "ch17p19", "audio": true, "sents": [{"fr": "— Mais je suis plus puissant que le doigt d’un roi, dit le serpent.", "zh": "小王子微微一笑。", "t": [100, 4087]}]}, {"id": "ch17p20", "audio": true, "sents": [{"fr": "Le petit prince eut un sourire :", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [100, 2288]}]}, {"id": "ch17p21", "audio": true, "sents": [{"fr": "— Tu n’es pas bien puissant…", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [100, 2462]}, {"fr": "tu n’as même pas de pattes…", "zh": "“你没有那么强大吧……你连爪子都没有……你连走路都不会……” “船能送你走远路，可我能送你走更远的路。", "t": [2462, 3750]}, {"fr": "tu ne peux même pas voyager…", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [3750, 5063]}]}, {"id": "ch17p22", "audio": true, "sents": [{"fr": "— Je puis t’emporter plus loin qu’un navire, dit le serpent.", "zh": "” 它盘着小王子的脚踝，像一只金镯子。", "t": [100, 4025]}]}, {"id": "ch17p23", "audio": true, "sents": [{"fr": "Il s’enroula autour de la cheville du petit prince, comme un bracelet d’or :", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [100, 4587]}]}, {"id": "ch17p24", "audio": true, "sents": [{"fr": "— Celui que je touche, je le rends à la terre dont il est sorti, dit-il encore.", "zh": "“我碰到谁，就能把他送回他来的地方，”蛇还说，“但你纯洁，你是从星球上来的……” 小王子默默无言。", "t": [100, 6125]}, {"fr": "Mais tu es pur et tu viens d’une étoile…", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [6125, 8038]}]}, {"id": "ch17p25", "audio": true, "sents": [{"fr": "Le petit prince ne répondit rien.", "zh": "“我同情你，在这花岗岩构成的地球上，你这么弱小。", "t": [100, 1937]}]}, {"id": "ch17p26", "audio": true, "sents": [{"fr": "— Tu me fais pitié, toi si faible, sur cette Terre de granit.", "zh": "如果你有朝一日思念你的星球，我可以帮助你。", "t": [100, 5588]}, {"fr": "Je puis t’aider un jour si tu regrettes trop ta planète.", "zh": "我可以……” “啊！", "t": [5588, 9262]}, {"fr": "Je puis…", "zh": "我可以……” “啊！", "t": [9262, 9950]}]}, {"id": "ch17p27", "audio": true, "sents": [{"fr": "— Oh !", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [100, 3038]}, {"fr": "J’ai très bien compris, fit le petit prince, mais pourquoi parles-tu toujours par énigmes ?", "zh": "我完全明白你的意思，”小王子说，“但你的话为什么句句都像谜似的？", "t": [3038, 8362]}]}, {"id": "ch17p28", "audio": true, "sents": [{"fr": "— Je les résous toutes, dit le serpent.", "zh": "”蛇说。", "t": [100, 3037]}]}, {"id": "ch17p29", "audio": true, "sents": [{"fr": "Et ils se turent.", "zh": "他们都不讲话了。", "t": [100, 925]}]}, {"id": "ch17p30", "audio": true, "sents": []}]}, {"id": "ch18", "title_fr": "Chapitre XVIII", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"fr": "Le petit prince traversa le désert et ne rencontra qu'une fleur.", "zh": "小王子穿过沙漠，只遇见一朵花。", "t": [100, 4300]}, {"fr": "Une fleur à trois pétales, une fleur de rien du tout...", "zh": "一朵三瓣的花，一朵极普通平凡的花…… “你好。", "t": [4300, 7150]}]}, {"id": "ch18p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "“你好。", "t": [100, 2063]}]}, {"id": "ch18p02", "audio": true, "sents": [{"fr": "— Bonjour, dit la fleur.", "zh": "“人在哪儿呢？", "t": [100, 1787]}]}, {"id": "ch18p03", "audio": true, "sents": [{"fr": "— Où sont les hommes ? demanda poliment le petit prince.", "zh": "”小王子彬彬有礼地问。", "t": [100, 2837]}]}, {"id": "ch18p04", "audio": true, "sents": [{"fr": "La fleur, un jour, avait vu passer une caravane :", "zh": "“人？", "t": [100, 3275]}]}, {"id": "ch18p05", "audio": true, "sents": [{"fr": "— Les hommes ? Il en existe, je crois, six ou sept.", "zh": "依我看，人是有的，大概六七个吧。", "t": [100, 5150]}, {"fr": "Je les ai aperçus il y a des années.", "zh": "但我不知道在哪儿能找到他们。", "t": [5150, 7862]}, {"fr": "Mais on ne sait jamais où les trouver.", "zh": "风把他们吹散了。", "t": [7862, 10400]}, {"fr": "Le vent les promène.", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [10400, 12325]}, {"fr": "Ils manquent de racines, ça les gêne beaucoup.", "zh": "他们没有根，这就使他们吃尽了苦头。", "t": [12325, 14800]}]}, {"id": "ch18p06", "audio": true, "sents": [{"fr": "— Adieu, fit le petit prince.", "zh": "”小王子说。", "t": [100, 1825]}]}, {"id": "ch18p07", "audio": true, "sents": [{"fr": "— Adieu, dit la fleur.", "zh": "”花儿说。", "t": [100, 1550]}]}]}, {"id": "ch19", "title_fr": "Chapitre XIX", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": []}, {"id": "ch19p01", "audio": true, "sents": [{"fr": "Le petit prince fit l’ascension d’une haute montagne.", "zh": "小王子登上一座高山。", "t": [100, 3425]}, {"fr": "Les seules montagnes qu’il eût jamais connues étaient les trois volcans qui lui arrivaient au genou.", "zh": "死火山只能给他当凳子坐。", "t": [3425, 8325]}, {"fr": "Et il se servait du volcan éteint comme d’un tabouret.", "zh": "“站在这座高山上，”他想道，“我一眼就能看见整个星球和所有的人了……” 但他只看见悬崖峭壁。", "t": [8325, 11650]}, {"fr": "\"D’une montagne haute comme celle-ci, se dit-il donc, j’apercevrai d’un coup toute la planète et tous les hommes…\" Mais il n’aperçut rien que des aiguilles de roc bien aiguisées.", "zh": "“您好。", "t": [11650, 21150]}]}, {"id": "ch19p02", "audio": true, "sents": [{"fr": "— Bonjour, dit-il à tout hasard.", "zh": "”小王子问。", "t": [100, 3150]}]}, {"id": "ch19p03", "audio": true, "sents": [{"fr": "— Bonjour…", "zh": "”小王子问。", "t": [100, 2700]}, {"fr": "Bonjour…", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [2700, 4312]}, {"fr": "Bonjour…", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [4312, 5238]}, {"fr": "répondit l’écho.", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [5238, 6200]}]}, {"id": "ch19p04", "audio": true, "sents": [{"fr": "— Qui êtes-vous ?", "zh": "“您是谁……您是谁……您是谁……”回声应道。", "t": [100, 2812]}, {"fr": "dit le petit prince.", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [2812, 3800]}]}, {"id": "ch19p05", "audio": true, "sents": [{"fr": "— Qui êtes-vous…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [100, 2088]}, {"fr": "qui êtes-vous…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [2088, 2888]}, {"fr": "qui êtes-vous…", "zh": "“做我的朋友吧，我很孤单……”他说。", "t": [2888, 3762]}, {"fr": "répondit l’écho.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [3762, 4687]}]}, {"id": "ch19p06", "audio": true, "sents": [{"fr": "— Soyez mes amis, je suis seul, dit-il.", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [100, 3650]}]}, {"id": "ch19p07", "audio": true, "sents": [{"fr": "— Je suis seul…", "zh": "“我很孤单……我很孤单……我很孤单……”回声又答应道。", "t": [100, 2125]}, {"fr": "je suis seul…", "zh": "“多么古怪的星球！", "t": [2125, 2988]}, {"fr": "je suis seul…", "zh": "“多么古怪的星球！", "t": [2988, 3912]}, {"fr": "répondit l’écho.", "zh": "“多么古怪的星球！", "t": [3912, 4800]}]}, {"id": "ch19p08", "audio": true, "sents": [{"fr": "\"Quelle drôle de planète !", "zh": "”小王子想道。", "t": [100, 2175]}, {"fr": "pensa-t-il alors.", "zh": "”小王子想道。", "t": [2175, 4075]}, {"fr": "Elle est toute sèche, et toute pointue et toute salée.", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [4075, 7538]}, {"fr": "Et les hommes manquent d’imagination.", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [7538, 10100]}, {"fr": "Ils répètent ce qu’on leur dit…", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [10100, 12450]}, {"fr": "Chez moi j’avais une fleur : elle parlait toujours la première…\"", "zh": "“干干巴巴的，尖尖峭峭的，带点咸味儿的，这儿的人缺乏想像力，他们净重复别人讲过的话……而在我的那个星球里，我有一朵花，她总是抢先讲话……”", "t": [12450, 16062]}]}, {"id": "ch19p09", "audio": true, "sents": []}, {"id": "ch19p10", "audio": true, "sents": []}]}, {"id": "ch20", "title_fr": "Chapitre XX", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"fr": "Mais il arriva que le petit prince, ayant longtemps marché à travers les sables, les rocs et les neiges, découvrit enfin une route.", "zh": "他终于看见了一条路，条条路都通向有人烟的地方。", "t": [100, 7800]}, {"fr": "Et les routes vont toutes chez les hommes.", "zh": "”他说。", "t": [7800, 9400]}]}, {"id": "ch20p01", "audio": true, "sents": [{"fr": "— Bonjour, dit-il.", "zh": "“你好。", "t": [100, 2562]}]}, {"id": "ch20p02", "audio": true, "sents": [{"fr": "C’était un jardin fleuri de roses.", "zh": "”玫瑰花们说。", "t": [100, 1887]}]}, {"id": "ch20p03", "audio": true, "sents": [{"fr": "— Bonjour, dirent les roses.", "zh": "小王子看着她们。", "t": [100, 2763]}]}, {"id": "ch20p04", "audio": true, "sents": [{"fr": "Le petit prince les regarda.", "zh": "她们一个个全像他的那朵花儿。", "t": [100, 2562]}, {"fr": "Elles ressemblaient toutes à sa fleur.", "zh": "“你们是谁？", "t": [2562, 4250]}]}, {"id": "ch20p05", "audio": true, "sents": [{"fr": "— Qui êtes-vous ?", "zh": "”小王子大吃一惊，问她们说。", "t": [100, 3388]}, {"fr": "leur demanda-t-il, stupéfait.", "zh": "“我们是玫瑰花。", "t": [3388, 5488]}]}, {"id": "ch20p06", "audio": true, "sents": [{"fr": "— Nous sommes des roses, dirent les roses.", "zh": "”玫瑰花们说。", "t": [100, 3075]}]}, {"id": "ch20p07", "audio": true, "sents": [{"fr": "— Ah !", "zh": "”小王子说…… 小王子伤心极了。", "t": [100, 2462]}, {"fr": "fit le petit prince…", "zh": "”小王子说…… 小王子伤心极了。", "t": [2462, 3475]}]}, {"id": "ch20p08", "audio": true, "sents": [{"fr": "Et il se sentit très malheureux.", "zh": "”小王子说…… 小王子伤心极了。", "t": [100, 2375]}, {"fr": "Sa fleur lui avait raconté qu’elle était seule de son espèce dans l’univers.", "zh": "他的花儿告诉他，大千世界中，她是惟一的玫瑰花。", "t": [2375, 6875]}, {"fr": "Et voici qu’il en était cinq mille, toutes semblables, dans un seul jardin !", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [6875, 11274]}]}, {"id": "ch20p09", "audio": true, "sents": [{"fr": "\"Elle serait bien vexée, se dit-il, si elle voyait ça…", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [100, 3612]}, {"fr": "elle tousserait énormément et ferait semblant de mourir pour échapper au ridicule.", "zh": "可是在这儿，仅仅一座花园里就有五千朵玫瑰花，全都长得一模一样！", "t": [3612, 8275]}, {"fr": "Et je serais bien obligé de faire semblant de la soigner, car, sinon, pour m’humilier moi aussi, elle se laisserait vraiment mourir…\"", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [8275, 15462]}]}, {"id": "ch20p10", "audio": true, "sents": [{"fr": "Puis il se dit encore : \"Je me croyais riche d’une fleur unique, et je ne possède qu’une rose ordinaire.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [100, 6912]}, {"fr": "Ça et mes trois volcans qui m’arrivent au genou, et dont l’un, peut-être, est éteint pour toujours, ça ne fait pas de moi un bien grand prince…\" Et, couché dans l’herbe, il pleura.", "zh": "他想：“要是她看见这群玫瑰花，她又要恼羞成怒了……为了挽回面子，她又要装模作样地咳嗽，做出一副要死要活的样子，我也要呵护她，不然，她为了羞辱我，真会寻死的……” 他又想道：“我原以为我拥有一朵独一无二的花，我以为我很富足，原来她只是一朵极平常的花，她，以及我那三座只有我膝盖高的火山——其中一座也许永远都活不了，它们不能使我成为一位伟大的王子了……” 于是，他趴倒在草地上伤心地哭泣。", "t": [6912, 16963]}]}, {"id": "ch20p11", "audio": true, "sents": []}]}, {"id": "ch21", "title_fr": "Chapitre XXI", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": []}, {"id": "ch21p01", "audio": true, "sents": [{"fr": "C’est alors qu’apparut le renard :", "zh": "就在这个时候，出现了一只狐狸。", "t": [100, 2338]}]}, {"id": "ch21p02", "audio": true, "sents": [{"fr": "— Bonjour, dit le renard.", "zh": "“你好。", "t": [100, 2837]}]}, {"id": "ch21p03", "audio": true, "sents": [{"fr": "— Bonjour, répondit poliment le petit prince, qui se retourna mais ne vit rien.", "zh": "“你好。", "t": [100, 5600]}]}, {"id": "ch21p04", "audio": true, "sents": [{"fr": "— Je suis là, dit la voix, sous le pommier.", "zh": "”小王子彬彬有礼地回答，他转过身，但看不见有什么东西。", "t": [100, 3450]}]}, {"id": "ch21p05", "audio": true, "sents": [{"fr": "— Qui es-tu ?", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [100, 2762]}, {"fr": "dit le petit prince.", "zh": "“我在这里，”那声音说，“在苹果树下。", "t": [2762, 4612]}, {"fr": "Tu es bien joli…", "zh": "” “你是谁？", "t": [4612, 5587]}]}, {"id": "ch21p06", "audio": true, "sents": [{"fr": "— Je suis un renard, dit le renard.", "zh": "” “你是谁？", "t": [100, 3112]}]}, {"id": "ch21p07", "audio": true, "sents": [{"fr": "— Viens jouer avec moi, lui proposa le petit prince.", "zh": "”小王子说，“你真漂亮……” “我是狐狸。", "t": [100, 5025]}, {"fr": "Je suis tellement triste…", "zh": "“来跟我一起玩吧。", "t": [5025, 6313]}]}, {"id": "ch21p08", "audio": true, "sents": [{"fr": "— Je ne puis pas jouer avec toi, dit le renard.", "zh": "”小王子向他建议。", "t": [100, 4475]}, {"fr": "Je ne suis pas apprivoisé.", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [4475, 5875]}]}, {"id": "ch21p09", "audio": true, "sents": [{"fr": "— Ah !", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [100, 3038]}, {"fr": "pardon, fit le petit prince.", "zh": "“我非常伤心……” “我不能跟你一起玩，”狐狸说，“我不是驯养的动物。", "t": [3038, 4863]}]}, {"id": "ch21p10", "audio": true, "sents": [{"fr": "Mais, après réflexion, il ajouta :", "zh": "” “哦，对不起。", "t": [100, 3263]}]}, {"id": "ch21p11", "audio": true, "sents": [{"fr": "— Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "” “哦，对不起。", "t": [100, 3588]}]}, {"id": "ch21p12", "audio": true, "sents": [{"fr": "— Tu n’es pas d’ici, dit le renard, que cherches-tu ?", "zh": "小王子想了想，又问： “什么叫做‘驯养’？", "t": [100, 4575]}]}, {"id": "ch21p13", "audio": true, "sents": [{"fr": "— Je cherche les hommes, dit le petit prince.", "zh": "” “你不是本地人。", "t": [100, 4362]}, {"fr": "Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "”狐狸说。", "t": [4362, 6762]}]}, {"id": "ch21p14", "audio": true, "sents": [{"fr": "— Les hommes, dit le renard, ils ont des fusils et ils chassent.", "zh": "可人也养鸡！", "t": [100, 5225]}, {"fr": "C’est bien gênant !", "zh": "你也找鸡吗？", "t": [5225, 7688]}, {"fr": "Ils élèvent aussi des poules.", "zh": "” “不！", "t": [7688, 10012]}, {"fr": "C’est leur seul intérêt.", "zh": "”小王子说，“我找朋友。", "t": [10012, 12000]}, {"fr": "Tu cherches des poules ?", "zh": "什么叫做‘驯养’？", "t": [12000, 13612]}]}, {"id": "ch21p15", "audio": true, "sents": [{"fr": "— Non, dit le petit prince.", "zh": "什么叫做‘驯养’？", "t": [100, 3662]}, {"fr": "Je cherche des amis.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [3662, 5700]}, {"fr": "Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [5700, 8100]}]}, {"id": "ch21p16", "audio": true, "sents": [{"fr": "— C’est une chose trop oubliée, dit le renard.", "zh": "” “这是一件被人遗忘干净的事了，”狐狸说，“它的意思就是‘建立联系’……” “建立联系？", "t": [100, 4412]}, {"fr": "Ça signifie \"créer des liens…\"", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [4412, 6150]}]}, {"id": "ch21p17", "audio": true, "sents": [{"fr": "— Créer des liens ?", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [100, 2750]}]}, {"id": "ch21p18", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "” “当然，”狐狸说，“对我而言，你不过是一个小男孩，和千千万万的小男孩没有两样。", "t": [100, 3762]}, {"fr": "Tu n’es encore pour moi qu’un petit garçon tout semblable à cent mille petits garçons.", "zh": "而且我不需要你，你也不需要我。", "t": [3762, 8425]}, {"fr": "Et je n’ai pas besoin de toi.", "zh": "而且我不需要你，你也不需要我。", "t": [8425, 10675]}, {"fr": "Et tu n’as pas besoin de moi non plus.", "zh": "对你而言，我只是一只狐狸，和千千万万只狐狸没有两样。", "t": [10675, 13212]}, {"fr": "Je ne suis pour toi qu’un renard semblable à cent mille renards.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [13212, 17100]}, {"fr": "Mais, si tu m’apprivoises, nous aurons besoin l’un de l’autre.", "zh": "但如果你驯养了我，我们就互相需要了。", "t": [17100, 21388]}, {"fr": "Tu seras pour moi unique au monde.", "zh": "你就是我世界上惟一的人了，我也是你世上惟一的狐狸了……” “我有点明白了。", "t": [21388, 23975]}, {"fr": "Je serai pour toi unique au monde…", "zh": "”小王子说。", "t": [23975, 25763]}]}, {"id": "ch21p19", "audio": true, "sents": [{"fr": "— Je commence à comprendre, dit le petit prince.", "zh": "”小王子说。", "t": [100, 4688]}, {"fr": "Il y a une fleur…", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [4688, 5838]}, {"fr": "je crois qu’elle m’a apprivoisé…", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [5838, 7237]}]}, {"id": "ch21p20", "audio": true, "sents": [{"fr": "— C’est possible, dit le renard.", "zh": "“有一朵花儿……我认为她驯养了我……” “这可能，”狐狸说，“地球上有各色各样，形形色色的东西……” “啊！", "t": [100, 3750]}, {"fr": "On voit sur la Terre toutes sortes de choses…", "zh": "她不在地球上。", "t": [3750, 5738]}]}, {"id": "ch21p21", "audio": true, "sents": [{"fr": "— Oh !", "zh": "她不在地球上。", "t": [100, 3038]}, {"fr": "ce n’est pas sur la Terre, dit le petit prince.", "zh": "”小王子说。", "t": [3038, 5525]}]}, {"id": "ch21p22", "audio": true, "sents": [{"fr": "Le renard parut très intrigué :", "zh": "狐狸露出大惊的神色。", "t": [100, 2575]}]}, {"id": "ch21p23", "audio": true, "sents": [{"fr": "— Sur une autre planète ?", "zh": "“在另一个星球上？", "t": [100, 2900]}]}, {"id": "ch21p24", "audio": true, "sents": [{"fr": "— Oui.", "zh": "” “是的。", "t": [100, 1525]}]}, {"id": "ch21p25", "audio": true, "sents": [{"fr": "— Il y a des chasseurs, sur cette planète-là ?", "zh": "” “那颗星球上，有猎人吗？", "t": [100, 4163]}]}, {"id": "ch21p26", "audio": true, "sents": [{"fr": "— Non.", "zh": "” “没有。", "t": [100, 1474]}]}, {"id": "ch21p27", "audio": true, "sents": [{"fr": "— Ça, c’est intéressant !", "zh": "” “没有。", "t": [100, 4188]}, {"fr": "Et des poules ?", "zh": "” “那可有意思了！", "t": [4188, 5474]}]}, {"id": "ch21p28", "audio": true, "sents": [{"fr": "— Non.", "zh": "有鸡吗？", "t": [100, 1474]}]}, {"id": "ch21p29", "audio": true, "sents": [{"fr": "— Rien n’est parfait, soupira le renard.", "zh": "” “没有。", "t": [100, 3500]}]}, {"id": "ch21p30", "audio": true, "sents": [{"fr": "Mais le renard revint à son idée :", "zh": "” “世上就没有十全十美的东西。", "t": [100, 2588]}]}, {"id": "ch21p31", "audio": true, "sents": [{"fr": "— Ma vie est monotone.", "zh": "”狐狸叹了一口气。", "t": [100, 3212]}, {"fr": "Je chasse les poules, les hommes me chassent.", "zh": "狐狸又扯回原先的话题： “我的生活枯燥乏味，异常单调。", "t": [3212, 6350]}, {"fr": "Toutes les poules se ressemblent, et tous les hommes se ressemblent.", "zh": "我逮鸡，人逮我。", "t": [6350, 10150]}, {"fr": "Je m’ennuie donc un peu.", "zh": "鸡全是一个模样，人也是一个模样，我都腻了。", "t": [10150, 12375]}, {"fr": "Mais, si tu m’apprivoises, ma vie sera comme ensoleillée.", "zh": "鸡全是一个模样，人也是一个模样，我都腻了。", "t": [12375, 16600]}, {"fr": "Je connaîtrai un bruit de pas qui sera différent de tous les autres.", "zh": "但如果你驯养我，我的生活就会充满阳光。", "t": [16600, 20550]}, {"fr": "Les autres pas me font rentrer sous terre.", "zh": "别人的脚步声吓得我赶紧钻回地洞。", "t": [20550, 23438]}, {"fr": "Le tien m’appellera hors du terrier, comme une musique.", "zh": "你的脚步声却像悦耳的音乐，召唤我走出洞穴。", "t": [23438, 27150]}, {"fr": "Et puis regarde !", "zh": "你的脚步声却像悦耳的音乐，召唤我走出洞穴。", "t": [27150, 29550]}, {"fr": "Tu vois, là-bas, les champs de blé ?", "zh": "你瞧！", "t": [29550, 33338]}, {"fr": "Je ne mange pas de pain.", "zh": "你看那儿，那不是一片麦田吗？", "t": [33338, 35438]}, {"fr": "Le blé pour moi est inutile.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [35438, 37988]}, {"fr": "Les champs de blé ne me rappellent rien.", "zh": "我不吃面包，我不需要小麦，麦田引不起我的想像力。", "t": [37988, 40600]}, {"fr": "Et ça, c’est triste !", "zh": "说到这个，实在可悲！", "t": [40600, 43325]}, {"fr": "Mais tu as des cheveux couleur d’or.", "zh": "说到这个，实在可悲！", "t": [43325, 45862]}, {"fr": "Alors ce sera merveilleux quand tu m’auras apprivoisé !", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [45862, 49950]}, {"fr": "Le blé, qui est doré, me fera souvenir de toi.", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [49950, 53900]}, {"fr": "Et j’aimerai le bruit du vent dans le blé…", "zh": "但你的头发是金灿灿的，它会叫我想起你的，我就会爱上风吹麦子的声音……”狐狸没说下去，对小王子瞧了好久，又说： “请你……驯养我吧！", "t": [53900, 55688]}]}, {"id": "ch21p32", "audio": true, "sents": [{"fr": "Le renard se tut et regarda longtemps le petit prince :", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 3375]}]}, {"id": "ch21p33", "audio": true, "sents": [{"fr": "— S’il te plaît…", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 2038]}, {"fr": "apprivoise-moi !", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [2038, 3725]}, {"fr": "dit-il.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [3725, 4250]}]}, {"id": "ch21p34", "audio": true, "sents": [{"fr": "— Je veux bien, répondit le petit prince, mais je n’ai pas beaucoup de temps.", "zh": "” “我很愿意，”小王子回答说，“但我的时间不多，我还要寻找朋友，还要了解许多新鲜的事物。", "t": [100, 5900]}, {"fr": "J’ai des amis à découvrir et beaucoup de choses à connaître.", "zh": "” “人只认识自己驯养的东西。", "t": [5900, 8775]}]}, {"id": "ch21p35", "audio": true, "sents": [{"fr": "— On ne connaît que les choses que l’on apprivoise, dit le renard.", "zh": "“人再没时间认识什么事物。", "t": [100, 5088]}, {"fr": "Les hommes n’ont plus le temps de rien connaître.", "zh": "他们到商店买现成的东西，但没有一家商店是出售朋友的，人也就没有朋友了。", "t": [5088, 8112]}, {"fr": "Ils achètent des choses toutes faites chez les marchands.", "zh": "如果你想要朋友，你就驯养我吧！", "t": [8112, 11225]}, {"fr": "Mais comme il n’existe point de marchands d’amis, les hommes n’ont plus d’amis.", "zh": "” “我该做些什么呢？", "t": [11225, 15775]}, {"fr": "Si tu veux un ami, apprivoise-moi !", "zh": "”狐狸回答说。", "t": [15775, 18437]}]}, {"id": "ch21p36", "audio": true, "sents": [{"fr": "— Que faut-il faire ?", "zh": "”狐狸回答说。", "t": [100, 2988]}, {"fr": "dit le petit prince.", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [2988, 3988]}]}, {"id": "ch21p37", "audio": true, "sents": [{"fr": "— Il faut être très patient, répondit le renard.", "zh": "“首先你要离我稍远点，坐着，像这样，坐在草地上。", "t": [100, 4712]}, {"fr": "Tu t’assoiras d’abord un peu loin de moi, comme ça, dans l’herbe.", "zh": "语言是误会的源泉。", "t": [4712, 8975]}, {"fr": "Je te regarderai du coin de l’œil et tu ne diras rien.", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [8975, 12512]}, {"fr": "Le langage est source de malentendus.", "zh": "可是每天你可以坐得稍近一点……” 翌日，小王子又来了。", "t": [12512, 15362]}, {"fr": "Mais, chaque jour, tu pourras t’asseoir un peu plus près…", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [15362, 18450]}]}, {"id": "ch21p38", "audio": true, "sents": [{"fr": "Le lendemain revint le petit prince.", "zh": "“最好在同一个时间来，”狐狸说，“例如，如果你是下午四点钟来的，从三点钟开始，我就开始感觉到幸福的滋味了。", "t": [100, 1925]}]}, {"id": "ch21p39", "audio": true, "sents": [{"fr": "— Il eût mieux valu revenir à la même heure, dit le renard.", "zh": "越接近四点钟，我越觉得幸福。", "t": [100, 4988]}, {"fr": "Si tu viens, par exemple, à quatre heures de l’après-midi, dès trois heures je commencerai d’être heureux.", "zh": "到了四点钟，我就心神恍惚，坐立不安了。", "t": [4988, 11162]}, {"fr": "Plus l’heure avancera, plus je me sentirai heureux.", "zh": "我发现了幸福的价值，但是如果你不按时来，我就不知道几点钟该装扮我的心，仪式还是需要的。", "t": [11162, 14625]}, {"fr": "A quatre heures, déjà, je m’agiterai et m’inquiéterai ; je découvrirai le prix du bonheur !", "zh": "” “什么叫做‘仪式’？", "t": [14625, 21925]}, {"fr": "Mais si tu viens n’importe quand, je ne saurai jamais à quelle heure m’habiller le cœur…", "zh": "“这也是一件被人遗忘干净了的事情。", "t": [21925, 26762]}, {"fr": "Il faut des rites.", "zh": "”狐狸说。", "t": [26762, 27688]}]}, {"id": "ch21p40", "audio": true, "sents": [{"fr": "— Qu’est-ce qu’un rite ?", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [100, 2862]}, {"fr": "dit le petit prince.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [2862, 3850]}]}, {"id": "ch21p41", "audio": true, "sents": [{"fr": "— C’est aussi quelque chose de trop oublié, dit le renard.", "zh": "“仪式就是使得某一日不同于其他日子，某一个小时不同于别的小时。", "t": [100, 5075]}, {"fr": "C’est ce qui fait qu’un jour est différent des autres jours, une heure, des autres heures.", "zh": "比如说，猎人们有个仪式，每逢星期四，他们就与村里的姑娘们跳舞，星期四就成了再美妙不过的日子了！", "t": [5075, 10188]}, {"fr": "Il y a un rite, par exemple, chez mes chasseurs.", "zh": "我也就可以到葡萄园里去闲逛了。", "t": [10188, 14025]}, {"fr": "Ils dansent le jeudi avec les filles du village.", "zh": "我也就可以到葡萄园里去闲逛了。", "t": [14025, 17212]}, {"fr": "Alors le jeudi est jour merveilleux !", "zh": "如果猎人跳舞不挑日子，每一天都一样，我就没有假期了。", "t": [17212, 20450]}, {"fr": "Je vais me promener jusqu’à la vigne.", "zh": "” 于是小王子驯养狐狸了。", "t": [20450, 23138]}, {"fr": "Si les chasseurs dansaient n’importe quand, les jours se ressembleraient tous, et je n’aurais point de vacances.", "zh": "“啊！", "t": [23138, 28463]}]}, {"id": "ch21p42", "audio": true, "sents": [{"fr": "Ainsi le petit prince apprivoisa le renard.", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [100, 3150]}, {"fr": "Et quand l’heure du départ fut proche :", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [3150, 5338]}]}, {"id": "ch21p43", "audio": true, "sents": [{"fr": "— Ah !", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [100, 2400]}, {"fr": "dit le renard…", "zh": "” “这就是你的不对了，”小王子说，“我一点也不想伤害你，但你却要我驯养你……” “不错。", "t": [2400, 4050]}, {"fr": "Je pleurerai.", "zh": "”狐狸说。", "t": [4050, 4900]}]}, {"id": "ch21p44", "audio": true, "sents": [{"fr": "— C’est ta faute, dit le petit prince, je ne te souhaitais point de mal, mais tu as voulu que je t’apprivoise…", "zh": "”小王子说。", "t": [100, 6812]}]}, {"id": "ch21p45", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "“那你是一无所获了！", "t": [100, 2900]}]}, {"id": "ch21p46", "audio": true, "sents": [{"fr": "— Mais tu vas pleurer !", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [100, 3212]}, {"fr": "dit le petit prince.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [3212, 4213]}]}, {"id": "ch21p47", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "” “我有收获的，”狐狸说，“我得到了小麦的颜色。", "t": [100, 2900]}]}, {"id": "ch21p48", "audio": true, "sents": [{"fr": "— Alors tu n’y gagnes rien !", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 3213]}]}, {"id": "ch21p49", "audio": true, "sents": [{"fr": "— J’y gagne, dit le renard, à cause de la couleur du blé.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 4437]}]}, {"id": "ch21p50", "audio": true, "sents": [{"fr": "Puis il ajouta :", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 1812]}]}, {"id": "ch21p51", "audio": true, "sents": [{"fr": "— Va revoir les roses.", "zh": "” 然后他又说： “你去探望玫瑰花们吧，你就会明白，你的玫瑰花是世界上独一无二的花儿。", "t": [100, 3150]}, {"fr": "Tu comprendras que la tienne est unique au monde.", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [3150, 6312]}, {"fr": "Tu reviendras me dire adieu, et je te ferai cadeau d’un secret.", "zh": "然后你回来与我告别，我会送你一桩秘密作为礼物。", "t": [6312, 9576]}]}, {"id": "ch21p52", "audio": true, "sents": [{"fr": "Le petit prince s’en fut revoir les roses :", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [100, 2737]}]}, {"id": "ch21p53", "audio": true, "sents": [{"fr": "— Vous n’êtes pas du tout semblables à ma rose, vous n’êtes rien encore, leur dit-il.", "zh": "” 小王子探望玫瑰花们，并对她们说： “你们一点也不像我的玫瑰，你们还无足轻重，没有人驯养你们，你们也没有驯养任何人。", "t": [100, 6350]}, {"fr": "Personne ne vous a apprivoisé et vous n’avez apprivoisé personne.", "zh": "你们的今天如同我的狐狸的昨天。", "t": [6350, 10350]}, {"fr": "Vous êtes comme était mon renard.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [10350, 12812]}, {"fr": "Ce n’était qu’un renard semblable à cent mille autres.", "zh": "昨天的他与千千万万的狐狸一样，但自从我让他做了我的朋友，他就是世上绝无仅有的狐狸了。", "t": [12812, 16100]}, {"fr": "Mais j’en ai fait mon ami, et il est maintenant unique au monde.", "zh": "” 玫瑰花们听了心里怪不自在的。", "t": [16100, 19125]}]}, {"id": "ch21p54", "audio": true, "sents": [{"fr": "Et les roses étaient bien gênées.", "zh": "” 玫瑰花们听了心里怪不自在的。", "t": [100, 1475]}]}, {"id": "ch21p55", "audio": true, "sents": [{"fr": "— Vous êtes belles, mais vous êtes vides, leur dit-il encore.", "zh": "“你们长得很美，但你们的感情世界一片空白。", "t": [100, 5238]}, {"fr": "On ne peut pas mourir pour vous.", "zh": "“没有人为你们而死。", "t": [5238, 7475]}, {"fr": "Bien sûr, ma rose à moi, un passant ordinaire croirait qu’elle vous ressemble.", "zh": "“没有人为你们而死。", "t": [7475, 12600]}, {"fr": "Mais à elle seule elle est plus importante que vous toutes, puisque c’est elle que j’ai arrosée.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [12600, 17688]}, {"fr": "Puisque c’est elle que j’ai mise sous globe.", "zh": "不错，行人会认为我的玫瑰与你们没有两样，但只有她比你们重要，因为我给她浇了水，我给她盖上花罩，我给她竖起屏风，给她避风挡雨。", "t": [17688, 20625]}, {"fr": "Puisque c’est elle que j’ai abritée par le paravent.", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [20625, 23912]}, {"fr": "Puisque c’est elle dont j’ai tué les chenilles (sauf les deux ou trois pour les papillons).", "zh": "我为她杀死了几条毛虫（除了两三条我没杀，要让它们变成蝴蝶），我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子，因为她是我的玫瑰。", "t": [23912, 28838]}, {"fr": "Puisque c’est elle que j’ai écoutée se plaindre, ou se vanter, ou même quelquefois se taire.", "zh": "” 他回到狐狸身边。", "t": [28838, 34288]}, {"fr": "Puisque c’est ma rose.", "zh": "“别了。", "t": [34288, 35450]}]}, {"id": "ch21p56", "audio": true, "sents": [{"fr": "Et il revint vers le renard :", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [100, 2125]}]}, {"id": "ch21p57", "audio": true, "sents": [{"fr": "— Adieu, dit-il…", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [100, 2262]}]}, {"id": "ch21p58", "audio": true, "sents": [{"fr": "— Adieu, dit le renard.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [100, 3462]}, {"fr": "Voici mon secret.", "zh": "”他说…… “别了，”狐狸说，“这就是我的秘密，它很简单：用心去看才能看清楚，用眼睛是看不见本质的东西的。", "t": [3462, 5362]}, {"fr": "Il est très simple : on ne voit bien qu’avec le cœur.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [5362, 9575]}, {"fr": "L’essentiel est invisible pour les yeux.", "zh": "” “用眼睛是看不见本质的东西的。", "t": [9575, 11450]}]}, {"id": "ch21p59", "audio": true, "sents": [{"fr": "— L’essentiel est invisible pour les yeux, répéta le petit prince, afin de se souvenir.", "zh": "”小王子重复念叨这句话，为了把它牢牢记住。", "t": [100, 6075]}]}, {"id": "ch21p60", "audio": true, "sents": [{"fr": "— C’est le temps que tu as perdu pour ta rose qui fait ta rose si importante.", "zh": "“你为你的玫瑰失去的时间，使你的玫瑰变得重要了。", "t": [100, 4725]}]}, {"id": "ch21p61", "audio": true, "sents": [{"fr": "— C’est le temps que j’ai perdu pour ma rose…", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [100, 3262]}, {"fr": "fit le petit prince, afin de se souvenir.", "zh": "” “我为我的玫瑰失去的时间，使我的玫瑰……”小王子说道，为了把它记住。", "t": [3262, 5687]}]}, {"id": "ch21p62", "audio": true, "sents": [{"fr": "— Les hommes ont oublié cette vérité, dit le renard.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [100, 4775]}, {"fr": "Mais tu ne dois pas l’oublier.", "zh": "“人忘记了这条真理，”狐狸说，“但你不该忘。", "t": [4775, 7062]}, {"fr": "Tu deviens responsable pour toujours de ce que tu as apprivoisé.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [7062, 11125]}, {"fr": "Tu es responsable de ta rose…", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [11125, 12900]}]}, {"id": "ch21p63", "audio": true, "sents": [{"fr": "— Je suis responsable de ma rose…", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [100, 3212]}, {"fr": "répéta le petit prince, afin de se souvenir.", "zh": "你应该永远对你驯养的对象负责，你要对你的玫瑰负责……” “我要对我的玫瑰负责……”小王子反复念叨狐狸的教诲，为了牢牢记住它。", "t": [3212, 5925]}]}, {"id": "ch21p64", "audio": true, "sents": []}]}, {"id": "ch22", "title_fr": "Chapitre XXII", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": []}, {"id": "ch22p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "”小王子说。", "t": [100, 3074]}]}, {"id": "ch22p02", "audio": true, "sents": [{"fr": "— Bonjour, dit l’aiguilleur.", "zh": "”扳道工说。", "t": [100, 2863]}]}, {"id": "ch22p03", "audio": true, "sents": [{"fr": "— Que fais-tu ici ?", "zh": "“你在这儿干什么？", "t": [100, 3100]}, {"fr": "dit le petit prince.", "zh": "” “我给旅客们分组。", "t": [3100, 4088]}]}, {"id": "ch22p04", "audio": true, "sents": [{"fr": "— Je trie les voyageurs, par paquets de mille, dit l’aiguilleur.", "zh": "”扳道工说。", "t": [100, 6125]}, {"fr": "J’expédie les trains qui les emportent, tantôt vers la droite, tantôt vers la gauche.", "zh": "“载乘客的火车也由我调度，它们有时开往左方，有时开往右方。", "t": [6125, 10000]}]}, {"id": "ch22p05", "audio": true, "sents": [{"fr": "Et un rapide illuminé, grondant comme le tonnerre, fit trembler la cabine d’aiguillage.", "zh": "” 一列灯火通明的火车风驰电掣般奔来，轰隆隆的响声震得调度室抖动摇晃。", "t": [100, 4675]}]}, {"id": "ch22p06", "audio": true, "sents": [{"fr": "— Ils sont bien pressés, dit le petit prince.", "zh": "”小王子说。", "t": [100, 4362]}, {"fr": "Que cherchent-ils ?", "zh": "“他们寻找什么？", "t": [4362, 5762]}]}, {"id": "ch22p07", "audio": true, "sents": [{"fr": "— L’homme de la locomotive l’ignore lui-même, dit l’aiguilleur.", "zh": "” “坐在火车头上的人也不知道他们要寻找什么。", "t": [100, 4300]}]}, {"id": "ch22p08", "audio": true, "sents": [{"fr": "Et gronda, en sens inverse, un second rapide illuminé.", "zh": "第二列灯火通明的火车轰隆隆地，从相反的方向奔驰而来。", "t": [100, 3550]}]}, {"id": "ch22p09", "audio": true, "sents": [{"fr": "— Ils reviennent déjà ?", "zh": "“他们已经回来了？", "t": [100, 3150]}, {"fr": "demanda le petit prince…", "zh": "“他们已经回来了？", "t": [3150, 4413]}]}, {"id": "ch22p10", "audio": true, "sents": [{"fr": "— Ce ne sont pas les mêmes, dit l’aiguilleur.", "zh": "”小王子问…… “这列车坐的不是刚才那些人。", "t": [100, 4300]}, {"fr": "C’est un échange.", "zh": "”扳道工说。", "t": [4300, 5112]}]}, {"id": "ch22p11", "audio": true, "sents": [{"fr": "— Ils n’étaient pas contents, là où ils étaient ?", "zh": "“这是对开的火车。", "t": [100, 3813]}]}, {"id": "ch22p12", "audio": true, "sents": [{"fr": "— On n’est jamais content là où l’on est, dit l’aiguilleur.", "zh": "” “人总是这山望着那山高的。", "t": [100, 3813]}]}, {"id": "ch22p13", "audio": true, "sents": [{"fr": "Et gronda le tonnerre d’un troisième rapide illuminé.", "zh": "”扳道工说。", "t": [100, 2712]}]}, {"id": "ch22p14", "audio": true, "sents": [{"fr": "— Ils poursuivent les premiers voyageurs ?", "zh": "第三列灯火通明的火车也轰隆隆地响起来了。", "t": [100, 3850]}, {"fr": "demanda le petit prince.", "zh": "“他们在追赶第一批旅客吗？", "t": [3850, 5125]}]}, {"id": "ch22p15", "audio": true, "sents": [{"fr": "— Ils ne poursuivent rien du tout, dit l’aiguilleur.", "zh": "”小王子问。", "t": [100, 4550]}, {"fr": "Ils dorment là-dedans, ou bien ils bâillent.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [4550, 7575]}, {"fr": "Les enfants seuls écrasent leur nez contre les vitres.", "zh": "“他们从不追赶人，”扳道工说，“他们在车厢里睡大觉或打哈欠，只有孩子们才把鼻子贴在玻璃窗上看外面的世界。", "t": [7575, 10037]}]}, {"id": "ch22p16", "audio": true, "sents": [{"fr": "— Les enfants seuls savent ce qu’ils cherchent, fit le petit prince.", "zh": "” “只有孩子才知道他们要寻觅什么。", "t": [100, 5275]}, {"fr": "Ils perdent du temps pour une poupée de chiffons, et elle devient très importante, et si on la leur enlève, ils pleurent…", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [5275, 11287]}]}, {"id": "ch22p17", "audio": true, "sents": [{"fr": "— Ils ont de la chance, dit l’aiguilleur.", "zh": "“他们花不少时间与布娃娃玩，布娃娃变得很重要，如果有人抢走他们的布娃娃，他们就哭鼻子……” “他们是有运气的人……”", "t": [100, 3200]}]}, {"id": "ch22p18", "audio": true, "sents": []}]}, {"id": "ch23", "title_fr": "Chapitre XXIII", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "”小王子说。", "t": [100, 3074]}]}, {"id": "ch23p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le marchand.", "zh": "“你好。", "t": [100, 2776]}]}, {"id": "ch23p02", "audio": true, "sents": [{"fr": "C’était un marchand de pilules perfectionnées qui apaisent la soif.", "zh": "这位商人贩卖解渴的药丸。", "t": [100, 4162]}, {"fr": "On en avale une par semaine et l’on n’éprouve plus le besoin de boire.", "zh": "“为什么你卖这种药？", "t": [4162, 7338]}]}, {"id": "ch23p03", "audio": true, "sents": [{"fr": "— Pourquoi vends-tu ça ?", "zh": "”小王子问。", "t": [100, 3112]}, {"fr": "dit le petit prince.", "zh": "”小王子问。", "t": [3112, 4125]}]}, {"id": "ch23p04", "audio": true, "sents": [{"fr": "— C’est une grosse économie de temps, dit le marchand.", "zh": "“为了节省更多的时间，”商人说，“专家们计算过，每个星期能节省五十三分钟。", "t": [100, 4662]}, {"fr": "Les experts ont fait des calculs.", "zh": "“为了节省更多的时间，”商人说，“专家们计算过，每个星期能节省五十三分钟。", "t": [4662, 7300]}, {"fr": "On épargne cinquante-trois minutes par semaine.", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [7300, 9513]}]}, {"id": "ch23p05", "audio": true, "sents": [{"fr": "— Et que fait-on des cinquante-trois minutes ?", "zh": "” “节省的这五十三分钟，有什么用途？", "t": [100, 3538]}]}, {"id": "ch23p06", "audio": true, "sents": [{"fr": "— On en fait ce que l’on veut…", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 2500]}]}, {"id": "ch23p07", "audio": true, "sents": [{"fr": "\"Moi, se dit le petit prince, si j’avais cinquante-trois minutes à dépenser, je marcherais tout doucement vers une fontaine…\"", "zh": "” “人可以干自己愿意干的事……” 小王子想：“要是我节省下这五十三分钟，我就要悠闲自在地朝一泓泉水走去……”", "t": [100, 6425]}]}, {"id": "ch23p08", "audio": true, "sents": []}]}, {"id": "ch24", "title_fr": "Chapitre XXIV", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": []}, {"id": "ch24p01", "audio": true, "sents": [{"fr": "Nous en étions au huitième jour de ma panne dans le désert, et j’avais écouté l’histoire du marchand en buvant la dernière goutte de ma provision d’eau :", "zh": "我的飞机在沙漠出故障的第八天，我听到了商人的故事，此时我储存的水已喝完了，一滴不剩。", "t": [100, 7838]}]}, {"id": "ch24p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "我对小王子说： “啊！", "t": [100, 3038]}, {"fr": "dis-je au petit prince, ils sont bien jolis, tes souvenirs, mais je n’ai pas encore réparé mon avion, je n’ai plus rien à boire, et je serais heureux, moi aussi, si je pouvais marcher tout doucement vers une fontaine !", "zh": "你的这些回忆挺美好的，但我还没修好我的飞机，我的水也喝完了，如果我能悠闲自在地向一泓泉水走过去，我也会很幸福快活的！", "t": [3038, 15250]}]}, {"id": "ch24p03", "audio": true, "sents": [{"fr": "— Mon ami le renard, me dit-il…", "zh": "” “我的朋友狐狸告诉我……” “我的小人儿，别再说狐狸的事了！", "t": [100, 3100]}]}, {"id": "ch24p04", "audio": true, "sents": [{"fr": "— Mon petit bonhomme, il ne s’agit plus du renard !", "zh": "” “为什么？", "t": [100, 4375]}]}, {"id": "ch24p05", "audio": true, "sents": [{"fr": "— Pourquoi ?", "zh": "” “为什么？", "t": [100, 2462]}]}, {"id": "ch24p06", "audio": true, "sents": [{"fr": "— Parce qu’on va mourir de soif…", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [100, 2712]}]}, {"id": "ch24p07", "audio": true, "sents": [{"fr": "Il ne comprit pas mon raisonnement, il me répondit :", "zh": "” “因为我快渴死了……” 他听不懂我说的理由。", "t": [100, 3388]}]}, {"id": "ch24p08", "audio": true, "sents": [{"fr": "— C’est bien d’avoir eu un ami, même si l’on va mourir.", "zh": "他说道： “有个朋友真好，哪怕命在旦夕。", "t": [100, 4900]}, {"fr": "Moi, je suis bien content d’avoir eu un ami renard…", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [4900, 7725]}]}, {"id": "ch24p09", "audio": true, "sents": [{"fr": "Il ne mesure pas le danger, me dis-je.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [100, 3188]}, {"fr": "Il n’a jamais ni faim ni soif.", "zh": "我很满意狐狸做了我的朋友……” 我想：“他不知道危险的可怕，他从未尝过饥渴的滋味。", "t": [3188, 5625]}, {"fr": "Un peu de soleil lui suffit…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [5625, 7138]}]}, {"id": "ch24p10", "audio": true, "sents": [{"fr": "Mais il me regarda et répondit à ma pensée :", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 3225]}]}, {"id": "ch24p11", "audio": true, "sents": [{"fr": "— J’ai soif aussi…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [100, 2262]}, {"fr": "cherchons un puits…", "zh": "他只要一点儿阳光就满足了……” 他看着我，似乎猜中了我的念头： “我也渴……我们去找一口井吧……” 我做了个无法可想的手势。", "t": [2262, 3125]}]}, {"id": "ch24p12", "audio": true, "sents": [{"fr": "J’eus un geste de lassitude : il est absurde de chercher un puits, au hasard, dans l’immensité du désert.", "zh": "在一望无际的沙漠中寻一口井，这不是太荒唐了吗？", "t": [100, 7538]}, {"fr": "Cependant nous nous mîmes en marche.", "zh": "在一望无际的沙漠中寻一口井，这不是太荒唐了吗？", "t": [7538, 9112]}]}, {"id": "ch24p13", "audio": true, "sents": [{"fr": "Quand nous eûmes marché, des heures, en silence, la nuit tomba, et les étoiles commencèrent de s’éclairer.", "zh": "我们默默地走了几个小时。", "t": [100, 7000]}, {"fr": "Je les apercevais comme en rêve, ayant un peu de fièvre, à cause de ma soif.", "zh": "由于干渴，我在发烧，看见星星，还以为自己在梦中呢。", "t": [7000, 12175]}, {"fr": "Les mots du petit prince dansaient dans ma mémoire :", "zh": "小王子说的话也似乎在我的脑海中跳跃。", "t": [12175, 15000]}]}, {"id": "ch24p14", "audio": true, "sents": [{"fr": "— Tu as donc soif, toi aussi ?", "zh": "“你也口渴了吗？", "t": [100, 4650]}, {"fr": "lui demandai-je.", "zh": "“你也口渴了吗？", "t": [4650, 5612]}]}, {"id": "ch24p15", "audio": true, "sents": [{"fr": "Mais il ne répondit pas à ma question.", "zh": "”我问他。", "t": [100, 2812]}, {"fr": "Il me dit simplement :", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [2812, 4626]}]}, {"id": "ch24p16", "audio": true, "sents": [{"fr": "— L’eau peut aussi être bonne pour le cœur…", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [100, 3087]}]}, {"id": "ch24p17", "audio": true, "sents": [{"fr": "Je ne compris pas sa réponse mais je me tus…", "zh": "他不回答我的问题，只简单地对我说： “水对心也有好处……” 我听不懂他的话，但我不做声……我知道不应该问他。", "t": [100, 3125]}, {"fr": "Je savais bien qu’il ne fallait pas l’interroger.", "zh": "他走乏了，坐了下来。", "t": [3125, 5400]}]}, {"id": "ch24p18", "audio": true, "sents": [{"fr": "Il était fatigué.", "zh": "他走乏了，坐了下来。", "t": [100, 2000]}, {"fr": "Il s’assit.", "zh": "我靠着他坐下。", "t": [2000, 3625]}, {"fr": "Je m’assis auprès de lui.", "zh": "我靠着他坐下。", "t": [3625, 5912]}, {"fr": "Et, après un silence, il dit encore :", "zh": "沉默了一会，他又说： “星星美丽，因为里面有一朵看不见的花。", "t": [5912, 8812]}]}, {"id": "ch24p19", "audio": true, "sents": [{"fr": "— Les étoiles sont belles, à cause d’une fleur que l’on ne voit pas…", "zh": "” 我应了一句：“当然。", "t": [100, 4187]}]}, {"id": "ch24p20", "audio": true, "sents": [{"fr": "Je répondis \"bien sûr\" et je regardai, sans parler, les plis du sable sous la lune.", "zh": "”然后我不做声，看着月光下的起伏的沙丘。", "t": [100, 4975]}]}, {"id": "ch24p21", "audio": true, "sents": [{"fr": "— Le désert est beau, ajouta-t-il…", "zh": "”他又说。", "t": [100, 3024]}]}, {"id": "ch24p22", "audio": true, "sents": [{"fr": "Et c’était vrai.", "zh": "我素来喜爱沙漠。", "t": [100, 1688]}, {"fr": "J’ai toujours aimé le désert.", "zh": "我们坐在沙丘上。", "t": [1688, 4150]}, {"fr": "On s’assoit sur une dune de sable.", "zh": "我们无所见，我们无所闻。", "t": [4150, 6700]}, {"fr": "On ne voit rien.", "zh": "我们无所见，我们无所闻。", "t": [6700, 8438]}, {"fr": "On n’entend rien.", "zh": "我们无所见，我们无所闻。", "t": [8438, 10162]}, {"fr": "Et cependant quelque chose rayonne en silence…", "zh": "然而，有什么东西在静静地发光…… “沙漠美丽，因为沙漠的某处隐藏着一口井。", "t": [10162, 12376]}]}, {"id": "ch24p23", "audio": true, "sents": [{"fr": "— Ce qui embellit le désert, dit le petit prince, c’est qu’il cache un puits quelque part…", "zh": "”小王子说。", "t": [100, 5850]}]}, {"id": "ch24p24", "audio": true, "sents": [{"fr": "Je fus surpris de comprendre soudain ce mystérieux rayonnement du sable.", "zh": "我吃了一惊，因为我突然明白，沙漠中那神秘的闪闪发亮的东西是什么了。", "t": [100, 4612]}, {"fr": "Lorsque j’étais petit garçon j’habitais une maison ancienne, et la légende racontait qu’un trésor y était enfoui.", "zh": "我还是一个小男孩的时候，住在一幢古老大屋里。", "t": [4612, 11050]}, {"fr": "Bien sûr, jamais personne n’a su le découvrir, ni peut-être même ne l’a cherché.", "zh": "也许甚至没人去找它。", "t": [11050, 16425]}, {"fr": "Mais il enchantait toute cette maison.", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [16425, 19012]}, {"fr": "Ma maison cachait un secret au fond de son cœur…", "zh": "但它像给这幢屋子施了魔法，让它凭空增添了吸引力。", "t": [19012, 21387]}]}, {"id": "ch24p25", "audio": true, "sents": [{"fr": "— Oui, dis-je au petit prince, qu’il s’agisse de la maison, des étoiles ou du désert, ce qui fait leur beauté est invisible !", "zh": "房里埋藏着秘密…… “你说得对，”我对小王子说，“房子也好，星星、沙漠也好，美化它们的东西是肉眼看不见的！", "t": [100, 8424]}]}, {"id": "ch24p26", "audio": true, "sents": [{"fr": "— Je suis content, dit-il, que tu sois d’accord avec mon renard.", "zh": "” “我很欣慰，”他说，“你同意狐狸的看法。", "t": [100, 4800]}]}, {"id": "ch24p27", "audio": true, "sents": [{"fr": "Comme le petit prince s’endormait, je le pris dans mes bras, et me remis en route.", "zh": "” 小王子入睡了。", "t": [100, 5175]}, {"fr": "J’étais ému.", "zh": "我受了感动。", "t": [5175, 6900]}, {"fr": "Il me semblait porter un trésor fragile.", "zh": "我受了感动。", "t": [6900, 9850]}, {"fr": "Il me semblait même qu’il n’y eût rien de plus fragile sur la Terre.", "zh": "我甚至觉得地球上没有比他更脆弱的东西了。", "t": [9850, 13838]}, {"fr": "Je regardais, à la lumière de la lune, ce front pâle, ces yeux clos, ces mèches de cheveux qui tremblaient au vent, et je me disais : ce que je vois là n’est qu’une écorce.", "zh": "借着银色的月光，我细细看他苍白的前额、闭着的双目、随风抖动的绺绺秀发。", "t": [13838, 24575]}, {"fr": "Le plus important est invisible…", "zh": "我心想：“我看见的只是一具躯壳，最重要的东西是看不见的……” 他半张的嘴唇上泛出浅浅的微笑。", "t": [24575, 26388]}]}, {"id": "ch24p28", "audio": true, "sents": [{"fr": "Comme ses lèvres entr’ouvertes ébauchaient un demi-sourire je me dis encore : \"Ce qui m’émeut si fort de ce petit prince endormi, c’est sa fidélité pour une fleur, c’est l’image d’une rose qui rayonne en lui comme la flamme d’une lampe, même quand il dort…\" Et je le devinai plus fragile encore.", "zh": "我又想：“这位睡着了的小王子打动了我，而打动了我的是他对花的忠贞。", "t": [100, 20700]}, {"fr": "Il faut bien protéger les lampes : un coup de vent peut les éteindre…", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [20700, 21200]}]}, {"id": "ch24p29", "audio": true, "sents": [{"fr": "Et, marchant ainsi, je découvris le puits au lever du jour.", "zh": "灯是需要我们小心保护的，一股风就会把它吹灭……我就这样走着，曙光初露时我看见了那口井。", "t": [100, 3474]}]}, {"id": "ch24p30", "audio": true, "sents": []}]}, {"id": "ch25", "title_fr": "Chapitre XXV", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": []}, {"id": "ch25p01", "audio": true, "sents": [{"fr": "— Les hommes, dit le petit prince, ils s’enfournent dans les rapides, mais ils ne savent plus ce qu’ils cherchent.", "zh": "“人挤在快车的车厢里，”小王子说，“却不知道他们要寻找什么。", "t": [100, 7488]}, {"fr": "Alors ils s’agitent et tournent en rond…", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [7488, 9162]}]}, {"id": "ch25p02", "audio": true, "sents": [{"fr": "Et il ajouta :", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 1738]}]}, {"id": "ch25p03", "audio": true, "sents": [{"fr": "— Ce n’est pas la peine…", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 2125]}]}, {"id": "ch25p04", "audio": true, "sents": [{"fr": "Le puits que nous avions atteint ne ressemblait pas aux puits sahariens.", "zh": "他们焦躁不安，团团乱转……” 他又说： “这又何苦呢……” 我们找到的井不像撒哈拉沙漠的井。", "t": [100, 3888]}, {"fr": "Les puits sahariens sont de simples trous creusés dans le sable.", "zh": "撒哈拉沙漠的井是在沙里挖个洞，而我们找到的这口井与村子里的井一样，可是这儿没有一个村子。", "t": [3888, 7662]}, {"fr": "Celui-là ressemblait à un puits de village.", "zh": "我以为我正在做梦。", "t": [7662, 10775]}, {"fr": "Mais il n’y avait là aucun village, et je croyais rêver.", "zh": "我以为我正在做梦。", "t": [10775, 13788]}]}, {"id": "ch25p05", "audio": true, "sents": [{"fr": "— C’est étrange, dis-je au petit prince, tout est prêt : la poulie, le seau et la corde…", "zh": "“这就奇了，”我对小王子说，“这井一切齐备：辘轳，水桶，绳子……” 他笑了，抓住绳子，转动辘轳。", "t": [100, 6788]}]}, {"id": "ch25p06", "audio": true, "sents": [{"fr": "Il rit, toucha la corde, fit jouer la poulie.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [100, 3738]}, {"fr": "Et la poulie gémit comme gémit une vieille girouette quand le vent a longtemps dormi.", "zh": "辘轳吱吱呀呀地叫唤，活像一只老风信鸡在风长睡时的叫唤。", "t": [3738, 7424]}]}, {"id": "ch25p07", "audio": true, "sents": [{"fr": "— Tu entends, dit le petit prince, nous réveillons ce puits et il chante…", "zh": "“你听，”小王子说，“我们唤醒了这口井。", "t": [100, 5025]}]}, {"id": "ch25p08", "audio": true, "sents": [{"fr": "Je ne voulais pas qu’il fît un effort :", "zh": "它在唱歌呢……” 我不忍心看他劳力费神。", "t": [100, 2450]}]}, {"id": "ch25p09", "audio": true, "sents": [{"fr": "— Laisse-moi faire, lui dis-je, c’est trop lourd pour toi.", "zh": "“让我来干吧，”我对他说，“你干这活太重了。", "t": [100, 4213]}]}, {"id": "ch25p10", "audio": true, "sents": [{"fr": "Lentement je hissai le seau jusqu’à la margelle.", "zh": "” 我轻轻把水桶提到井口，垂直放进井内。", "t": [100, 3388]}, {"fr": "Je l’y installai bien d’aplomb.", "zh": "” 我轻轻把水桶提到井口，垂直放进井内。", "t": [3388, 5850]}, {"fr": "Dans mes oreilles durait le chant de la poulie et, dans l’eau qui tremblait encore, je voyais trembler le soleil.", "zh": "倾听着辘轳的歌声，还看见在荡漾的井水中摇动的太阳。", "t": [5850, 11213]}]}, {"id": "ch25p11", "audio": true, "sents": [{"fr": "— J’ai soif de cette eau-là, dit le petit prince, donne-moi à boire…", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”我明白他要寻找什么了。", "t": [100, 4838]}]}, {"id": "ch25p12", "audio": true, "sents": [{"fr": "Et je compris ce qu’il avait cherché !", "zh": "我把桶举到他的唇边。", "t": [100, 2538]}]}, {"id": "ch25p13", "audio": true, "sents": [{"fr": "Je soulevai le seau jusqu’à ses lèvres.", "zh": "他闭着双目喝水。", "t": [100, 2888]}, {"fr": "Il but, les yeux fermés.", "zh": "水甜得有如过节。", "t": [2888, 5288]}, {"fr": "C’était doux comme une fête.", "zh": "这水不仅是饮料，它还是别的东西。", "t": [5288, 7512]}, {"fr": "Cette eau était bien autre chose qu’un aliment.", "zh": "它是经过星光下的跋涉，在辘轳的歌声中和在我双臂的努力下诞生的。", "t": [7512, 10488]}, {"fr": "Elle était née de la marche sous les étoiles, du chant de la poulie, de l’effort de mes bras.", "zh": "它像礼物一样愉悦心灵。", "t": [10488, 15938]}, {"fr": "Elle était bonne pour le cœur, comme un cadeau.", "zh": "它像礼物一样愉悦心灵。", "t": [15938, 19112]}, {"fr": "Lorsque j’étais petit garçon, la lumière de l’arbre de Noël, la musique de la messe de minuit, la douceur des sourires faisaient ainsi tout le rayonnement du cadeau de Noël que je recevais.", "zh": "“你们这儿的人在一个园里种植五千株玫瑰……但他们却找不到他们寻觅的东西……” “他们没找到。", "t": [19112, 28500]}]}, {"id": "ch25p14", "audio": true, "sents": [{"fr": "— Les hommes de chez toi, dit le petit prince, cultivent cinq mille roses dans un même jardin…", "zh": "”我说…… “然而他们寻找的东西可以在一朵玫瑰或一点点水里找到的……” “不错。", "t": [100, 6162]}, {"fr": "et ils n’y trouvent pas ce qu’ils cherchent.", "zh": "”我说…… “然而他们寻找的东西可以在一朵玫瑰或一点点水里找到的……” “不错。", "t": [6162, 7600]}]}, {"id": "ch25p15", "audio": true, "sents": [{"fr": "— Ils ne le trouvent pas, répondis-je…", "zh": "”我回答说。", "t": [100, 2974]}]}, {"id": "ch25p16", "audio": true, "sents": [{"fr": "— Et cependant ce qu’ils cherchent pourrait être trouvé dans une seule rose ou un peu d’eau…", "zh": "小王子又说： “然而肉眼是看不见的，要用心灵去寻找。", "t": [100, 4825]}]}, {"id": "ch25p17", "audio": true, "sents": [{"fr": "— Bien sûr, répondis-je.", "zh": "” 我喝了水，呼吸畅通了。", "t": [100, 2850]}]}, {"id": "ch25p18", "audio": true, "sents": [{"fr": "Et le petit prince ajouta :", "zh": "” 我喝了水，呼吸畅通了。", "t": [100, 2274]}]}, {"id": "ch25p19", "audio": true, "sents": [{"fr": "— Mais les yeux sont aveugles.", "zh": "天亮时分，沙子颜色如蜜。", "t": [100, 3362]}, {"fr": "Il faut chercher avec le cœur.", "zh": "我也喜欢蜜般的颜色。", "t": [3362, 4900]}]}, {"id": "ch25p20", "audio": true, "sents": [{"fr": "J’avais bu.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [100, 1688]}, {"fr": "Je respirais bien.", "zh": "但为什么我的心里总有点不快乐呢？", "t": [1688, 3688]}, {"fr": "Le sable, au lever du jour, est couleur de miel.", "zh": "…… “你可要履行诺言啊。", "t": [3688, 7562]}, {"fr": "J’étais heureux aussi de cette couleur de miel.", "zh": "”小王子轻声对我说，他又靠近我坐着。", "t": [7562, 10725]}, {"fr": "Pourquoi fallait-il que j’eusse de la peine…", "zh": "“什么诺言？", "t": [10725, 12712]}]}, {"id": "ch25p21", "audio": true, "sents": [{"fr": "— Il faut que tu tiennes ta promesse, me dit doucement le petit prince, qui, de nouveau, s’était assis auprès de moi.", "zh": "” “你知道的呀……给我的绵羊画一个口罩，我要对我的花儿负责呀！", "t": [100, 7450]}]}, {"id": "ch25p22", "audio": true, "sents": [{"fr": "— Quelle promesse ?", "zh": "” 我从口袋里掏出画稿。", "t": [100, 2563]}]}, {"id": "ch25p23", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "” 我从口袋里掏出画稿。", "t": [100, 1888]}, {"fr": "une muselière pour mon mouton…", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [1888, 3425]}, {"fr": "je suis responsable de cette fleur !", "zh": "小王子看后，笑着对我说： “你画的猴面包树有点像卷心菜……” “呀！", "t": [3425, 5724]}]}, {"id": "ch25p24", "audio": true, "sents": [{"fr": "Je sortis de ma poche mes ébauches de dessin.", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [100, 3238]}, {"fr": "Le petit prince les aperçut et dit en riant :", "zh": "” 我还为我画的猴面包树自鸣得意呢！", "t": [3238, 6224]}]}, {"id": "ch25p25", "audio": true, "sents": [{"fr": "— Tes baobabs, ils ressemblent un peu à des choux…", "zh": "“你画的狐狸……它的耳朵……有点像角……太长了！", "t": [100, 3500]}]}, {"id": "ch25p26", "audio": true, "sents": [{"fr": "— Oh !", "zh": "” 他还在笑。", "t": [100, 2176]}]}, {"id": "ch25p27", "audio": true, "sents": [{"fr": "Moi qui était si fier des baobabs !", "zh": "” 他还在笑。", "t": [100, 2437]}]}, {"id": "ch25p28", "audio": true, "sents": [{"fr": "— Ton renard…", "zh": "“你不公平，小人儿。", "t": [100, 2050]}, {"fr": "ses oreilles…", "zh": "“你不公平，小人儿。", "t": [2050, 2925]}, {"fr": "elles ressemblent un peu à des cornes…", "zh": "我并不会画画，只会画打开了肚子的蟒蛇和没打开肚子的蟒蛇。", "t": [2925, 4550]}, {"fr": "et elles sont trop longues !", "zh": "我并不会画画，只会画打开了肚子的蟒蛇和没打开肚子的蟒蛇。", "t": [4550, 6188]}]}, {"id": "ch25p29", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "” “啊！", "t": [100, 1074]}]}, {"id": "ch25p30", "audio": true, "sents": [{"fr": "— Tu es injuste, petit bonhomme, je ne savais rien dessiner que les boas fermés et les boas ouverts.", "zh": "很不错的嘛，孩子们看得懂的。", "t": [100, 6562]}]}, {"id": "ch25p31", "audio": true, "sents": [{"fr": "— Oh !", "zh": "”他说。", "t": [100, 3038]}, {"fr": "ça ira, dit-il, les enfants savent.", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [3038, 5675]}]}, {"id": "ch25p32", "audio": true, "sents": [{"fr": "Je crayonnai donc une muselière.", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 2888]}, {"fr": "Et j’eus le cœur serré en la lui donnant :", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [2888, 5375]}]}, {"id": "ch25p33", "audio": true, "sents": [{"fr": "— Tu as des projets que j’ignore…", "zh": "我用铅笔画了一个口罩，把它交给他的时候，我的心揪得紧紧的： “你已有了我不知道的计划吧……” 但他避而不答。", "t": [100, 2725]}]}, {"id": "ch25p34", "audio": true, "sents": [{"fr": "Mais il ne me répondit pas.", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2200]}, {"fr": "Il me dit :", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [2200, 3550]}]}, {"id": "ch25p35", "audio": true, "sents": [{"fr": "— Tu sais, ma chute sur la Terre…", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 3325]}, {"fr": "c’en sera demain l’anniversaire…", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [3325, 4900]}]}, {"id": "ch25p36", "audio": true, "sents": [{"fr": "Puis, après un silence il dit encore :", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2813]}]}, {"id": "ch25p37", "audio": true, "sents": [{"fr": "— J’étais tombé tout près d’ici…", "zh": "他只对我说： “你知道，我落到地球上……明天已是一周年了……” 然后，沉默片刻，他又说： “当时我就落在附近……” 他的脸红了。", "t": [100, 2663]}]}, {"id": "ch25p38", "audio": true, "sents": [{"fr": "Et il rougit.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 900]}]}, {"id": "ch25p39", "audio": true, "sents": [{"fr": "Et de nouveau, sans comprendre pourquoi, j’éprouvai un chagrin bizarre.", "zh": "不知何故，我有说不出来的惆怅悲哀。", "t": [100, 5038]}, {"fr": "Cependant une question me vint :", "zh": "我提出了一个问题： “这么说，一个星期之前，认识你的那天早上，你不是偶尔一人来到这远离人烟的沙漠的？", "t": [5038, 7263]}]}, {"id": "ch25p40", "audio": true, "sents": [{"fr": "— Alors ce n’est pas par hasard que, le matin où je t’ai connu, il y a huit jours, tu te promenais comme ça, tout seul, à mille milles de toutes les régions habitées !", "zh": "你要回到你的降落点去？", "t": [100, 10688]}, {"fr": "Tu retournais vers le point de ta chute ?", "zh": "” 小王子的脸又红了。", "t": [10688, 13138]}]}, {"id": "ch25p41", "audio": true, "sents": [{"fr": "Le petit prince rougit encore.", "zh": "我犹豫着又问： “也许是为了纪念降落周年？", "t": [100, 1788]}]}, {"id": "ch25p42", "audio": true, "sents": [{"fr": "Et j’ajoutai, en hésitant :", "zh": "……” 小王子的脸再次红了。", "t": [100, 2538]}]}, {"id": "ch25p43", "audio": true, "sents": [{"fr": "— A cause, peut-être, de l’anniversaire ?…", "zh": "……” 小王子的脸再次红了。", "t": [100, 3987]}]}, {"id": "ch25p44", "audio": true, "sents": [{"fr": "Le petit prince rougit de nouveau.", "zh": "他从不回答我提的问题。", "t": [100, 2675]}, {"fr": "Il ne répondait jamais aux questions, mais, quand on rougit, ça signifie \"oui\", n’est-ce pas ?", "zh": "但一个人脸红，就意味着默认，意味着做了“是的”的回答，对吧？", "t": [2675, 8400]}]}, {"id": "ch25p45", "audio": true, "sents": [{"fr": "— Ah !", "zh": "“啊！", "t": [100, 3038]}, {"fr": "lui dis-je, j’ai peur…", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [3038, 4587]}]}, {"id": "ch25p46", "audio": true, "sents": [{"fr": "Mais il me répondit :", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 1988]}]}, {"id": "ch25p47", "audio": true, "sents": [{"fr": "— Tu dois maintenant travailler.", "zh": "”我对他说，“我怕……” 他却对我说： “现在你该干活了。", "t": [100, 3500]}, {"fr": "Tu dois repartir vers ta machine.", "zh": "你该到你的机器旁忙活儿了。", "t": [3500, 6250]}, {"fr": "Je t’attends ici.", "zh": "你该到你的机器旁忙活儿了。", "t": [6250, 8250]}, {"fr": "Reviens demain soir…", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [8250, 9463]}]}, {"id": "ch25p48", "audio": true, "sents": [{"fr": "Mais je n’étais pas rassuré.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [100, 2312]}, {"fr": "Je me souvenais du renard.", "zh": "我在这儿等你，明天晚上再来……” 但我不放心。", "t": [2312, 4638]}, {"fr": "On risque de pleurer un peu si l’on s’est laissé apprivoiser…", "zh": "我想起了狐狸的事，让别人驯养，难免要掉掉眼泪……", "t": [4638, 7312]}]}, {"id": "ch25p49", "audio": true, "sents": []}, {"id": "ch25p50", "audio": true, "sents": []}]}, {"id": "ch26", "title_fr": "Chapitre XXVI", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"fr": "Il y avait, à côté du puits, une ruine de vieux mur de pierre.", "zh": "井旁有一堵断墙残壁。", "t": [100, 4588]}, {"fr": "Lorsque je revins de mon travail, le lendemain soir, j’aperçus de loin mon petit prince assis là-haut, les jambes pendantes.", "zh": "我听见他说： “你不记得了吗？", "t": [4588, 12175]}, {"fr": "Et je l’entendis qui parlait :", "zh": "不完全在这里！", "t": [12175, 14312]}]}, {"id": "ch26p01", "audio": true, "sents": [{"fr": "— Tu ne t’en souviens donc pas ?", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [100, 3450]}, {"fr": "disait-il.", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [3450, 5025]}, {"fr": "Ce n’est pas tout à fait ici !", "zh": "” 无疑有另一个声音回了他的话，因为他反驳说： “没错！", "t": [5025, 7012]}]}, {"id": "ch26p02", "audio": true, "sents": [{"fr": "Une autre voix lui répondit sans doute, puisqu’il répliqua :", "zh": "没错！", "t": [100, 3875]}]}, {"id": "ch26p03", "audio": true, "sents": [{"fr": "— Si !", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [100, 3025]}, {"fr": "Si !", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [3025, 4988]}, {"fr": "c’est bien le jour, mais ce n’est pas ici l’endroit…", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [4988, 7650]}]}, {"id": "ch26p04", "audio": true, "sents": [{"fr": "Je poursuivis ma marche vers le mur.", "zh": "就是这一天，但不是这个地方……” 我向断墙残壁走过去，我看不见也听不见有什么人在那儿。", "t": [100, 2912]}, {"fr": "Je ne voyais ni n’entendais toujours personne.", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [2912, 6062]}, {"fr": "Pourtant le petit prince répliqua de nouveau :", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [6062, 8924]}]}, {"id": "ch26p05", "audio": true, "sents": [{"fr": "— …", "zh": "然而小王子又反驳了： “……当然，你会看到我留在沙地上的足迹，看到它是从哪儿开始的。", "t": [100, 1850]}, {"fr": "Bien sûr.", "zh": "你在那儿等我就行了。", "t": [1850, 3438]}, {"fr": "Tu verras où commence ma trace dans le sable.", "zh": "你在那儿等我就行了。", "t": [3438, 6550]}, {"fr": "Tu n’as qu’a m’y attendre.", "zh": "今夜我会在那儿等你。", "t": [6550, 9937]}, {"fr": "J’y serai cette nuit.", "zh": "今夜我会在那儿等你。", "t": [9937, 10437]}]}, {"id": "ch26p06", "audio": true, "sents": [{"fr": "J’étais à vingt mètres du mur et je ne voyais toujours rien.", "zh": "” 我离开墙才二十米，还是一无所见。", "t": [100, 2824]}]}, {"id": "ch26p07", "audio": true, "sents": [{"fr": "Le petit prince dit encore, après un silence :", "zh": "小王子沉默片刻后又说： “你有毒液吗？", "t": [100, 3325]}]}, {"id": "ch26p08", "audio": true, "sents": [{"fr": "— Tu as du bon venin ?", "zh": "你能肯定不让我经受很久的痛苦？", "t": [100, 3825]}, {"fr": "Tu es sûr de ne pas me faire souffrir longtemps ?", "zh": "你能肯定不让我经受很久的痛苦？", "t": [3825, 6687]}]}, {"id": "ch26p09", "audio": true, "sents": [{"fr": "Je fis halte, le cœur serré, mais je ne comprenais toujours pas.", "zh": "我仍然听不懂他的话。", "t": [100, 3663]}]}, {"id": "ch26p10", "audio": true, "sents": [{"fr": "— Maintenant va-t’en, dit-il…", "zh": "“现在你走吧。", "t": [100, 2838]}, {"fr": "je veux redescendre !", "zh": "“我要跳下去了！", "t": [2838, 4400]}]}, {"id": "ch26p11", "audio": true, "sents": [{"fr": "Alors j’abaissai moi-même les yeux vers le pied du mur, et je fis un bond !", "zh": "” 我的眼光落到墙根，我吓了一跳！", "t": [100, 5075]}, {"fr": "Il était là, dressé vers le petit prince, un de ces serpents jaunes qui vous exécutent en trente secondes.", "zh": "这种黄蛇最毒了，三十秒钟内就能要你的命。", "t": [5075, 11362]}, {"fr": "Tout en fouillant ma poche pour en tirer mon revolver, je pris le pas de course, mais, au bruit que je fis, le serpent se laissa doucement couler dans le sable, comme un jet d’eau qui meurt, et, sans trop se presser, se faufila entre les pierres avec un léger bruit de métal.", "zh": "蛇听到我的脚步声，轻轻地溜进沙里，如颓然跌落的水柱，不慌不忙地钻进石缝里，发出轻微的金属的声音。", "t": [11362, 25713]}]}, {"id": "ch26p12", "audio": true, "sents": [{"fr": "Je parvins au mur juste à temps pour y recevoir dans les bras mon petit bonhomme de prince, pâle comme la neige.", "zh": "“怎么回事，你和蛇说话了？", "t": [100, 5550]}]}, {"id": "ch26p13", "audio": true, "sents": [{"fr": "— Quelle est cette histoire-là !", "zh": "” 我解下他从不离身的金围巾，用水湿湿他的太阳穴，给他喝水。", "t": [100, 3875]}, {"fr": "Tu parles maintenant avec les serpents !", "zh": "现在我不敢再向他提什么问题了。", "t": [3875, 6363]}]}, {"id": "ch26p14", "audio": true, "sents": [{"fr": "J’avais défait son éternel cache-nez d’or.", "zh": "现在我不敢再向他提什么问题了。", "t": [100, 3138]}, {"fr": "Je lui avais mouillé les tempes et l’avais fait boire.", "zh": "他神情凝重地看着我，双臂搂住我的脖子。", "t": [3138, 6300]}, {"fr": "Et maintenant je n’osais plus rien lui demander.", "zh": "我感觉到他的心的狂跳，如同中弹濒死的小鸟。", "t": [6300, 9412]}, {"fr": "Il me regarda gravement et m’entoura le cou de ses bras.", "zh": "他对我说：“你找到了机器的毛病，我很高兴。", "t": [9412, 13000]}, {"fr": "Je sentais battre son cœur comme celui d’un oiseau qui meurt, quand on l’a tiré à la carabine.", "zh": "你可以回家了……” “你怎么知道的？", "t": [13000, 18700]}, {"fr": "Il me dit :", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [18700, 20050]}]}, {"id": "ch26p15", "audio": true, "sents": [{"fr": "— Je suis content que tu aies trouvé ce qui manquait à ta machine.", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [100, 4925]}, {"fr": "Tu vas pouvoir rentrer chez toi…", "zh": "” 我来找他，正是要告诉他：出乎我的意料，我竟修好了我的飞机。", "t": [4925, 6474]}]}, {"id": "ch26p16", "audio": true, "sents": [{"fr": "— Comment sais-tu !", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 2613]}]}, {"id": "ch26p17", "audio": true, "sents": [{"fr": "Je venais justement lui annoncer que, contre toute espérance, j’avais réussi mon travail !", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 5550]}]}, {"id": "ch26p18", "audio": true, "sents": [{"fr": "Il ne répondit rien à ma question, mais il ajouta :", "zh": "他不回答我的问题，却又说： “今天我也要回家了……” 然后，他神色凄伤，黯然说道： “我的家要远多了……也难回去得多……” 我感觉到发生了非比寻常的事情。", "t": [100, 3687]}]}, {"id": "ch26p19", "audio": true, "sents": [{"fr": "— Moi aussi, aujourd’hui, je rentre chez moi…", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 3763]}]}, {"id": "ch26p20", "audio": true, "sents": [{"fr": "Puis, mélancolique :", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 2150]}]}, {"id": "ch26p21", "audio": true, "sents": [{"fr": "— C’est bien plus loin…", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [100, 2312]}, {"fr": "c’est bien plus difficile…", "zh": "我把他搂进怀里，如同他是个小孩子。", "t": [2312, 3600]}]}, {"id": "ch26p22", "audio": true, "sents": [{"fr": "Je sentais bien qu’il se passait quelque chose d’extraordinaire.", "zh": "然而我觉得他直往深渊里坠下去，我一点也抓不住他…… 他目光严肃，落到远方。", "t": [100, 4138]}, {"fr": "Je le serrais dans les bras comme un petit enfant, et cependant il me semblait qu’il coulait verticalement dans un abîme sans que je pusse rien pour le retenir…", "zh": "“我有你的绵羊，我有给绵羊住的箱子。", "t": [4138, 11413]}]}, {"id": "ch26p23", "audio": true, "sents": [{"fr": "Il avait le regard sérieux, perdu très loin :", "zh": "我感觉到他的身体逐渐恢复了温暖。", "t": [100, 3263]}]}, {"id": "ch26p24", "audio": true, "sents": [{"fr": "— J’ai ton mouton.", "zh": "我感觉到他的身体逐渐恢复了温暖。", "t": [100, 2925]}, {"fr": "Et j’ai la caisse pour le mouton.", "zh": "“小人儿，你害怕了……” 当然，他害怕！", "t": [2925, 5225]}, {"fr": "Et j’ai la muselière…", "zh": "“小人儿，你害怕了……” 当然，他害怕！", "t": [5225, 6412]}]}, {"id": "ch26p25", "audio": true, "sents": [{"fr": "Et il sourit avec mélancolie.", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [100, 1725]}]}, {"id": "ch26p26", "audio": true, "sents": [{"fr": "J’attendis longtemps.", "zh": "他温和地笑笑： “今晚我会更害怕！", "t": [100, 2025]}, {"fr": "Je sentais qu’il se réchauffait peu à peu :", "zh": "” 我又一次体会到无可奈何的感觉。", "t": [2025, 4763]}]}, {"id": "ch26p27", "audio": true, "sents": [{"fr": "— Petit bonhomme, tu as eu peur…", "zh": "我全身冰冷。", "t": [100, 2987]}]}, {"id": "ch26p28", "audio": true, "sents": [{"fr": "Il avait eu peur, bien sûr !", "zh": "我全身冰冷。", "t": [100, 3300]}, {"fr": "Mais il rit doucement :", "zh": "我知道，听不见他的笑声，我会忍受不了的。", "t": [3300, 5100]}]}, {"id": "ch26p29", "audio": true, "sents": [{"fr": "— J’aurai bien plus peur ce soir…", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [100, 2763]}]}, {"id": "ch26p30", "audio": true, "sents": [{"fr": "De nouveau je me sentis glacé par le sentiment de l’irréparable.", "zh": "他的笑声对我来说，如同沙漠里的一口井。", "t": [100, 4212]}, {"fr": "Et je compris que je ne supportais pas l’idée de ne plus jamais entendre ce rire.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [4212, 8788]}, {"fr": "C’était pour moi comme une fontaine dans le désert.", "zh": "“小人儿，我还想听到你的笑声……” 但他对我说： “今夜是我到这儿的一周年。", "t": [8788, 11187]}]}, {"id": "ch26p31", "audio": true, "sents": [{"fr": "— Petit bonhomme, je veux encore t’entendre rire…", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [100, 3713]}]}, {"id": "ch26p32", "audio": true, "sents": [{"fr": "Mais il me dit :", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [100, 1650]}]}, {"id": "ch26p33", "audio": true, "sents": [{"fr": "— Cette nuit, ça fera un an.", "zh": "我的星星正好在我去年降落处的正上方……” “小人儿，蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [100, 3775]}, {"fr": "Mon étoile se trouvera juste au-dessus de l’endroit où je suis tombé l’année dernière…", "zh": "……” 但他不回答我的问题。", "t": [3775, 7800]}]}, {"id": "ch26p34", "audio": true, "sents": [{"fr": "— Petit bonhomme, n’est-ce pas que c’est un mauvais rêve cette histoire de serpent et de rendez-vous et d’étoile…", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [100, 6100]}]}, {"id": "ch26p35", "audio": true, "sents": [{"fr": "Mais il ne répondit pas à ma question.", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [100, 2812]}, {"fr": "Il me dit :", "zh": "他对我说： “最重要的东西，是肉眼看不到的……” “当然……” “花儿也是这样，如果你爱上了一朵长在一颗星星里的花儿，夜里看看星空，你会觉得甜蜜。", "t": [2812, 4162]}]}, {"id": "ch26p36", "audio": true, "sents": [{"fr": "— Ce qui est important, ça ne se voit pas…", "zh": "所有的星星都像开了花。", "t": [100, 3213]}]}, {"id": "ch26p37", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "所有的星星都像开了花。", "t": [100, 1825]}]}, {"id": "ch26p38", "audio": true, "sents": [{"fr": "— C’est comme pour la fleur.", "zh": "所有的星星都像开了花。", "t": [100, 3275]}, {"fr": "Si tu aimes une fleur qui se trouve dans une étoile, c’est doux, la nuit, de regarder le ciel.", "zh": "” “不错……” “水也是这样。", "t": [3275, 9112]}, {"fr": "Toutes les étoiles sont fleuries.", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [9112, 10576]}]}, {"id": "ch26p39", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "你给我喝的水，有了辘轳和绳子，水就如同音乐……你记得……它是甘甜的。", "t": [100, 1825]}]}, {"id": "ch26p40", "audio": true, "sents": [{"fr": "— C’est comme pour l’eau.", "zh": "” “不错。", "t": [100, 2888]}, {"fr": "Celle que tu m’as donnée à boire était comme une musique, à cause de la poulie et de la corde…", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [2888, 7425]}, {"fr": "tu te rappelles…", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [7425, 8425]}, {"fr": "elle était bonne.", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [8425, 9112]}]}, {"id": "ch26p41", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "” “夜里你仰望星空吧，我的那颗星太渺小，没法子告诉你它在哪儿。", "t": [100, 1825]}]}, {"id": "ch26p42", "audio": true, "sents": [{"fr": "— Tu regarderas, la nuit, les étoiles.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [100, 4500]}, {"fr": "C’est trop petit chez moi pour que je te montre où se trouve la mienne.", "zh": "这样更好……你就把我的星看做是万千星星中的一颗吧，这样你就会爱看所有的星星……它们全都成了你的朋友。", "t": [4500, 8412]}, {"fr": "C’est mieux comme ça.", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [8412, 10300]}, {"fr": "Mon étoile, ça sera pour toi une des étoiles.", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [10300, 14050]}, {"fr": "Alors, toutes les étoiles, tu aimeras les regarder…", "zh": "然后我会赠给你一份礼物……” 他还在笑。", "t": [14050, 18000]}, {"fr": "Elles seront toutes tes amies.", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [18000, 20175]}, {"fr": "Et puis je vais te faire un cadeau…", "zh": "“啊，小人儿，小人儿，我喜欢听你的笑声！", "t": [20175, 21562]}]}, {"id": "ch26p43", "audio": true, "sents": [{"fr": "Il rit encore.", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [100, 1013]}]}, {"id": "ch26p44", "audio": true, "sents": [{"fr": "— Ah !", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [100, 3038]}, {"fr": "petit bonhomme, petit bonhomme j’aime entendre ce rire !", "zh": "” “这正是我给你的礼物……这就和水一样……” “你想说什么？", "t": [3038, 6374]}]}, {"id": "ch26p45", "audio": true, "sents": [{"fr": "— Justement ce sera mon cadeau…", "zh": "” “不同的人有不同的星星。", "t": [100, 2812]}, {"fr": "ce sera comme pour l’eau…", "zh": "” “不同的人有不同的星星。", "t": [2812, 3874]}]}, {"id": "ch26p46", "audio": true, "sents": [{"fr": "— Que veux-tu dire ?", "zh": "” “不同的人有不同的星星。", "t": [100, 2587]}]}, {"id": "ch26p47", "audio": true, "sents": [{"fr": "— Les gens ont des étoiles qui ne sont pas les mêmes.", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [100, 4188]}, {"fr": "Pour les uns, qui voyagent, les étoiles sont des guides.", "zh": "星星是旅行的人的向导，星星只是其他人的小灯，星星是学者研究的问题，星星是我说过的那个商人的金子。", "t": [4188, 8112]}, {"fr": "Pour d’autres elles ne sont rien que de petites lumières.", "zh": "但所有的星星都沉默不语。", "t": [8112, 11288]}, {"fr": "Pour d’autres qui sont savants elles sont des problèmes.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [11288, 14325]}, {"fr": "Pour mon businessman elles étaient de l’or.", "zh": "你的那颗星星是别人没有的……” “你想说什么？", "t": [14325, 17150]}, {"fr": "Mais toutes ces étoiles-là se taisent.", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [17150, 19712]}, {"fr": "Toi, tu auras des étoiles comme personne n’en a…", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [19712, 22338]}]}, {"id": "ch26p48", "audio": true, "sents": [{"fr": "— Que veux-tu dire ?", "zh": "” “既然我住在天上一颗星星里，既然我在其中一颗星星里笑，这就如同所有的星星都在冲你笑，你就拥有无数会笑的星星了！", "t": [100, 2587]}]}, {"id": "ch26p49", "audio": true, "sents": [{"fr": "— Quand tu regarderas le ciel, la nuit, puisque j’habiterai dans l’une d’elles, puisque je rirai dans l’une d’elles, alors ce sera pour toi comme si riaient toutes les étoiles.", "zh": "“你得到了安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [100, 10462]}, {"fr": "Tu auras, toi, des étoiles qui savent rire !", "zh": "你会成为我永远的朋友，你会想与我一起笑。", "t": [10462, 13787]}]}, {"id": "ch26p50", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "你会成为我永远的朋友，你会想与我一起笑。", "t": [100, 1074]}]}, {"id": "ch26p51", "audio": true, "sents": [{"fr": "— Et quand tu seras consolé (on se console toujours) tu seras content de m’avoir connu.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [100, 6750]}, {"fr": "Tu seras toujours mon ami.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [6750, 9062]}, {"fr": "Tu auras envie de rire avec moi.", "zh": "有时候，当你想笑而打开窗户的时候……你的朋友看见你仰望星空独自发笑，他们一定会惊讶，你就对他们说：‘是的，我看见星星就要笑！", "t": [9062, 11688]}, {"fr": "Et tu ouvriras parfois ta fenêtre, comme ça, pour le plaisir…", "zh": "’他们会以为你神经出了毛病。", "t": [11688, 16162]}, {"fr": "Et tes amis seront bien étonnés de te voir rire en regardant le ciel.", "zh": "看来是我捉弄了你了……” 他还在笑。", "t": [16162, 20388]}, {"fr": "Alors tu leur diras : \"Oui, les étoiles, ça me fait toujours rire !\" Et ils te croiront fou.", "zh": "“这样一来，我给你的不是星星，而是一大批会笑的小铃铛……” 他还在笑。", "t": [20388, 28450]}, {"fr": "Je t’aurai joué un bien vilain tour…", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [28450, 30350]}]}, {"id": "ch26p52", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "然后他收敛了笑容： “今晚……你知道……你不要来了。", "t": [100, 1074]}]}, {"id": "ch26p53", "audio": true, "sents": [{"fr": "— Ce sera comme si je t’avais donné, au lieu d’étoiles, des tas de petits grelots qui savent rire…", "zh": "” “我不会离开你的。", "t": [100, 6050]}]}, {"id": "ch26p54", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [100, 1950]}, {"fr": "Puis il redevint sérieux :", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [1950, 3912]}]}, {"id": "ch26p55", "audio": true, "sents": [{"fr": "— Cette nuit…", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [100, 2000]}, {"fr": "tu sais…", "zh": "” “我会很难看的……会像个死人，别来看我的死了的样子，没有必要。", "t": [2000, 2650]}, {"fr": "ne viens pas.", "zh": "” “我不会离开你的。", "t": [2650, 3174]}]}, {"id": "ch26p56", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "” “我不会离开你的。", "t": [100, 2150]}]}, {"id": "ch26p57", "audio": true, "sents": [{"fr": "— J’aurai l’air d’avoir mal…", "zh": "” “我不会离开你的。", "t": [100, 9000]}, {"fr": "j’aurai un peu l’air de mourir.", "zh": "” 他露出忧心忡忡的神色。", "t": [9000, 9500]}, {"fr": "C’est comme ça.", "zh": "” 他露出忧心忡忡的神色。", "t": [9500, 10000]}, {"fr": "Ne viens pas voir ça, ce n’est pas la peine…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [10000, 10500]}]}, {"id": "ch26p58", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 2150]}]}, {"id": "ch26p59", "audio": true, "sents": [{"fr": "Mais il était soucieux.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 1225]}]}, {"id": "ch26p60", "audio": true, "sents": [{"fr": "— Je te dis ça…", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [100, 2100]}, {"fr": "c’est à cause aussi du serpent.", "zh": "“我跟你讲这些话……也是因为蛇，不该让它伤害你……蛇是凶残的动物，高兴时也咬人……” “我不离开你。", "t": [2100, 4375]}, {"fr": "Il ne faut pas qu’il te morde…", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [4375, 6638]}, {"fr": "Les serpents, c’est méchant.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [6638, 9038]}, {"fr": "Ça peut mordre pour le plaisir…", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [9038, 10700]}]}, {"id": "ch26p61", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "” 他想起什么，随即放宽了心： “真的，蛇咬的第二口不再有毒液……” 那天夜里我没看见他离开我。", "t": [100, 2150]}]}, {"id": "ch26p62", "audio": true, "sents": [{"fr": "Mais quelque chose le rassura :", "zh": "他是悄悄走的。", "t": [100, 2475]}]}, {"id": "ch26p63", "audio": true, "sents": [{"fr": "— C’est vrai qu’ils n’ont plus de venin pour la seconde morsure…", "zh": "他是悄悄走的。", "t": [100, 3800]}]}, {"id": "ch26p64", "audio": true, "sents": [{"fr": "Cette nuit-là je ne le vis pas se mettre en route.", "zh": "他大步走着，步子迈得又大又坚决。", "t": [100, 3238]}, {"fr": "Il s’était évadé sans bruit.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [3238, 5675]}, {"fr": "Quand je réussis à le rejoindre il marchait décidé, d’un pas rapide.", "zh": "他见了我，只说了一句：“呀，你在这儿……” 他牵住我的手。", "t": [5675, 10100]}, {"fr": "Il me dit seulement :", "zh": "然后他苦恼地说： “你不该来的。", "t": [10100, 11787]}]}, {"id": "ch26p65", "audio": true, "sents": [{"fr": "— Ah !", "zh": "然后他苦恼地说： “你不该来的。", "t": [100, 3038]}, {"fr": "tu es là…", "zh": "你会难过的。", "t": [3038, 3588]}]}, {"id": "ch26p66", "audio": true, "sents": [{"fr": "Et il me prit par la main.", "zh": "你会难过的。", "t": [100, 2125]}, {"fr": "Mais il se tourmenta encore :", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [2125, 4326]}]}, {"id": "ch26p67", "audio": true, "sents": [{"fr": "— Tu as eu tort.", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [100, 2975]}, {"fr": "Tu auras de la peine.", "zh": "我会像个死人，其实我不是真死……” 我不做声。", "t": [2975, 4975]}, {"fr": "J’aurai l’air d’être mort et ce ne sera pas vrai…", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [4975, 7263]}]}, {"id": "ch26p68", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "“你知道吧，路途太远，我拖不动这副皮囊，它太沉了。", "t": [100, 1112]}]}, {"id": "ch26p69", "audio": true, "sents": [{"fr": "— Tu comprends.", "zh": "” 我不做声。", "t": [100, 2738]}, {"fr": "C’est trop loin.", "zh": "” 我不做声。", "t": [2738, 4425]}, {"fr": "Je ne peux pas emporter ce corps-là.", "zh": "” 我不做声。", "t": [4425, 6938]}, {"fr": "C’est trop lourd.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [6938, 7825]}]}, {"id": "ch26p70", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [100, 1112]}]}, {"id": "ch26p71", "audio": true, "sents": [{"fr": "— Mais ce sera comme une vieille écorce abandonnée.", "zh": "“也不过如同蜕了旧壳，一副旧壳不值得悲哀……” 我还是不做声。", "t": [100, 4275]}, {"fr": "Ce n’est pas triste les vieilles écorces…", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [4275, 6088]}]}, {"id": "ch26p72", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 1112]}]}, {"id": "ch26p73", "audio": true, "sents": [{"fr": "Il se découragea un peu.", "zh": "他有点泄气了，但还在竭力安慰我： “你知道，想起你，我的心会温暖的。", "t": [100, 2362]}, {"fr": "Mais il fit encore un effort :", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [2362, 4463]}]}, {"id": "ch26p74", "audio": true, "sents": [{"fr": "— Ce sera gentil, tu sais.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [100, 3625]}, {"fr": "Moi aussi je regarderai les étoiles.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [3625, 6475]}, {"fr": "Toutes les étoiles seront des puits avec une poulie rouillée.", "zh": "以后我也会仰望星空，所有的星星会成了带有生锈辘轳的井，所有的星星给我倒水喝……” 我还是不做声。", "t": [6475, 10012]}, {"fr": "Toutes les étoiles me verseront à boire…", "zh": "“那会是多有趣的事情！", "t": [10012, 11987]}]}, {"id": "ch26p75", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "“那会是多有趣的事情！", "t": [100, 1112]}]}, {"id": "ch26p76", "audio": true, "sents": [{"fr": "— Ce sera tellement amusant !", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [100, 4062]}, {"fr": "Tu auras cinq cents millions de grelots, j’aurai cinq cents millions de fontaines…", "zh": "你会有五亿个小铃铛，我有五亿口井……” 他也不做声了，因为他哭了…… “就在这儿吧。", "t": [4062, 7650]}]}, {"id": "ch26p77", "audio": true, "sents": [{"fr": "Et il se tut aussi, parce qu’il pleurait…", "zh": "你让我独自走一步。", "t": [100, 2213]}]}, {"id": "ch26p78", "audio": true, "sents": [{"fr": "— C’est là.", "zh": "” 他坐了下来，因为他害怕了。", "t": [100, 2462]}, {"fr": "Laisse-moi faire un pas tout seul.", "zh": "” 他坐了下来，因为他害怕了。", "t": [2462, 4025]}]}, {"id": "ch26p79", "audio": true, "sents": [{"fr": "Et il s’assit parce qu’il avait peur.", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [100, 1750]}]}, {"id": "ch26p80", "audio": true, "sents": [{"fr": "Il dit encore :", "zh": "他还说： “你知道……我的花……我要对她负责！", "t": [100, 1600]}]}, {"id": "ch26p81", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "她弱不禁风！", "t": [100, 1900]}, {"fr": "ma fleur…", "zh": "她弱不禁风！", "t": [1900, 2638]}, {"fr": "j’en suis responsable !", "zh": "她聪明纯洁！", "t": [2638, 5200]}, {"fr": "Et elle est tellement faible !", "zh": "她一无所有！", "t": [5200, 7838]}, {"fr": "Et elle est tellement naïve.", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [7838, 9888]}, {"fr": "Elle a quatre épines de rien du tout pour la protéger contre le monde…", "zh": "只凭四根刺保护自己，抵御世上的侵害……” 我瘫坐在地上。", "t": [9888, 13063]}]}, {"id": "ch26p82", "audio": true, "sents": [{"fr": "Moi je m’assis parce que je ne pouvais plus me tenir debout.", "zh": "因为我站不住了。", "t": [100, 3712]}, {"fr": "Il dit :", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [3712, 4962]}]}, {"id": "ch26p83", "audio": true, "sents": [{"fr": "— Voilà…", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [100, 2450]}, {"fr": "C’est tout…", "zh": "他说： “我的话……讲完了……” 他还犹豫了片刻，然后站起来，向前走了一步。", "t": [2450, 2963]}]}, {"id": "ch26p84", "audio": true, "sents": [{"fr": "Il hésita encore un peu, puis il se releva.", "zh": "而我不能动弹。", "t": [100, 3462]}, {"fr": "Il fit un pas.", "zh": "而我不能动弹。", "t": [3462, 5038]}, {"fr": "Moi je ne pouvais pas bouger.", "zh": "他的脚踝边闪了一道黄光。", "t": [5038, 6487]}]}, {"id": "ch26p85", "audio": true, "sents": [{"fr": "Il n’y eut rien qu’un éclair jaune près de sa cheville.", "zh": "他凝然不动。", "t": [100, 3375]}, {"fr": "Il demeura un instant immobile.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [3375, 6100]}, {"fr": "Il ne cria pas.", "zh": "好一会儿之后，他像大树倒地似的倒下。", "t": [6100, 7812]}, {"fr": "Il tomba doucement comme tombe un arbre.", "zh": "因为这儿是沙地，他倒下去的时候，一点声音都没有。", "t": [7812, 10688]}, {"fr": "Ça ne fit même pas de bruit, à cause du sable.", "zh": "因为这儿是沙地，他倒下去的时候，一点声音都没有。", "t": [10688, 13288]}]}, {"id": "ch26p86", "audio": true, "sents": []}, {"id": "ch26p87", "audio": true, "sents": []}]}, {"id": "ch27", "title_fr": "Chapitre XXVII", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"fr": "Et maintenant, bien sûr, ça fait six ans déjà…", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [100, 3800]}, {"fr": "Je n’ai jamais encore raconté cette histoire.", "zh": "当然，这已是六年前的事了……我从来没对别人讲过这个故事。", "t": [3800, 7025]}, {"fr": "Les camarades qui m’ont revu ont été bien contents de me revoir vivant.", "zh": "我的同事们看见我活着回来，都替我庆幸。", "t": [7025, 11412]}, {"fr": "J’étais triste mais je leur disais : C’est la fatigue…", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [11412, 14850]}]}, {"id": "ch27p01", "audio": true, "sents": [{"fr": "Maintenant je me suis un peu consolé.", "zh": "我神色哀伤，但我告诉他们：“这是因为累……” 现在，我的离愁别绪已经减轻了一些。", "t": [100, 2825]}, {"fr": "C’est à dire…", "zh": "也就是说……还没有完全消除。", "t": [2825, 3800]}, {"fr": "pas tout à fait.", "zh": "也就是说……还没有完全消除。", "t": [3800, 5412]}, {"fr": "Mais je sais bien qu’il est revenu à sa planète, car, au lever du jour, je n’ai pas retrouvé son corps.", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [5412, 11825]}, {"fr": "Ce n’était pas un corps tellement lourd…", "zh": "我很明白，他回他的星球去了，因为天亮时我没找到他的尸体。", "t": [11825, 14400]}, {"fr": "Et j’aime la nuit écouter les étoiles.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [14400, 17062]}, {"fr": "C’est comme cinq cent millions de grelots…", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [17062, 18738]}]}, {"id": "ch27p02", "audio": true, "sents": [{"fr": "Mais voilà qu’il se passe quelque chose d’extraordinaire.", "zh": "他的躯体并不沉重……我喜欢在夜里倾听星星的呢喃，它们就像五亿个小铃铛…… 可是出了非同寻常的事了：我给小王子画了口罩，但我忘了给口罩配上皮带！", "t": [100, 3788]}, {"fr": "La muselière que j’ai dessinée pour le petit prince, j’ai oublié d’y ajouter la courroie de cuir !", "zh": "他别想把口罩套上羊嘴了。", "t": [3788, 10112]}, {"fr": "Il n’aura jamais pu l’attacher au mouton.", "zh": "我于是想：“他的星球发生了什么事呢？", "t": [10112, 13012]}, {"fr": "Alors je me demande : \"Que s’est-il passé sur sa planète ?", "zh": "绵羊很可能吃了花儿……” 有时我又想：“一定不会的！", "t": [13012, 18138]}, {"fr": "Peut-être bien que le mouton a mangé la fleur…\"", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [18138, 20537]}]}, {"id": "ch27p03", "audio": true, "sents": [{"fr": "Tantôt je me dis : \"Sûrement non !", "zh": "小王子每天夜里把他的花儿罩在玻璃罩里，他一定会看管好他的绵羊……”于是我放心了，天上所有的星星都温和地微笑。", "t": [100, 4162]}, {"fr": "Le petit prince enferme sa fleur toutes les nuits sous son globe de verre, et il surveille bien son mouton…\" Alors je suis heureux.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [4162, 12050]}, {"fr": "Et toutes les étoiles rient doucement.", "zh": "有时我想：“人总免不了有疏忽大意的时候，这就够糟的了！", "t": [12050, 13575]}]}, {"id": "ch27p04", "audio": true, "sents": [{"fr": "Tantôt je me dis : \"On est distrait une fois ou l’autre, et ça suffit !", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [100, 5938]}, {"fr": "Il a oublié, un soir, le globe de verre, ou bien le mouton est sorti sans bruit pendant la nuit…\" Alors les grelots se changent tous en larmes !…", "zh": "要是有天晚上他忘了给花罩上玻璃罩，或者绵羊在夜里悄悄地溜出来呢……”于是，铃铛全变成了泪珠…… 这件事始终是无法解开的谜。", "t": [5938, 14737]}]}, {"id": "ch27p05", "audio": true, "sents": [{"fr": "C’est là un bien grand mystère.", "zh": "在宇宙中不知哪个角落，我们不认识的绵羊有没有吃掉一朵玫瑰花，你们——喜爱小王子的人，和我一样，看法绝不相同…… 请你们仰望星空吧。", "t": [100, 2512]}, {"fr": "Pour vous qui aimez aussi le petit prince, comme pour moi, rien de l’univers n’est semblable si quelque part, on ne sait où, un mouton que nous ne connaissons pas a, oui ou non, mangé une rose…", "zh": "请你们问问自己：绵羊有没有吃掉花儿？", "t": [2512, 12587]}]}, {"id": "ch27p06", "audio": true, "sents": [{"fr": "Regardez le ciel.", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [100, 2112]}, {"fr": "Demandez-vous : le mouton oui ou non a-t-il mangé la fleur ?", "zh": "你们就会看到，天上所有的星星发生了变化…… 没有一个大人明白，弄清楚这个问题有多重要！", "t": [2112, 7462]}, {"fr": "Et vous verrez comme tout change…", "zh": "我认为这幅图画是世界上最凄美的图画了。", "t": [7462, 8912]}]}, {"id": "ch27p07", "audio": true, "sents": [{"fr": "Et aucune grande personne ne comprendra jamais que ça a tellement d’importance !", "zh": "它与前一幅的画面一样。", "t": [100, 4425]}]}, {"id": "ch27p08", "audio": true, "sents": [{"fr": "Ça c’est, pour moi, le plus beau et le plus triste paysage du monde.", "zh": "我再一次画它，是为了让你们好好地看看它。", "t": [100, 4912]}, {"fr": "C’est le même paysage que celui de la page précédente, mais je l’ai dessiné une fois encore pour bien vous le montrer.", "zh": "小王子就是在这里出现在地球上的，然后又是从这里离开了地球。", "t": [4912, 11600]}, {"fr": "C’est ici que le petit prince a apparu sur terre, puis disparu.", "zh": "请你们仔细看清楚这幅画，有朝一日你们到沙漠，到非洲旅行，才能认出这地方来。", "t": [11600, 14937]}]}, {"id": "ch27p09", "audio": true, "sents": [{"fr": "Regardez attentivement ce paysage afin d’être sûrs de le reconnaître, si vous voyagez un jour en Afrique, dans le désert.", "zh": "如果你经过这个地方，我恳求你们，别匆忙离去，请在那颗星下稍待片刻！", "t": [100, 7700]}, {"fr": "Et, s’il vous arrive de passer par là, je vous en supplie, ne vous pressez pas, attendez un peu juste sous l’étoile !", "zh": "如果有个孩子向你走过来；如果他笑吟吟的；如果他长着一头金发；如果你向他提问题，他不回答；你们就会猜到他是谁了。", "t": [7700, 15300]}, {"fr": "Si alors un enfant vient à vous, s’il rit, s’il a des cheveux d’or, s’il ne répond pas quand on l’interroge, vous devinerez bien qui il est.", "zh": "果真如此，请你们行行好！", "t": [15300, 23350]}, {"fr": "Alors soyez gentils !", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [23350, 26050]}, {"fr": "Ne me laissez pas tellement triste : écrivez-moi vite qu’il est revenu…", "zh": "别眼睁睁看着我为思念他而悲伤，别坐视不理，别无动于衷：请你们快点写信告诉我，他回来了…… 【注释】 [1] 美国的一个州。", "t": [26050, 29900]}]}, {"id": "ch27p10", "audio": true, "sents": []}]}]}